QB("tabari",5,0,[[1,1,"القول في تأويل قوله عز ذكره ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"يا أيها الذين آمنوا أوفوا\"، يا أيها الذين أقرّوا بوحدانية الله، وأذعنوا له بالعبودية، وسلموا له الألوهة [[في المطبوعة: \"الألوهية\"، وأثبت ما في المخطوطة.]] وصدَّقوا رسوله محمدًا ﷺ في نبوته وفيما جاءهم به من عند ربهم من شرائع دينه =\"أوفوا بالعقود\"، يعني: أوفوا بالعهود التي عاهدتموها ربَّكم، والعقود التي عاقدتموها إياه، وأوجبتم بها على أنفسكم حقوقًا، وألزمتم أنفسكم بها لله فروضًا، فأتمُّوها بالوفاء والكمال والتمام منكم لله بما ألزمكم بها، ولمن عاقدتموه منكم، بما أوجبتموه له بها على أنفسكم، ولا تنكُثُوها فتنقضوها بعد توكيدها. [[انظر تفسير\"أوفى\" فيما سلف ١: ٥٥٧/٣: ٣٤٨/٦: ٥٢٦.]]\n\n* *\n\nواختلف أهل التأويل في\"العقود\" التي أمر الله جل ثناؤه بالوفاء بها بهذه الآية، بعد إجماع جميعهم على أن معنى\"العقود\"، العهود.\n\nفقال بعضهم: هي العقود التي كان أهل الجاهلية عاقد بعضهم بعضًا على النُّصرة والمؤازرة والمظاهرة على من حاول ظلمه أو بغاه سوءًا، وذلك هو معنى\"الحلف\" الذي كانوا يتعاقدونه بينهم.\n\nذكر من قال: معنى\"العقود\"، العهود.\n\n١٠٨٩٣- حدثني المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية بن صالح، عن علي، عن ابن عباس قوله:\"أوفوا بالعقود\"، يعني: بالعهود.\n\n١٠٨٩٤- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله جل وعز:\"أوفوا بالعقود\"، قال: العهود.\n\n١٠٨٩٥- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١٠٨٩٦- حدثنا سفيان قال، حدثنا أبي، عن سفيان، عن رجل، عن مجاهد، مثله. [[الأثر: ١٠٨٩٦- في المخطوطة: \"حدثنا سفيان قال، حدثنا ابن أبي سفيان، عن رجل ... \" وهو خطأ وسهو، وهو إسناد دائر في التفسير: سفيان بن وكيع، عن أبيه وكيع، عن سفيان الثوري.]]\n\n١٠٨٩٧- حدثنا ابن وكيع قال، حدثنا عبيد الله، عن أبي جعفر الرازي، عن الربيع بن أنس قال: جلسنا إلى مطرّف بن الشخِّير وعنده رجل يحدثهم، فقال:\"يا أيها الذين آمنوا أوفوا بالعقود\"، قال: هي العهود. [[الأثر: ١٠٨٩٧-\"عبيد الله\"، هو\"عبيد الله بن موسى بن أبي المختار العبسي\"\"باذام\"، مضت ترجمته برقم: ٢٠٩٢، ٢٢١٩، ٥٧٩٦، ٧٧٥٨. وكان في المطبوعة هنا: \"عبيد الله عن ابن أبي جعفر الرازي\"، وهو خطأ سيأتي على الصواب في الأسانيد التالية رقم: ١٠٩٣٥، ١٠٩٥٧، ١٠٩٦٣.]]\n\n١٠٨٩٨- حدثنا المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع:\"أوفوا بالعقود\"، قال: العهود.\n\n١٠٨٩٩- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك:\"يا أيها الذين آمنوا أوفوا بالعقود\"، قال: هي العهود.\n\n١٠٩٠٠- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سليمان قال، سمعت الضحاك يقول:\"أوفوا بالعقود\"، بالعهود.\n\n١٠٩٠١- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق، عن معمر، عن قتادة في قوله:\"أوفوا بالعقود\"، قال: بالعهود.\n\n١٠٩٠٢- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"أوفوا بالعقود\"، قال: هي العهود.\n\n١٠٩٠٣- حدثني الحارث قال، حدثنا عبد العزيز قال، سمعت الثوري يقول:\"أوفوا بالعقود\"، قال: بالعهود.\n\n١٠٩٠٤- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج، عن مجاهد، مثله.\n\n* *\n\nقال أبو جعفر: و\"العقود\" جمع\"عَقْدٍ\"، وأصل\"العقد\"، عقد الشيء بغيره، وهو وصله به، كما يعقد الحبل بالحبلِ، إذا وصل به شدًّا. يقال منه:\"عقد فلان بينه وبين فلان عقدًا، فهو يعقده\"، ومنه قول الحطيئة:\n\nقَوْمٌ إذَا عَقَدُوا عَقْدًا لِجَارِهِمُ ... شَدُّوا العِنَاجَ وَشَدُّوا فَوْقَهُ الْكَرَبَا [[ديوانه: ٦، مجاز القرآن لأبي عبيدة ١: ١٤٥، اللسان (كرب) (عنج) ، من قصيدته التي قالها في الزبرقان بن بدر، وبغيض بن عامر من بني أنف الناقة، فمدح بغيضًا وقومه فقال: قَوْمٌ هُمُ الأَنْفُ، وَالأَذْنَابُ غَيْرهُمُ، ... وَمَنْ يُسَوِّي بِأَنْفِ النَّاقَةِ الذَّنَبَا!\n\nقَوْمٌ يَبِيتُ قَرِيرَ العَيْنِ جَارُهُمُ ... إذَا لَوَى بقُوَى أَطْنَابِهِمْ طُنُبَا\n\nقَوْمٌ إذَا عَقَدُوا........ ... . . . . . . . . . . . . . . . . . . .\n\nهذا مثل ضربه يقول: إذا عقدوا للجار عقدًا وذمامًا، أحكموا على أنفسهم العقد، حتى يكون أقر عينًا بنصرتهم له، وحمايتهم لعرضه وماله. وضرب المثل بالدلو، التي يستقي بها وينتفع. و\"العناج\": خيط يشد في أسفل الدلو، ثم يشد في عروتها، أو في أحد آذانها، فإذا انقطع حبل الدلو، أمسك العناج الدلو أن تقع في البئر. و\"الكرب\" الحبل الذي يشد على الدلو بعد\"المنين\" وهو الحبل الأول، فإذا انقطع المنين بقي الكرب. فهذا هو المثل، استوثقوا له بالعهد، كما استوثقوا لدلوه بالحبل بعد الحبل حتى تكون بمأمن من القطع.]] وذلك إذا وَاثقه على أمر وعاهده عليه عهدًا بالوفاء له بما عاقده عليه، من أمان وذِمَّة، أو نصرة، أو نكاح، أو بيع، أو شركة، أو غير ذلك من العقود.\n\n* *\n\nذكر من قال المعنى الذي ذكرنا عمن قاله في المراد من قوله:\"أوفوا بالعقود\".\n\n١٠٩٠٥- حدثنا بشر بن معاذ قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة في قوله:\"يا أيها الذين آمنوا أوفوا بالعقود\"، أي: بعقد الجاهلية. ذُكر لنا أن نبيَّ الله ﷺ كان يقول: أوفوا بعقد الجاهلية، ولا تحدثوا عقدًا في الإسلام. وذكر لنا أن فرات بن حيَّان العِجلي، سأل رسول الله ﷺ عن حلف الجاهلية، فقال نبي الله ﷺ: لعلك تسأل عن حِلْف لخْمٍ وتَيْم الله؟ فقال: نعم، يا نبي الله! قال: لا يزيده الإسلام إلا شدة.\n\n١٠٩٠٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، حدثنا معمر، عن قتادة:\"أوفوا بالعقود\"، قال: عقود الجاهلية: الحلف.\n\n* *\n\nوقال آخرون: بل هي الحلف التي أخذ الله على عباده بالإيمان به وطاعته، فيما أحل لهم وحرم عليهم.\n\nذكر من قال ذلك:\n\n١٠٩٠٧- حدثني المثنى قال، أخبرنا عبد الله قال، حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس قوله:\"أوفوا بالعقود\"، يعني: ما أحل وما حرّم، وما فرض، وما حدَّ في القرآن كله، فلا تغدِروا ولا تنكُثوا. ثم شدَّد ذلك فقال: ﴿وَالَّذِينَ يَنْقُضُونَ عَهْدَ اللَّهِ مِنْ بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ﴾ إلى قوله: ﴿سُوءُ الدَّارِ﴾ [سورة الرعد: ٣٥] .\n\n١٠٩٠٨- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد:\"أوفوا بالعقود\"، ما عقد الله على العباد مما أحل لهم وحرَّم عليهم.\n\n* *\n\nوقال آخرون: بل هي العقود التي يتعاقدها الناس بينهم، ويعقدها المرء على نفسه.\n\nذكر من قال ذلك:\n\n١٠٩٠٩- حدثنا سفيان بن وكيع قال، حدثني أبي، عن موسى بن عبيدة، عن أخيه عبد الله بن عبيدة قال: العقود خمس: عُقدة الأيمان، وعُقدة النكاح، وعقدة العَهد، وعقدة البيع، وعقدة الحِلْف.\n\n١٠٩١٠- حدثنا القاسم قال، حدثنا الحسين قال، حدثنا وكيع، عن موسى بن عبيدة، عن محمد بن كعب القرظي = أو عن أخيه عبد الله بن عبيدة، نحوه.\n\n١٠٩١١- حدثني يونس بن عبد الأعلى قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"يا أيها الذين آمنوا أوفوا بالعقود\"، قال: عقد العهد، وعقد اليمين وعَقد الحِلْف، وعقد الشركة، وعقد النكاح. قال: هذه العقود، خمس.\n\n١٠٩١٢- حدثني المثنى قال، حدثنا عتبة بن سعيد الحمصي قال، حدثنا عبد الرحمن بن زيد بن أسلم قال، حدثنا أبي في قول الله جل وعز:\"يا أيها الذين آمنوا أوفوا بالعقود\"، قال: العقود خمس: عقدة النكاح، وعقدة الشركة، وعقد اليمين، وعقدة العهد، وعقدة الحلف. [[الأثر ١٠٩١٢-\"عتبة بن سعيد الحمصي\" مضى برقم: ٨٩٦٦.]]\n\n* *\n\nوقال آخرون: بل هذه الآية أمرٌ من الله تعالى لأهل الكتاب بالوفاء بما أخذ به ميثاقهم، من العمل بما في التوراة والإنجيل في تصديق محمد ﷺ وما جاءهم به من عند الله.\n\nذكر من قال ذلك:\n\n١٠٩١٣- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج:\"أوفوا بالعقود\"، قال: العهود التي أخذها الله على أهل الكتاب: أن يعملوا بما جاءهم.\n\n١٠٩١٤- حدثني المثنى قال، حدثنا أبو صالح قال، حدثني الليث قال، حدثني يونس قال، قال محمد بن مسلم: قرأت كتاب رسول الله ﷺ الذي كتب لعمرو بن حزم حين بعثه على نَجْران [[في المطبوعة: \"بعثه إلى نجران\"، وأثبت ما في المخطوطة.]] فكان الكتاب عند أبي بكر بن حزم، فيه:\"هذا بيان من الله ورسوله:\"يا أيها الذين آمنوا أوفوا بالعقود\"، فكتب الآيات منها حتى بلغ\"إن الله سريع الحساب\". [[الأثر: ١٠٩١٤- روى كتاب رسول الله ﷺ، أبو جعفر في التاريخ ٣: ١٥٧، وهو في سيرة ابن هشام ٤: ٢٤١، وفتوح البلدان للبلاذري: ٧٧، وغيرها.]]\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في ذلك عندنا بالصواب، ما قاله ابن عباس، وأن معناه: أوفوا، يا أيها الذين آمنوا، بعقود الله التي أوجبَهَا عليكم، وعقدها فيما أحلَّ لكم وحرم عليكم، وألزمكم فرضه، وبيَّن لكم حدوده.\n\nوإنما قلنا ذلك أولى بالصواب من غيره من الأقوال، لأن الله جل وعز أتبع ذلك البيانَ عما أحل لعباده وحرم عليهم، وما أوجب عليهم من فرائضه. فكان معلومًا بذلك أن قوله:\"أوفوا بالعقود\"، أمرٌ منه عبادَه بالعمل بما ألزمهم من فرائضه وعقوده عقيب ذلك، ونَهْيٌ منه لهم عن نقض ما عقده عليهم منه، مع أن قوله:\"أوفوا بالعقود\"، أمرٌ منه بالوفاء بكل عقد أذن فيه، فغير جائز أن يخصَّ منه شيء حتى تقوم حجة بخصوص شيء منه يجب التسليم لها. فإذْ كان الأمر في ذلك كما وصفنا، فلا معنى لقول من وجَّه ذلك إلى معنى الأمر بالوفاء ببعض العقود التي أمرَ الله بالوفاء بها دون بعض.\n\n* *\n\nوأما قوله:\"أوفوا\" فإن للعرب فيه لغتين:\n\nإحداهما:\"أوفوا\"، من قول القائل:\"أوفيت لفلان بعهده، أوفي له به\".\n\nوالأخرى من قولهم:\"وفيت له بعهده أفي\". [[انظر تفسير\"أوفى\" فيما سلف ١: ٥٥٧-٥٥٩/٣: ٣٤٨/٦: ٥٢٦.]]\n\nو\"الإيفاء بالعهد\"، إتمامه على ما عقد عليه من شروطه الجائزة.\n\n* *\n\nالقول في تأويل قوله: ﴿أُحِلَّتْ لَكُمْ بَهِيمَةُ الأنْعَامِ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في\"بهيمة الأنعام\" التي ذكر الله عز ذكره في هذه الآية أنه أحلها لنا.\n\nفقال بعضهم: هي الأنعام كلها.\n\nذكر من قال ذلك:\n\n١٠٩١٥- حدثنا سفيان بن وكيع قال، حدثنا عبد الأعلى، عن عوف، عن الحسن قال: بهيمة الأنعام، هي الإبل والبقر والغنم.\n\n١٠٩١٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:\"أحلت لكم بهيمة الأنعام\"، قال: الأنعام كلها.\n\n١٠٩١٧- حدثنا محمد بن الحسين قال، حدثنا ابن مفضل قال، حدثنا أسباط، عن السدي:\"أحلت لكم بهيمة الأنعام\"، قال: الأنعام كلها.\n\n١٠٩١٨- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع بن أنس في قوله:\"أحلت لكم بهيمة الأنعام\"، قال: الأنعام كلها. [[سقط من الترقيم، رقم: ١٠٩١٩.]]\n\n١٠٩٢٠- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سليمان قال، سمعت الضحاك يقول في قوله:\"بهيمة الأنعام\"، هي الأنعام.\n\n* *\n\nوقال آخرون: بل عنى بقوله:\"أحلت لكم بهيمة الأنعام\"، أجنة الأنعام التي توجد في بطون أمهاتها -إذا نحرت أو ذبحت- ميتةً.\n\nذكر من قال ذلك:\n\n١٠٩٢١- حدثني الحارث بن محمد قال، حدثنا عبد العزيز قال، أخبرنا أبو عبد الرحمن الفزاري، عن عطية العوفي، عن ابن عمر في قوله:\"أحلت لكم بهيمة الأنعام\". قال: ما في بطونها. قال قلت: إن خرج ميتًا أكله؟ قال: نعم.\n\n١٠٩٢٢- حدثنا القاسم قال، حدثنا الحسين قال، حدثنا يحيى بن زكريا، عن إدريس الأودي، عن عطية، عن ابن عمر نحوه = وزاد فيه قال: نعم، هو بمنزلة رئتها وكبدها.\n\n١٠٩٢٣- حدثنا ابن حميد وابن وكيع قالا حدثنا جرير، عن قابوس، عن أبيه، عن ابن عباس قال: الجنين من بهيمة الأنعام، فكلوه.\n\n١٠٩٢٤- حدثنا ابن وكيع قال، حدثنا أبي، عن مسعر = وسفيان، عن قابوس = عن أبيه، عن ابن عباس: أن بقرة نحرت فوُجد في بطنها جنين، فأخذ ابن عباس بذنَب الجنين فقال: هذا من بهيمة الأنعام التي أحلّت لكم.\n\n١٠٩٢٥- حدثنا أبو كريب قال، حدثنا ابن يمان، عن سفيان، عن قابوس، عن أبيه، عن ابن عباس قال: هو من بهيمة الأنعام.\n\n١٠٩٢٦- حدثنا ابن بشار قال، حدثنا أبو عاصم ومؤمل قالا حدثنا سفيان، عن قابوس، عن أبيه قال: ذبحنا بقرة، فإذا في بطنها جنين، فسألنا ابن عباس فقال: هذه بهيمة الأنعام.\n\n* *\n\nقال أبو جعفر: وأولى القولين بالصواب في ذلك، قول من قال: عنى بقوله:\"أحلت لكم بهيمة الأنعام\"، الأنعام كلها: أجنَّتها وسِخَالها وكبارها. [[\"السخال\" جمع\"سخلة\" (بفتح فسكون) : وهي ولد الشاة من المعز والضأن، ذكرًا كان أو أنثى.]] لأن العرب لا تمتنع من تسمية جميع ذلك\"بهيمة وبهائم\"، ولم يخصص الله منها شيئًا دون شيء. فذلك على عمومه وظاهره، حتى تأتى حجة بخصوصه يجب التسليم لها.\n\n* *\n\nوأما\"النعم\" فإنها عند العرب، اسم للإبل والبقر والغنم خاصة، كما قال جل ثناؤه: ﴿وَالأنْعَامَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَافِعُ وَمِنْهَا تَأْكُلُونَ﴾ ، [سورة النحل: ٥] ، ثم قال: ﴿وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً﴾ [سورة النحل: ٨] ، ففصل جنس النعم من غيرها من أجناس الحيوان. [[انظر تفسير\"الأنعام\" فيما سلف ٦: ٢٥٤.]]\n\nوأما\"بهائمها\"، فإنها أولادها. وإنما قلنا يلزم الكبار منها اسم\"بهيمة\"، كما يلزم الصغار، لأن معنى قول القائل:\"بهيمة الأنعام\"، نظير قوله:\"ولد الأنعام\". فلما كان لا يسقط معنى الولادة عنه بعد الكبر، فكذلك لا يسقط عنه اسم البهيمة بعد الكبر.\n\n* *\n\nوقد قال قوم:\"بهيمة الأنعام\"، وحشيُّها، كالظباء وبقر الوحش والحُمُر. [[هي مقالة الفراء في معاني القرآن ١: ٢٩٨.]]\n\n* *\n\nالقول في تأويل قوله: ﴿إِلا مَا يُتْلَى عَلَيْكُمْ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في الذي عناه الله بقوله:\"إلا ما يتلى عليكم\". فقال بعضهم: عنى الله بذلك: أحلت لكم أولاد الإبل والبقر والغنم، إلا ما بيَّن الله لكم فيما يتلى عليكم بقوله: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ﴾ ، الآية [سورة المائدة: ٣] .\n\nذكر من قال ذلك:\n\n١٠٩٢٧- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد:\"بهيمة الأنعام إلا ما يتلى عليكم\"، إلا الميتة وما ذكر معها.\n\n١٠٩٢٨- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم\"، أي: من الميتة التي نهى الله عنها، وقدَّم فيها.\n\n١٠٩٢٩- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة:\"إلا ما يتلى عليكم\"، قال: إلا الميتة وما لم يذكر اسم الله عليه.\n\n١٠٩٣٠- حدثني محمد بن الحسين قال، حدثنا أحمد بن مفضل قال، حدثنا أسباط، عن السدي:\"إلا ما يتلى عليكم\"، الميتة والدم ولحم الخنزير.\n\n١٠٩٣١- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي بن أبي طلحة، عن ابن عباس:\"أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم\"، الميتة ولحم الخنزير.\n\n١٠٩٣٢- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي بن أبي طلحة، عن ابن عباس:\"أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم\"، هي الميتة والدم ولحم الخنزير وما أُهِلَّ لغير الله به.\n\n* *\n\nوقال آخرون: بل الذي استثنى الله بقوله:\"إلا ما يتلى عليكم\"، الخنزير.\n\nذكر من قال ذلك:\n\n١٠٩٣٣- حدثني عبد الله بن داود قال، حدثنا عبد الله بن صالح قال، حدثني معاوية، عن علي، عن ابن عباس:\"إلا ما يتلى عليكم\"، قال: الخنزير.\n\n١٠٩٣٤- حدثت عن الحسين قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سليمان قال، سمعت الضحاك يقول في قوله:\"إلا ما يتلى عليكم\"، يعني: الخنزير.\n\n* *\n\nقال أبو جعفر: وأولى التأويلين في ذلك بالصواب، تأويل من قال:\"عنى بذلك: إلا ما يتلى عليكم من تحريم الله ما حرّم عليكم بقوله:\"حرمت عليكم الميتة\"، الآية. لأن الله عز وجل استثنى مما أباح لعباده من بهيمة الأنعام، ما حرَّم عليهم منها. والذي حرّم عليهم منها، ما بيّنه في قوله: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزيرِ﴾ [سورة المائدة: ٣] . وإن كان حرَّمه الله علينا، فليس من بهيمة الأنعام فيستثنى منها. فاستثناء ما حرَّم علينا مما دخل في جملة ما قبل الاستثناء، أشبهُ من استثناء ما حرَّم مما لم يدخل في جملة ما قبل الاستثناء.\n\n* *\n\nالقول في تأويل قوله: ﴿غَيْرَ مُحِلِّي الصَّيْدِ وَأَنْتُمْ حُرُمٌ إِنَّ اللَّهَ يَحْكُمُ مَا يُرِيدُ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في تأويل ذلك.\n\nفقال بعضهم: معنى ذلك:\"يا أيها الذين آمنوا أوفوا بالعقود\" =\"غير محلي الصيد وأنتم حرم\" =\"أحلت لكم بهيمة الأنعام\" فذلك، على قولهم، من المؤخر الذي معناه التقديم. فـ\"غير\" منصوب = على قول قائلي هذه المقالة = على الحال مما في قوله:\"أوفوا\" من ذكر\"الذين آمنوا\".\n\nوتأويل الكلام على مذهبهم: أوفوا، أيها المؤمنون، بعقود الله التي عقدها عليكم في كتابه، لا محلّين الصيد وأنتم حرم.\n\n* *\n\nوقال آخرون: معنى ذلك: أحلت لكم بهيمة الأنعام الوحشية من الظباء والبقر والحمر =\"غير محلي الصيد\"، غير مستحلِّي اصطيادها، وأنتم حرم إلا ما يتلى عليكم\". فـ\"غير\"، على قول هؤلاء، منصوب على الحال من\"الكاف والميم\" اللتين في قوله:\"لكم\"، بتأويل: أحلت لكم، أيها الذين آمنوا، بهيمة الأنعام، لا مستحلِّي اصطيادها في حال إحرامكم. [[انظر معاني القرآن للفراء ١: ٢٩٨.]]\n\n* *\n\nوقال آخرون: معنى ذلك: أحلت لكم بهيمة الأنعام كلها =\"إلا ما يتلى عليكم\"، إلا ما كان منها وحشيًّا، فإنه صيد، فلا يحل لكم وأنتم حرم. فكأن من قال ذلك، وجَّه الكلام إلى معنى: أحلت لكم بهيمة الأنعام كلها =\"إلا ما يتلى عليكم\"، إلا ما يبين لكم من وحشيها، غيرَ مستحلي اصطيادها في حال إحرامكم. فتكون\"غير\" منصوبة، على قولهم، على الحال من\"الكاف والميم\" في قوله:\"إلا ما يتلى عليكم\".\n\nذكر من قال ذلك:\n\n١٠٩٣٥- حدثنا سفيان بن وكيع قال، حدثنا عبيد الله، عن أبي جعفر الرازي، عن الربيع بن أنس قال: جلسنا إلى مطرِّف بن الشخير، وعنده رجل، فحدّثهم فقال:\"أحلت لكم بهيمة الأنعام\" صيدًا =\"غير محلي الصيد وأنتم حرم\"، فهو عليكم حرام. يعني: بقر الوحش والظباءَ وأشباهه. [[انظر الإسناد السالف رقم: ١٠٨٩٧، وكان هناك عن\"ابن أبي جعفر الرازي\"، وهذا هو الإسناد الصحيح، صححت ذلك عليه. وسيأتي برقم: ١٠٩٥٧، ١٠٩٦٣.]]\n\n١٠٩٣٦- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع بن أنس في قوله:\"أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم غير محلي الصيد وأنتم حرم\"، قال: الأنعام كلها حِلٌّ، إلا ما كان منها وحشيًّا، فإنه صيد، فلا يحل إذا كان مُحْرِمًا.\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في ذلك بالصواب = على ما تظاهر به تأويل أهل التأويل في قوله:\"أحلت لكم بهيمة الأنعام\"، من أنها الأنعام وأجنَّتها وسخالها، وعلى دلالة ظاهر التنزيل = قولُ من قال: معنى ذلك: أوفوا بالعقود، غيرَ محلي الصيد وأنتم حرم، فقد أحلت لكم بهيمة الأنعام في حال إحرامكم أو غيرها من أحوالكم، إلا ما يتلى عليكم تحريمه من الميتة منها والدم، وما أهل لغير الله به.\n\nوذلك أن قوله:\"إلا ما يتلى عليكم\"، لو كان معناه:\"إلا الصيد\"، لقيل:\"إلا ما يتلى عليكم من الصيد غير محليه\". وفي ترك الله وَصْلَ قوله:\"إلا ما يتلى عليكم\" بما ذكرت، وإظهار ذكر الصيد في قوله:\"غير محلي الصيد\"، أوضحُ الدليل على أن قوله:\"إلا ما يتلى عليكم\"، خَبَرٌ متناهية قصته، وأن معنى قوله:\"غير محلي الصيد\"، منفصل منه.\n\nوكذلك لو كان قوله: ﴿أحلت لكم بهيمة الأنعام﴾ ، مقصودًا به قصد الوحش، لم يكن أيضًا لإعادة ذكر الصيد في قوله:\"غير محلي الصيد\" وَجْهٌ، وقد مضى ذكره قبل، ولقيل:\"أحلت لكم بهيمة الأنعام إلا ما يتلى عليكم غير محلِّيه وأنتم حرم\". وفي إظهاره ذكر الصيد في قوله:\"غير محلي الصيد\"، أبينُ الدلالة على صحة ما قلنا في معنى ذلك.\n\n* *\n\nفإن قال قائل: فإن العرب ربما أظهرت ذكر الشيء باسمه وقد جرى ذكره باسمه؟ قيل: ذلك من فعلها ضرورة شعر، وليس ذلك بالفصيح المستعمل من كلامهم. وتوجيه كلام الله إلى الأفصح من لغات من نزل كلامه بلغته، أولى = ما وُجد إلى ذلك سبيل = من صرفه إلى غير ذلك.\n\n* *\n\nقال أبو جعفر: فمعنى الكلام إذًا: يا أيها الذين آمنوا أوفوا بعقود الله التي عقد عليكم مما حرّم وأحلّ، لا محلين الصيد في حرمكم، ففيما أحلَّ لكم من بهيمة الأنعام المذكَّاة دون ميتتها، متَّسع لكم ومستغنًى عن الصيد في حال إحرامكم.\n\n* *\n\nالقول في تأويل قوله: ﴿إِنَّ اللَّهَ يَحْكُمُ مَا يُرِيدُ (١) ﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: إن الله يقضي في خلقه ما يشاء [[انظر تفسير\"حكم\" فيما سلف: ص ٣٢٤: تعليق: ٣.]] من تحليل ما أراد تحليله، وتحريم ما أراد تحريمه، وإيجاب ما شاء إيجابه عليهم، وغير ذلك من أحكامه وقضاياه = فأوفوا، أيها المؤمنون، له بما عقدَ عليكم من تحليل ما أحل لكم وتحريم ما حرّم عليكم، وغير ذلك من عقوده، فلا تنكثوها ولا تنقضوها. كما:-\n\n١٠٩٣٧- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"إن الله يحكم ما يريد\"، إن الله يحكم ما أراد في خلقه، وبيّن لعباده، وفرض فرائضه، وحدَّ حدوده، وأمر بطاعته، ونهى عن معصيته.\n\n* *\n\nالقول في تأويل قوله: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لا تُحِلُّوا شَعَائِرَ اللَّهِ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في معنى قول الله:\"لا تحلوا شعائر الله\".\n\nفقال بعضهم معناه: لا تحلوا حُرُمات الله، ولا تتعدَّوا حدوده = كأنهم وجهوا\"الشعائر\" إلى المعالم، وتأولوا\"لا تحلوا شعائر الله\"، معالم حدود الله، وأمرَه ونهيَه وفرائضَه.\n\n[ذكر من قال ذلك] : [[ما بين القوسين زيادة ليست في المخطوطة ولا المطبوعة، وأثبتها على نهج أبي جعفر في تفسيره.]]\n\n١٠٩٣٨- حدثنا ابن وكيع قال، حدثنا عبد الوهاب الثقفي قال، حدثنا حبيب المعلم، عن عطاء: أنه سئل عن\"شعائر الله\" فقال: حُرُمات الله، اجتناب سَخَطِ الله، واتباع طاعته، فذلك\"شعائر الله\".\n\n* *\n\nوقال آخرون: معنى ذلك: [[في المطبوعة والمخطوطة: \"معنى قوله\"، وهو لا يستقيم، وما أثبت أشبه بالصواب.]] لا تحلوا حَرَم الله = فكأنهم وجهوا معنى قوله:\"شعائر الله\"، أي: معالم حرم الله من البلاد.\n\nذكر من قال ذلك:\n\n١٠٩٣٩- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\"، قال: أما\"شعائر الله\"، فحرَم الله.\n\n* *\n\nوقال آخرون: معنى ذلك: لا تحلّوا مناسك الحج فتضيعوها = وكأنهم وجَّهوا تأويل ذلك إلى: لا تحلوا معالم حدود الله التي حدَّها لكم في حجِّكم.\n\nذكر من قال ذلك:\n\n١٠٩٤٠- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج قال، قال ابن جريج، قال ابن عباس قوله:\"لا تحلوا شعائر الله\"، قال: مناسك الحج.\n\n١٠٩٤١- حدثني المثنى قال، حدثنا أبو صالح قال، حدثنا معاوية، عن علي بن أبي طلحة، عن ابن عباس قوله:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\"، قال: كان المشركون يحجّون البيت الحرام، ويهدُون الهدايا، ويعظِّمون حرمة المشاعر، ويتَّجرون في حجهم، فأراد المسلمون أن يُغَيِّروا عليهم، فقال الله عز وجل:\"لا تحلوا شعائر الله\".\n\n١٠٩٤٢- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله:\"شعائر الله\"، الصفا والمروة، والهَدْي، والبُدْن، كل هذا من\"شعائر الله\".\n\n١٠٩٤٣- حدثني المثنى قال، حدثني أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n* *\n\nوقال آخرون: معنى ذلك: لا تحلوا ما حرَّم الله عليكم في حال إحرامكم.\n\nذكر من قال ذلك:\n\n١٠٩٤٤- حدثنا محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قوله:\"لا تحلوا شعائر الله\"، قال:\"شعائر الله\"، ما نهى الله عنه أن تصيبه وأنت محرِم.\n\n* *\n\n= وكأن الذين قالوا هذه المقالة، وجَّهوا تأويل ذلك إلى: لا تحلوا معالم حدود الله التي حرّمها عليكم في إحرامكم.\n\n* *\n\nقال أبو جعفر: وأولى التأويلات بقوله:\"لا تحلوا شعائر الله\"، قول عطاء الذي ذكرناه [[هو الأثر السالف رقم: ١٠٩٣٨.]] من توجيهه معنى ذلك إلى: لا تحلوا حرمات الله ولا تضيعوا فرائضه.\n\n* *\n\nلأن\"الشعائر\" جمع\"شعيرة\"،\"والشعيرة\"\"فعيلة\" من قول القائل:\"قد شعر فلان بهذا الأمر\"، إذا علم به. فـ\"الشعائر\"، المعالم، من ذلك. [[انظر تفسير\"شعائر الله\" فيما سلف ٣: ٢٢٦-٢٢٨.]]\n\n* *\n\nوإذا كان ذلك كذلك، كان معنى الكلام: لا تستحلوا، أيها الذين آمنوا، معالم الله = فيدخل في ذلك معالم الله كلها في مناسك الحج: من تحريم ما حرَّم الله إصابته فيها على المحرم، وتضييع ما نهى عن تضييعه فيها، وفيما حرَّم من استحلال حُرمات حَرَمه، وغير ذلك من حدوده وفرائضه، وحلاله وحرامه، لأن كل ذلك من معالمه وشعائره التي جعلها أماراتٍ بين الحق والباطل، يُعْلَم بها حلالُه وحرامه، وأمره ونهيه.\n\nوإنما قلنا ذلك القول أولى بتأويل قوله تعالى:\"لا تحلوا شعائر الله\"، لأن الله نهى عن استحلال شعائره ومعالم حدوده وإحلالها نهيًا عامًّا، من غير اختصاص شيء من ذلك دون شيء، فلم يَجُز لأحد أن يوجِّه معنى ذلك إلى الخصوص إلا بحجة يجب التسليم لها، ولا حجة بذلك كذلك."],[2,2,"القول في تأويل قوله: ﴿وَلا الشَّهْرَ الْحَرَامَ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"ولا الشهر الحرام\"، ولا تستحلوا الشهر الحرام بقتالكم فيه أعداءَكم من المشركين [[في المطبوعة: \"بقتالكم به\"، والصواب من المخطوطة.]] وهو كقوله: ﴿يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ﴾ [سورة البقرة: ٢١٧] .\n\n* *\n\nوبنحو الذي قلنا في ذلك قال ابن عباس وغيره.\n\nذكر من قال ذلك:\n\n١٠٩٤٥- حدثني المثنى قال، حدثنا أبو صالح قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"ولا الشهر الحرام\"، يعني: لا تستحلوا قتالا فيه.\n\n١٠٩٤٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة قال: كان المشرك يومئذ لا يُصَدُّ عن البيت، فأمروا أن لا يقاتلوا في الشهر الحرام ولا عند البيت.\n\n* *\n\nوأما\"الشهر الحرام\" الذي عناه الله بقوله:\"ولا الشهر الحرام\"، فرجب مُضَر، وهو شهر كانت مضر تحرِّم فيه القتال.\n\n* *\n\nوقد قيل: هو في هذا الموضع\"ذو القعدة\".\n\nذكر من قال ذلك:\n\n١٠٩٤٧- حدثنا القاسم قال، حدثنا الحسين قال، حدثنا حجاج، عن ابن جريج، عن عكرمة قال: هو ذو القعدة.\n\n* *\n\nوقد بينا الدلالة على صحة ما قلنا في ذلك فيما مضى، وذلك في تأويل قوله:\"يسألونك عن الشهر الحرام قتال فيه\". [[انظر ما سلف في\"الشهر الحرام\" ٤: ٢٢٩، ٣٠٠، وما بعدها، وهو الموضع الذي ذكره، ثم قبله ٣: ٥٧٥-٥٧٩. وتفسير\"الشهر\" فيما سلف ٣: ٤٤٠.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَلا الْهَدْيَ وَلا الْقَلائِدَ﴾\n\nقال أبو جعفر:\"أما الهدي\"، فهو ما أهداه المرء من بعيرٍ أو بقرة أو شاة أو غير ذلك، إلى بيت الله، تقرُّبا به إلى الله، وطلبَ ثوابه. [[انظر تفسير\"الهدي\" فيما سلف ٤: ٢٤، ٢٥.]]\n\n* *\n\nيقول الله عز وجل: فلا تستحلوا ذلك، فتغصبوه أهله غَلَبةً [[في المطبوعة: \"فتغصبوا أهله عليه\"، وفي المخطوطة كما كتبتها، إلا أن كتب\"عليه\" بالياء، ووضع فتحة على العين، وفتحة على اللام، وظاهر أن\"الياء\" إنما هي\"باء\"، وأن الناسخ لما رآها مضبوطة في النسخة الأم نقل الشكل، ووضع الإعجام من عند نفسه. هذا وصواب الكلام يقتضي أيضًا ما أثبت.]] ولا تحولوا بينهم وبين ما أهدوا من ذلك أن يبلُغوا به المحِلَّ الذي جعله الله جل وعزّ مَحِلَّه من كعبته.\n\nوقد روي عن ابن عباس أن\"الهدي\" إنما يكون هديًا ما لم يُقَلَّد.\n\n١٠٩٤٨- حدثني بذلك محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قوله:\"ولا الهدي\"، قال: الهدي ما لم يقلَّد، وقد جعل على نفسه أن يهديه ويقلِّده.\n\n* *\n\nوأما قوله:\"ولا القلائد\"، فإنه يعني: ولا تحلوا أيضًا القلائد.\n\n* *\n\nثم اختلف أهل التأويل في\"القلائد\" التي نهى الله عز وجل عن إحلالها.\n\nفقال بعضهم: عنى بـ \"القلائد\"، قلائدَ الهدي. وقالوا: إنما أراد الله جل وعز بقوله:\"ولا الهدي ولا القلائد\"، ولا تحلوا الهدايا المقلَّدات منها وغير المقلَّدات. فقوله:\"ولا الهدي\"، ما لم يقلّد من الهدايا =\"ولا القلائد\"، المقلّد منها. قالوا: ودلّ بقوله:\"ولا القلائد\"، على معنى ما أراد من النهي عن استحلال الهدايا المقلّدة.\n\nذكر من قال ذلك:\n\n١٠٩٤٩- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قوله:\"ولا القلائد\"، القلائد، مقلَّدات الهدي. وإذا قلَّد الرجل هديه فقد أحرم. فإن فعل ذلك وعليه قميصه، فليخلَعْه.\n\n* *\n\nوقال آخرون: يعني بذلك: القلائد التي كان المشركون يتقلدونها إذا أرادوا الحج مقبلين إلى مكة، من لِحَاء السَّمُر [[\"لحاء الشجرة\" (بكسر اللام) : قشرها. و\"السمر\" (بفتح السين وضم الميم) : ضرب من الشجر، صغار الورق، قصار الشوك، وله برمة صفراء يأكلها الناس، وليس في العضاء شيء أجود خشبًا منه. ينقل إلى القرى، فتغمى به البيوت.]] = وإذا خرجوا منها إلى منازلهم منصرفين منها، من الشَّعَر.\n\nذكر من قال ذلك:\n\n١٠٩٥٠- حدثني الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة:\"لا تحلوا شعائر الله ولا الشهر الحرام\"، قال: كان الرجل في الجاهلية إذا خرج من بيته يريد الحج، تقلَّد من السَّمُر، فلم يعرض له أحد. فإذا رجع تقلَّد قِلادة شَعَر، فلم يعرض له أحد.\n\n* *\n\nوقال آخرون: بل كان الرجل منهم يتقلّد = إذا أراد الخروج من الحرم، أو خرج = من لحاء شجر الحرم، فيأمن بذلك من سائر قبائل العرب أن يعرضوا له بسوء.\n\nذكر من قال ذلك:\n\n١٠٩٥١- حدثنا ابن وكيع قال، حدثنا أبي، عن مالك بن مغول، عن عطاء:\"ولا القلائد\"، قال: كانوا يتقلدون من لحاء شجر الحرم، يأمنون بذلك إذا خرجوا من الحرم، فنزلت:\"لا تحلوا شعائر الله\"، الآية،\"ولا الهدي ولا القلائد\".\n\n١٠٩٥٢- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد:\"ولا القلائد\"، قال:\"القلائد\"، اللحاء في رقاب الناس والبهائم، أمْنٌ لهم.\n\n١٠٩٥٣- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١٠٩٥٤- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي، قوله:\"ولا الهدي ولا القلائد\"، قال: إن العرب كانوا يتقلدون من لحاء شجر مكة، فيقيم الرجل بمكانه، حتى إذا انقضت الأشهر الحرم، فأراد أن يرجع إلى أهله، قلَّد نفسه وناقته من لحاء الشجر، فيأمن حتى يأتي أهله.\n\n١٠٩٥٥- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله: \"ولا القلائد\"، قال:\"القلائد\"، كان الرجل يأخذ لحاء شجرة من شجر الحرم، فيتقلدها، ثم يذهب حيث شاء، فيأمن بذلك. فذلك\"القلائد\".\n\n* *\n\nوقال آخرون: إنما نهى الله المؤمنين بقوله:\"ولا القلائد\"، أن ينزعوا شيئًا من شجر الحرم فيتقلّدوه، كما كان المشركون يفعلون في جاهليتهم.\n\nذكر من قال ذلك:\n\n١٠٩٥٦- حدثنا ابن حميد قال، حدثنا جرير، عن عبد الملك، عن عطاء في قوله:\"ولا الهدي ولا القلائد\"، كان المشركون يأخذون من شجر مكة، من لحاء السَّمُر، فيتقلدونها، فيأمنون بها من الناس. فنهى الله أن ينزع شجرها فَيُتَقَلَّد.\n\n١٠٩٥٧- حدثنا ابن وكيع قال، حدثنا عبيد الله، عن أبي جعفر الرازي، عن الربيع بن أنس قال: جلسنا إلى مُطرِّف بن الشخير، وعنده رجل فحدّثهم في قوله:\"ولا القلائد\"، قال: كان المشركون يأخذون من شجر مكة، من لِحاء السمر، فيتقلدون، فيأمنون بها في الناس. فنهى الله عز ذكره أن يُنزع شجرها فيتقلَّد.\n\n* *\n\nقال أبو جعفر: والذي هو أولى بتأويل قوله:\"ولا القلائد\" = إذ كانت معطوفة على أول الكلام، ولم يكن في الكلام ما يدلّ على انقطاعها عن أوله، ولا أنه عنى بها النهي عن التقلد أو اتخاذ القلائد من شيء = أن يكون معناه: ولا تُحِلّوا القلائد.\n\nفإذا كان ذلك بتأويله أولى، فمعلوم أنه نَهْيٌ من الله جل ذكره عن استحلال حرمة المقلَّد، هديًا كان ذلك أو إنسانًا، دون حرمة القلادة. وإن الله عز ذكره، إنما دلّ بتحريمه حرمة القلادة، على ما ذكرنا من حرمة المقلَّد، فاجتزأ بذكره \"القلائد\" من ذكر\"المقلد\"، إذ كان مفهومًا عند المخاطبين بذلك معنى ما أريد به.\n\n* *\n\nفمعنى الآية = إذ كان الأمر على ما وصفنا =: يا أيها الذين آمنوا لا تحلوا شعائر الله، ولا الشهر الحرام، ولا الهدي، ولا المقلِّد نفسَه بقلائد الحرم. [[في المطبوعة: \"ولا المقلد بقسميه\"، وهو لا معنى له، والصواب ما في المخطوطة. يعني: الذي يقلد نفسه قلادة من شجر أو شعر، ليأمن، كما ذكر آنفًا، وانظر الفقرة التالية.]]\n\n* *\n\nوقد ذكر بعض الشعراء في شعره ما ذكرنا عمن تأوَّل\"القلائد\" أنها قلائد لحاء شجر الحرم الذي كان أهل الجاهلية يتقلَّدونه، فقال وهو يعيب رجلين قتلا رجلين كانا تقلَّدا ذلك: [[القائل هو حذيفة بن أنس الهذلي.]]\n\nأَلَمْ تَقْتُلا الْحِرْجَيْنِ إذْ أَعْوَراكُمَا ... يُمِرَّانِ بِالأيْدِي اللِّحَاءَ الْمُضَفَّرَا [[أشعار الهذليين ٣: ١٩، والمعاني الكبير: ١١٢٠، واللسان (حرج) . و\"الحرج\" (بكسر الحاء وسكون الراء) : الودعة، قالوا: عنى بالحرجين: رجلين أبيضين كالودعة، فإما أن يكون البياض لونهما، وإما أن يكون كنى بذلك عن شرفهما. وقال شارح ديوانه: \"ويكون أيضًا الحرجان، رجلين يقال لهما: الحرجان\". و\"أمر الحبل يمره\": فتله. و\"اللحاء\"، قشر الشجر. و\"المضفر\" الذي جدل ضفائر.\n\nهذا وقد ذكر أبو جعفر أن الشعر في رجلين قتلا رجلين، وروى\"ألم تقتلا\"، والذي في المراجع\"ألم تقتلوا\"، وهو الذي يدل عليه سياق الشعر، فإن أوله قبل البيت: ألا أبْلِغَا جُلَّ السَّوَارِي وَجابرًا ... وَأَبْلِغْ بَني ذِي السَّهْم عَنِّي وَيَعْمَرَا\n\nوَقُولا لَهُمْ عَنِّي مَقَالَةَ شَاعِرٍ ... أَلَمّ بقَوْلٍ، لَمْ يُحَاوِلْ لِيَفْخَرَا\n\nلَعَلَّكُمْ لَمَّا قَتَلْتُمْ ذَكَرْتُمُ ... وَلَنْ تَتْرُكُوا أَنْ تَقْتُلُوا، مَنْ تَعَمَّرَا\n\nفالشعر كله بضمير الجمع. وسببه أن جندبًا، أخو البريق بن عياض اللحياني، قتل قيسًا وسالمًا ابني عامر بن عريب الكنانيين، وقتل سالم جندبًا، اختلفا ضربتين.]]\n\nو\"الحرجان\"، المقتولان كذلك. ومعنى قوله:\"أعوراكما\"، أمكناكما من عورتهما. [[رواية أبي جعفر كما شرحها\"أعوراكما\"، ورواية الديوان\"أعورا لكم\"، وهي في سياق لمشعر، ورواية اللسان: \"أعرضا لكم\"، ويروي\"عورا لكم\" بتشديد الواو. هذا على أن هذه الرواية: \"أعور\" متعديًا، والذي كتب في اللغة\"أعور لك الشيء فهو معور\".]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَلا آمِّينَ الْبَيْتَ الْحَرَامَ يَبْتَغُونَ فَضْلا مِنْ رَبِّهِمْ وَرِضْوَانًا﴾ [[كان في المطبوعة والمخطوطة: \"ولا آمين البيت الحرام\"، ولم يأت بقية ما شرح من الآية في هذا الموضع. فزدت ما شرحه هنا. هذا على أنه سيعود إلى شرحه مرة أخرى في ص: ٤٧٩. وهذا غريب جدًا، لا أدري كيف وقع لأبي جعفر، فلعله نسي، أو أخذه ما يأخذه الناس من التعب عند هذا الموضع، ثم عاد إليه فلم يغير، ثم ابتدأ الكلام في تفسير بقية الآية، وترك ما مضى.]]\n\nقال أبو جعفر: يعني بقوله عز ذكره:\"ولا آمين البيت الحرام\"، ولا تحلُّوا قاصدي البيت الحرام العامدية. [[في المطبوعة والمخطوطة: \"ولا تحلوا قاصدين البيت\"، وهو خطأ، كما يدل عليه السياق. والصواب ما أثبته.]]\n\n* *\n\nتقول منه:\"أممت كذا\"، إذا قصدته وعمدته، وبعضهم يقول:\"يَمَمْته\" [[انظر تفسير\"أم يؤم\" فيما سلف ٥: ٥٥٨/٨: ٤٠٧. وقوله: \"يممته\" ثلاثي، بفتح الياء والميم الأولى وسكون الثانية: مثل\"ضربت\".]] كما قال الشاعر: [[لم أعرف قائله.]]\n\nإنِّي كَذَاكَ إذَا مَا سَاءَنِي بَلَدٌ ... يَمَمْتُ صَدْرَ بَعِيرِي غَيْرَهُ بَلَدَا [[مجاز القرآن لأبي عبيدة ١: ١٤٦.]]\n\n* *\n\n\"والبيت الحرام\"، بيت الله الذي بمكة، وقد بينت فيما مضى لم قيل له\"الحرام\". [[انظر ما سلف ٣: ٤٤-٥١.]]\n\n* *\n\n=\"يبتغون فضلا من ربهم\"، يعني: يلتمسون أرباحًا في تجاراتهم من الله =\"ورضوانًا\"، يقول: وأن يرضى الله عنهم بنسكهم.\n\n* *\n\nوقد قيل: إن هذه الآية نزلت في رجل من بني ربيعة يقال له:\"الحُطَمُ\".\n\nذكر من قال ذلك:\n\n١٠٩٥٨- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي قال: أقبل الحُطم بن هند البكري، ثم أحد بني قيس بن ثعلبة [[\"الحطم\" لقب، واسمه: \"شريح بن ضبيعة بن شرحبيل بن عمرو بن مرثد بن سعد بن مالك بن ضبيعة بن قيس بن ثعلبة، من بكر بن وائل\" (جمهرة الأنساب: ٣٠١) ، وهذا\"الحطم\"، خرج في الردة، في السنة الحادية عشرة، فيمن تبعه من بكر بن وائل، ومن تأشب إليه من غير المرتدين ممن لم يزل كافرًا، فخرج بهم حتى نزل القطيف وهجر، واستغوى الخط، ومن فيها من الزط والسيابجة. وحاصر المسلمين حصارًا شديدًا. فتجمع المسلمون جميعًا إلى العلاء بن الحضرمي، وتجمع المشركون كلهم إلى الحطم. ثم بيتهم المسلمون وقتلوا الحطم ومن معه في خبر طويل (انظر تاريخ الطبري ٣: ٢٥٤-٢٦٠) .\n\nوقوله هنا: \"الحطم بن هند\"، أتى بذكر أمه من الشعر الآتي، واسم أبيه هو ما مر بك آنفًا، وهي: \"هند بنت حسان بن عمرو بن مرثد\" (رغبة الآمل ٤: ٧٥) .]] حتى أتى النبي ﷺ وحده، وخَلَّف خيله خارجة من المدينة. فدعاه، فقال: إلام تدعو؟ فأخبره = وقد كان النبي ﷺ قال لأصحابه: يدخل اليوم عليكم رجل من ربيعة، يتكلم بلسان شيطان! = فلما أخبره النبي ﷺ قال: انظر، ولعلّي أسلم [[في المطبوعة والمخطوطة: \"انظروا لعلي أسلم\"، وليس بشيء، والصواب ما أثبت، ويؤيده كلامه الآتي في الخبر التالي.]] ولي من أشاوره. فخرج من عنده، فقال رسول الله ﷺ، لقد دخل بوجه كافر، وخرج بعَقِب غادرٍ! فمرَّ بسَرْح من سَرْح المدينة فساقه، فانطلق به وهو يرتجز [[اختلفوا في نسبة هذا الشعر اختلافًا كثيرًا، فنقل التبريزي في شرح الحماسة (١: ١٨٥) خبر رشيد بن رميض العنزي (بفتح العين، وسكون النون) من بني عنز بن وائل، بلا شك عندي في ذلك. قال التبريري: \"قالها في غارة الحطم، وهو شريح بن شرحبيل بن عمرو بن مرثد، أغار على اليمن، فقتل وليعة بن معد يكرب، أخا قيس، وسبى بنت قيس بن معد يكرب، أخت الأشعث بن قيس، فبعث الأشعث يعرض عليه في فدائها، بكل قرن من قرونها (ضفائرها) مئة من الإبل. فلم يفعل الحطم، وماتت عنده عطشًا. (وانظر غير ذلك في الأغاني ١٤: ٤٤) .\n\nونسبت أيضًا للأغلب العجلي، وللأخنس بن شهاب، ولجابر بن حني التغلبي. وانظر ذلك في تحقيق أستاذنا الراجكوتي، سمط اللآلئ: ٧٢٩. ولعل\"الحطم\" أنشده مدحًا لنفسه فيما فعل من سوق السرح.]]\n\nقَدْ لَفَّهَا اللَّيْلُ بِسَوَّاقٍ حُطَمْ ... لَيْسَ بِرَاعِي إبِلٍ وَلا غَنَم ... وَلا بِجَزَّارٍ على ظَهْرِ الوَضَمْ ... بَاتُوا نِيَامًا وَابْنُ هِنْدٍ لَمْ يَنَمْ ... بَاتَ يُقَاسِيهَا غُلامٌ كَالزَّلَمْ ... خَدَلَّجُ السَّاقَيْنِ مَمْسُوحُ القَدَمْ [[البيان والتبيين ٢: ٣٠٨، الأغاني ١٤: ٤٤، حماسة أبي تمام ١: ١٨٤، حماسة ابن الشجري: ٣٨، الكامل ١: ٢٢٤ (ونسبه للحطم في ص: ٢٢٧) ، الخيل لابن الأعرابي ٨٦، واللسان (حطم) وغيرها، وقبل هذا الرجز: هذَا أوانُ الشَّدِّ، فَاشْتَدِّي زِيَمْ\n\nو\"زيم\" اسم فرس. وقوله: \"حطم\" شديد الحطم، فقالوا: للسائق الذي لا يبقى شيئًا من السير والإسراع\"حطم\". و\"الوضم\" ما يوقي به اللحم عند تقطيعه من خشب أو غيره. و\"الزلم\" (بفتح الزاي واللام، أو بضم الزاي) ، واحد\"الأزلام\"، وهي قداح الميسر. يعني: هو كالقدح في صلابته ونحافته وملاسته. و\"خدلج الساقين\": ممتلئ الساقين، وهذا غير حسن في الرجال، وإنما صواب روايته ما رواه ابن الأعرابي: مُهَفْهَفُ الْكَشْحَيْنِ خَفَّاقُ القَدَمْ\n\nأي ضامر الخصر. و\"خفاق القدم\"، لأقدامه خفق متتابع على الأرض من سرعته وهو يحدو بالإبل. ورواية أبي جعفر\"ممسوح القدم\": أي ليس لباطن قدمه أخمص، فأسفل قدمه مستو أملس لين، ليس فيهما تكسر ولا شقاق. وقد جاء في صفة رسول الله ﷺ: \"مسيح القدمين\".]]\n\nثم أقبل من عام قابلٍ حاجًّا قد قلَّد وأهدى، فأراد رسول الله ﷺ أن يبعث إليه، فنزلت هذه الآية، حتى بلغ:\"ولا آمين البيت الحرام\". قال له ناس من أصحابه: يا رسول الله، خلِّ بيننا وبينه، فإنه صاحبنا! قال: إنه قد قلَّد! قالوا: إنما هو شيء كنا نصنعه في الجاهلية! فأبى عليهم، فنزلت هذه الآية.\n\n١٠٩٥٩- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج، عن عكرمة قال: قدم الحُطَم، أخو بني ضُبيعة بن ثعلبة البكري، المدينةَ في عِير له يحمل طعامًا، فباعه. ثم دخل على النبي ﷺ فبايعه وأسلم. فلما ولى خارجًا، نظر إليه فقال لمن عنده: لقد دخل عليّ بوجهٍ فاجرٍ، وولّى بقفا غادرٍ! فلما قدم اليمامة ارتدَّ عن الإسلام، وخرج في عير له تحمل الطعام في ذي القعدة يريد مكة. فلما سمع به أصحاب رسول الله ﷺ، تهيَّأ للخروج إليه نفر من المهاجرين والأنصار ليقتطعوه في عِيره، فأنزل الله عز وجل:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\"، الآية، فانتهى القوم.\n\n= قال ابن جريج قوله:\"ولا آمين البيت الحرام\"، قال: ينهى عن الحجاج أن تُقطع سبلهم. قال: وذلك أن الحطم قدِم على النبي ﷺ ليرتاد وينظر، فقال: إني داعية قوم [[في المطبوعة: \"داعية قومي\"، وأثبت ما في المخطوطة، وهما سواء.]] فاعرض عليّ ما تقول. قال له: أدعوك إلى الله أن تعبده ولا تشرك به شيئًا، وتقيم الصلاة، وتؤتي الزكاة، وتصوم شهر رمضان، وتحج البيت. قال الحطم: في أمرك هذا غلظة، أرجع إلى قومي فأذكر لهم ما ذكرت، فإن قبلوه أقبلتُ معهم، وإن أدبروا كنت معهم. قال له: ارجع. فلما خرج قال: لقد دخل عليّ بوجه كافرٍ، وخرج من عندي بعَقِبَى غادر، وما الرجل بمسلم! فمرَّ على سَرْح لأهل المدينة فانطلق به، فطلبه أصحابُ رسول الله ﷺ ففاتهم، وقدم اليمامة، وحضر الحج، فجهّز خارجًا، وكان عظيم التجارة، فاستأذنوا أن يتلقَّوه ويأخذوا ما معه، فأنزل الله عز وجل:\"لا تحلّوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام\".\n\n١٠٩٦٠- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"ولا آمين البيت الحرام\" الآية، قال: هذا يوم الفتح، جاء ناسٌ يؤمُّون البيت من المشركين يُهِلُّون بعمرة، فقال المسلمون: يا رسول الله، إنما هؤلاء مشركون كمثل هؤلاء [[في المطبوعة: \"فمثل هؤلاء\"، وصواب قراءتها من المخطوطة، كما أثبت.]] فلن ندعهم إلا أن نغير عليهم. فنزل القرآن:\"ولا آمين البيت الحرام\".\n\n١٠٩٦١- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس:\"ولا آمين البيت الحرام\"، يقول: من توجَّه حاجًّا.\n\n١٠٩٦٢- حدثني المثنى قال، حدثنا عمرو بن عون قال، أخبرنا هشيم، عن جويبر، عن الضحاك في قوله:\"ولا آمين البيت الحرام\"، يعني: الحاج. [[الأثر: ١٠٩٦٢-\"عمرو بن عون بن أوس الواسطي\"، مضت ترجمته برقم: ٥٤٣٥، ومضى في آثار أخرى كثيرة، رواية المثنى عنه، عن هشيم فيما سلف، مثل: ٣١٥٩، ٣٨٧٩. وكان في المخطوطة والمطبوعة: \"عمرو بن عوف\"، وهو تحريف. وسيأتي على الصواب قريبًا برقم: ١٠٩٦٩.]]\n\n١٠٩٦٣- حدثنا ابن وكيع قال، حدثنا عبيد الله بن موسى، عن أبي جعفر الرازي، عن الربيع بن أنس قال: جلسنا إلى مطرِّف بن الشخّير وعنده رجل، فحدثهم فقال:\"ولا آمين البيت الحرام\"، قال: الذين يريدون البيت.\n\n* *\n\nثم اختلف أهل العلم فيما نسخ من هذه الآية، بعد إجماعهم على أن منها منسوخًا.\n\nفقال بعضهم: نسخ جميعها.\n\nذكر من قال ذلك:\n\n١٠٩٦٤- حدثنا ابن وكيع قال، حدثنا جرير، عن بيان، عن عامر، قال: لم ينسخ من المائدة إلا هذه الآية:\"لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد\".\n\n١٠٩٦٥- حدثنا ابن وكيع قال، حدثنا يزيد بن هارون، عن سفيان بن حسين، عن الحكم، عن مجاهد:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\"، نسختها، ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ ، [سورة التوبة: ٥] .\n\n١٠٩٦٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا الثوري، عن بيان، عن الشعبي قال، لم ينسخ من سورة المائدة غير هذه الآية:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\".\n\n١٠٩٦٧- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:\"لا تحلوا شعائر الله ولا الشهر الحرام\" الآية، قال: منسوخ. قال: كان المشرك يومئذ لا يُصَدُّ عن البيت، فأمروا أن لا يقاتلوا في الأشهر الحُرم، ولا عند البيت، فنسخها قوله: ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ . [[الأثر: ١٠٩٦٧- هو تمام الأثر السالف رقم: ١٠٩٥٠ وسيأتي برقم: ١٠٩٧٦، خبرًا واحدًا، ورواه أبو جعفر النحاس في الناسخ والمنسوخ: ١١٥.]]\n\n١٠٩٦٨- حدثنا ابن وكيع قال، حدثنا أبو معاوية، عن جويبر، عن الضحاك:\"لا تحلوا شعائر الله\" إلى قوله:\"ولا آمين البيت الحرام\"، قال: نسختها\"براءة\": ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ .\n\n١٠٩٦٩- حدثني المثنى قال، حدثنا عمرو بن عون قال، حدثنا هشيم، عن الضحاك، مثله.\n\n١٠٩٧٠- حدثنا ابن حميد وابن وكيع قالا حدثنا جرير، عن منصور، عن حبيب بن أبي ثابت:\"لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد\"، قال: هذا شيء نهي عنه، فترك كما هو. [[الأثر: ١٠٩٧٠-\"جرير\"، هو\"جرير بن عبد الحميد الضبي\"، مضى مرارًا. وكان في المطبوعة: \"جويبر\"، وهو خطأ فاحش، والصواب من المخطوطة.]]\n\n١٠٩٧١- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"يا أيها الذين آمنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام\"، قال: هذا كله منسوخ، نسخ هذا أمرُه بجهادهم كافة. [[يعني قوله تعالى: ﴿وَقَاتِلُوا المُشْرِكينَ كَافَّةً كَمَا يُقَاتِلُونَكُمْ كَافَّةً﴾ [سورة التوبة: ٣٦]]]\n\n* *\n\nوقال آخرون: الذي نسخ من هذه الآية قوله:\"ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام\".\n\nذكر من قال ذلك:\n\n١٠٩٧٢- حدثنا ابن وكيع قال، حدثنا عبدة بن سليمان قال، قرأت على ابن أبي عروبة فقال: هكذا سمعته من قتادة: نسخ من\"المائدة\":\"آمين البيت الحرام\"، نسختها\"براءة\" قال الله: ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ ، وقال: ﴿مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَسَاجِدَ اللَّهِ شَاهِدِينَ عَلَى أَنْفُسِهِمْ بِالْكُفْرِ﴾ [سورة التوبة: ١٧] ، وقال: ﴿إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا﴾ [سورة التوبة: ٢٧] ، وهو العام الذي حج فيه أبو بكر، فنادى فيه بالأذان. [[في المخطوطة: \"فنادى عليه بالأذان\" وفوق\"عليه\"\"فيه\". ويعني بالأذان، قوله تعالى: ﴿وَأَذَانٌ مِنَ اللهِ وَرَسُولِهِ إلَى الناسِ يَوْمَ الحَجِّ الأَكْبَرِ أَنَّ اللهَ بَرِيءٌ منَ الْمُشْرِكِينَ وَرَسُولُهُ﴾ ، [سورة التوبة: ٢] .]]\n\n١٠٩٧٣- حدثني المثنى قال، حدثنا الحجاج بن المنهال قال، حدثنا همام بن يحيى، عن قتادة قوله:\"يا أيها الذين آمنوا لا تحلوا شعائر الله\" الآية، قال: فنسخ منها:\"آمين البيت الحرام\"، نسختها\"براءة\"، فقال: ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ ، فذكر نحو حديث عبدة.\n\n١٠٩٧٤- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي قال: نزل في شأن الحُطم:\"ولا الهدي ولا القلائد ولا آمين البيت الحرام\"، ثم نسخه الله فقال: ﴿وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ﴾ [[انظر خبر\"الحطم\" فيما سلف رقم: ١٠٩٥٨، ١٠٩٥٩.]] [سورة البقرة: ١٩١] .\n\n١٠٩٧٥- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"لا تحلوا شعائر الله\" إلى قوله:\"ولا آمين البيت\"، [فكان المؤمنون والمشركون يحجون إلى البيت] جميعًا، فنهى الله المؤمنين أن يمنعوا أحدًا أن يحجّ البيت أو يعرضوا له، من مؤمن أو كافر، ثم أنزل الله بعد هذا: ﴿إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا﴾ ، وقال: ﴿مَا كَانَ لِلْمُشْرِكِينَ أَنْ يَعْمُرُوا مَسَاجِدَ اللَّهِ﴾ ، وقال: ﴿إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الآخِرِ﴾ [سورة التوبة: ١٨] ، فنفى المشركين من المسجد الحرام. [[الأثر: ١٠٩٧٥- ما بين القوسين، زيادة من رواية أبي جعفر النحاس في الناسخ والمنسوخ: ١١٥، حيث روى هذا الأثر بهذا الإسناد نفسه، والكلام بغيرها لا يستقيم.]]\n\n١٠٩٧٦- حدثنا الحسن بن يحيى قال: أخبرنا عبد الرزاق قال: أخبرنا معمر، عن قتادة في قوله:\"لا تحلوا شعائر الله ولا الشهر الحرام\"، الآية، قال: منسوخ، كان الرجل في الجاهلية إذا خرج من بيته يريد الحج، تقلَّد من السَّمُر فلم يعرض له أحد. وإذا رجع، تقلَّد قلادة شَعَرٍ فلم يعرض له أحد. وكان المشرك يومئذ لا يُصَدُّ عن البيت. وأمروا أن لا يقاتلوا في الأشهر الحُرُم، ولا عند البيت، فنسخها قوله:\"فاقتلوا المشركين حيث وجدتموهم \". [[الأثر: ١٠٩٧٦- هو ما جاء في الأثرين السالفين: ١٠٩٥٠، ١٠٩٦٧.]]\n\n* *\n\nوقال آخرون: لم ينسخ من ذلك شيء، إلا القلائد التي كانت في الجاهلية يتقلَّدونها من لِحَاء الشجر.\n\nذكر من قال ذلك:\n\n١٠٩٧٧- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قوله:\"لا تحلوا شعائر الله ولا الشهر الحرام\"، الآية، قال أصحاب محمد ﷺ: هذا كله من عمل الجاهلية فِعله وإقامته، فحرَّم الله ذلك كله بالإسلام، إلا لحاء القلائد، فترك ذلك [[يعني فجعلها الله إحلالها حرامًا في الإسلام إلا لحاء القلائد، فإنه قد نسخ.]] =\"ولا آمين البيت الحرام\"، فحرم الله على كل أحد إخافتهم.\n\n١٠٩٧٨- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في ذلك بالصحة، قول من قال: نسخ الله من هذه الآية قوله:\"ولا الشهر الحرام ولا الهدي ولا القلائد ولا آمين البيت الحرام\"، لإجماع الجميع على أن الله قد أحلّ قتال أهل الشرك في الأشهر الحرم وغيرها من شهور السنة كلها. وكذلك أجمعوا على أن المشرك لو قَلَّد عنقه أو ذراعيه لحاء جميع أشجار الحرم، لم يكن ذلك له أمانًا من القتل، إذا لم يكن تقدَّم له عقد ذمة من المسلمين أو أمان = وقد بينا فيما مضى معنى\"القلائد\" في غير هذا الموضع. [[انظر ما سلف ص: ٤٦٧-٤٧٠.]]\n\nوأما قوله:\"ولا آمين البيت الحرام\"، فإنه محتمل ظاهره: ولا تحلوا حُرْمة آمِّين البيت الحرام من أهل الشرك والإسلام، لعموم جميع من أمَّ البيت. وإذا احتمل ذلك، فكان أهل الشرك داخلين في جملتهم، فلا شك أن قوله: ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ ، ناسخٌ له. لأنه غير جائز اجتماع الأمر بقتلهم وترك قتلهم في حال واحدة ووقت واحد. وفي إجماع الجميع على أن حكم الله في أهل الحرب من المشركين قتلُهم، أمُّوا البيت الحرام أو البيت المقدس، في أشهر الحرم وغيرها = ما يُعلم أن المنع من قتلهم إذا أموا البيت الحرام منسوخٌ. ومحتمل أيضًا: ولا آمين البيت الحرام من أهل الشرك.\n\nوأكثر أهل التأويل على ذلك.\n\nوإن كان عُني بذلك المشركون من أهل الحرب، فهو أيضًا لا شك منسوخ.\n\n* *\n\nوإذْ كان ذلك كذلك = وكان لا اختلاف في ذلك بينهم ظاهر، وكان ما كان مستفيضًا فيهم ظاهرًا حجةً = فالواجب، وإن احتمل ذلك معنى غير الذي قالوا، التسليمُ لما استفاض بصحته نقلهم. [[سياق هذه الفقرة: \"وإذ كان ذلك كذلك، وكان لا اختلاف ... فالواجب ... التسليم لما استفاض بصحته نقلهم\".]]\n\n* *\n\nالقول في تأويل قوله: ﴿يَبْتَغُونَ فَضْلا مِنْ رَبِّهِمْ وَرِضْوَانًا﴾\n\nقال أبو جعفر: يعني بقوله:\"يبتغون\"، يطلبون ويلتمسون = و\"الفضل\" الأرباح في التجارة = و\"الرضوان\"، رضَى الله عنهم، فلا يحل بهم من العقوبة في الدنيا ما أحلَّ بغيرهم من الأمم في عاجل دنياهم، بحجّهم بيتَه. [[مضى تفسير هذه الآية ص: ٤٧١، ٤٧٢، كما أسلفت في التعليق: ١، ص: ٤٧١ وانظر تفسير\"الابتغاء\" فيما سلف ٩: ٣١٩، تعليق: ٣، والمراجع هناك.\n\nوتفسير\"الفضل\" فيما سلف من فهارس اللغة.\n\nوتفسير\"الرضوان\" فيما سلف ٦: ٢٦٢.]]\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١٠٩٧٩- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، حدثنا معمر، عن قتادة في قوله:\"يبتغون فضلا من ربهم ورضوانًا\"، قال: هم المشركون، يلتمسون فضل الله ورضوانه فيما يصلح لهم دُنياهم.\n\n١٠٩٨٠- حدثنا ابن وكيع قال، حدثنا عبدة بن سليمان قال، قرأت على ابن أبي عروبة فقال: هكذا سمعته من قتادة في قوله:\"يبتغون فضلا من ربهم ورضوانًا\"، والفضل والرضوان اللذان يبتغون: أن يصلح معايشهم في الدنيا، وأن لا يعجَّل لهم العقوبة فيها.\n\n١٠٩٨١- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن ابن عباس:\"يبتغون فضلا من ربهم ورضوانًا\"، يعني: أنهم يترضَّون الله بحجهم.\n\n١٠٩٨٢- حدثنا ابن وكيع قال، حدثنا عبيد الله، عن أبي جعفر الرازي، عن الربيع بن أنس قال: جلسنا إلى مطرِّف بن الشِّخِّير، وعنده رجل فحدثهم في قوله:\"يبتغون فضلا من ربهم ورضوانًا\"، قال: التجارة في الحج، والرضوان في الحج.\n\n١٠٩٨٣- حدثنا محمد بن المثنى قال، حدثنا محمد بن جعفر قال، حدثنا شعبة، عن أبي أميمة قال، قال ابن عمر في الرجل يحج ويحمل معه متاعًا، قال: لا بأس به = وتلا هذه الآية:\"يبتغون فضلا من ربهم ورضوانًا\". [[الأثر: ١٠٩٨٣-\"أبو أميمة التيمي\" وهو\"أبو أمامة التيمي\"، قال ابن معين: \"ثقة، لا يعرف اسمه\"، وقال البخاري في الكنى: \"أبو أمامة، قال شعبة: أبو أميمة سمع ابن عمر. روى عنه العلاء، وشعبة. يقال اسمه: عمرو بن أسماء\". مترجم في التهذيب، والكنى للبخاري: ٤، وابن أبي حاتم في باب\"أبو أمامة\"، و\"أبو أميمة\". ترجمتان ٤/٢/٣٣٠، ٣٣١.]]\n\n١٠٩٨٤- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد:\"يبتغون فضلا من ربهم ورضوانًا\"، قال: يبتغون الأجر والتجارة.\n\n* *\n\nالقول في تأويل قوله: ﴿وَإِذَا حَلَلْتُمْ فَاصْطَادُوا﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: وإذا حللتم فاصطادوا الصيد الذي نهيتكم أن تُحِلُّوه وأنتم حرم. يقول: فلا حرج عليكم في اصطياده، واصطادوا إن شئتم حينئذ، لأن المعنى الذي من أجله كنت حرَّمته عليكم في حال إحرامكم قد زال.\n\n* *\n\nوبما قلنا في ذلك قال جميع أهل التأويل.\n\nذكر من قال ذلك:\n\n١٠٩٨٥- حدثني يعقوب بن إبراهيم قال، حدثنا هشيم قال، حدثنا حصين، عن مجاهد أنه قال: هي رخصة = يعني قوله:\"وإذا حللتم فاصطادوا\".\n\n١٠٩٨٦- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن حجاج، عن القاسم، عن مجاهد قال: خمس في كتاب الله رخصة، وليست بعَزْمة، فذكر:\"وإذا حللتم فاصطادوا\"، قال: من شاء فعل، ومن شاء لم يفعل.\n\n١٠٩٨٧- حدثنا ابن وكيع قال، حدثنا أبو خالد، عن حجاج، عن عطاء، مثله.\n\n١٠٩٨٨- حدثنا ابن وكيع قال، حدثنا أبي، عن سفيان، عن حصين، عن مجاهد:\"وإذا حللتم فاصطادوا\"، قال: إذا حلّ، فإن شاء صاد، وإن شاء لم يصطد.\n\n١٠٩٨٩- حدثنا ابن وكيع قال، حدثنا ابن إدريس، عن ابن جريج، عن رجل، عن مجاهد: أنه كان لا يرى الأكل من هَدْي المتعة واجبًا، وكان يتأول هذه الآية:\"وإذا حللتم فاصطادوا\" = ﴿فَإِذَا قُضِيَتِ الصَّلاةُ فَانْتَشِرُوا فِي الأرْضِ﴾ [سورة الجمعة: ١٠] . [[يعني بقوله: \"يتأول هذه الآية\"، أي يفسرها كتفسير الآية الأخرى: فإذا قضيت الصلاة، فمن شاء خرج من المسجد، ومن شاء جلس، رخصة من الله.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَلا يَجْرِمَنَّكُمْ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"ولا يجرمنكم\"، ولا يحملنكم، كما:-\n\n١٠٩٩٠- حدثني المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية بن صالح، عن علي، عن ابن عباس قوله:\"ولا يجرمنكم شنآن قوم\"، يقول: لا يحملنكم شنآن قوم.\n\n١٠٩٩١- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"ولا يجرمنكم شنآن قوم\"، أي: لا يحملنكم.\n\n* *\n\nوأما أهل المعرفة باللغة فإنهم اختلفوا في تأويلها.\n\nفقال بعض البصريين: معنى قوله:\"ولا يجرمنكم\"، لا يُحِقَّنَّ لكم، لأن قوله: ﴿لا جَرَمَ أَنَّ لَهُمُ النَّارَ﴾ [سورة النحل: ٦٢] ، هو: حقٌّ أن لهم النار. [[هذه مقالة الأخفش، كما ذكر ذلك صاحب لسان العرب، مادة (جرم) .]]\n\n* *\n\nوقال بعض الكوفيين: معناه: لا يحملنَّكم. وقال: يقال:\"جرمني فلان على أن صنعت كذا وكذا\"، أي: حملني عليه.\n\n* *\n\nواحتج جميعهم ببيت الشاعر: [[هو أبو أسماء بن الضّريبة. ويقال: هو لعطية بن عفيف، ونسبه سيبوبه للفزاري مجهلا.]]\n\nوَلَقَدْ طَعَنْتَ أَبَا عُيَيْنَةَ طَعْنَةً ... جَرَمَتْ فَزَارَةُ بَعْدَهَا أَنْ يَغْضَبُوا [[سيبويه ١: ٤٦٩، مجاز القرآن لأبي عبيدة ١: ١٤٧، مشكل القرآن: ٤١٨، والفاخر: ٢٠٠، الجواليقي: ١٦٣، البطليوسي: ٣١٣، الخزانة ٤: ٣١٠، اللسان (جرم) . وسبب الشعر أن كرزًا العقيلي، قتل أبا عيينة حصن بن حذيفة بن بدر الفزاري يوم حاجر، فلما قتل كرز، قال الشاعر يرثيه ويخاطبه: يَا كُرزُ، إنَّكَ قَدْ قُتِلْتَ بِفَارِسٍ ... بَطَلٍ إذَا هَابَ الكُمَاةُ وَجَبَّبُوا\n\n\"جبب الرجل تجبيبًا\": إذا فر ومضى مسرعًا. وروى البكري في معجم ما استعجم أنه قال: يَا كُرْزُ إنَّكَ قد فَتَكْتَ بِفَارِسٍ ... بَطَلٍ إذَا هَابَ الكُمَاةُ مُجَرَّبِ\n\nوكأنه شعر غير هذا الشعر.]] فتأول ذلك كل فريق منهم على المعنى الذي تأوله من القرآن. فقال الذين قالوا:\"لا يجرمنكم\"، لا يُحِقَّن لكم = معنى قول الشاعر:\"جرمت فزارة\"، أحقَّت الطعنةُ لفزارة الغضبَ.\n\nوقال الذين قالوا: معناه: لا يحملنكم = معناه في البيت:\"جرمت فزارة أن يغضبوا\"، حملت فزارة على أن يغضبوا.\n\n* *\n\nوقال آخر من الكوفيين: معنى قوله:\"لا يجرمنكم\"، لا يكسبنكم شنآن قوم.\n\nوتأويل قائل هذا القول قولَ الشاعر في البيت:\"جرمت فزارة\"، كسبت فزارة أن يغضبوا. قال: وسمعت العرب تقول:\"فلان جريمة أهله\"، بمعنى: كاسبهم =\"وخرج يجرمهم\"، يكسبهم. [[قائل هذا هو الفراء في معاني القرآن ١: ٢٩٩.]]\n\n* *\n\nقال أبو جعفر: وهذه الأقوال التي حكيناها عمن حكيناها عنه، متقاربة المعنى. وذلك أن من حمل رجلا على بغض رجل، فقد أكسبه بغضه. ومن أكسبه بغضه، فقد أحقَّه له.\n\nفإذا كان ذلك كذلك، فالذي هو أحسن في الإبانة عن معنى الحرف، ما قاله ابن عباس وقتادة، وذلك توجيههما معنى قوله:\"ولا يجرمنكم شنآن قوم\"، ولا يحملنكم شنآن قومٍ على العدوان.\n\n* *\n\nواختلفت القرأة في قراءة ذلك.\n\nفقرأته عامة قرأة الأمصار: ﴿وَلا يَجْرِمَنَّكُمْ﴾ بفتح\"الياء\" من:\"جَرَمْتُه أجْرِمُه\".\n\n* *\n\nوقرأ ذلك بعض قرأة الكوفيين [[انظر معاني القرآن للفراء ١: ٢٩٩.]] وهو يحيى بين وثّاب، والأعمش: ما:-\n\n١٠٩٩٢- حدثنا ابن حميد وابن وكيع قالا حدثنا جرير، عن الأعمش أنه قرأ: ﴿وَلا يُجْرِمَنَّكُمْ﴾ مرتفعة\"الياء\"، من:\"أجرمته أجرمه، وهو يُجْرِمني\".\n\n* *\n\nقال أبو جعفر: والذي هو أولى بالصواب من القراءتين، قراءة من قرأ ذلك: ﴿وَلا يَجْرِمَنَّكُمْ﴾ بفتح\"الياء\"، لاستفاضة القراءة بذلك في قرأة الأمصار، وشذوذ ما خالفها، وأنها اللغة المعروفة السائرة في العرب، وإن كان مسموعًا من بعضها:\"أجرم يُجْرم\" على شذوذه. وقراءة القرآن بأفصح اللغات، أولى وأحق منها بغير ذلك. ومن لغة من قال\"جَرَمْتُ\"، قول الشاعر: [[ينسب للفرزدق، وليس في ديوانه.]]\n\nيَا أَيُّهَا المُشْتَكِي عُكْلا وَمَا جَرَمَتْ ... إلى القَبَائِلِ مِنْ قَتْلٍ، وإبْآسُ [[مجالس ثعلب: ٤٩، ٥٠، والأضداد لابن الأنباري: ٨٥، والبيت مرفوع القافية وبعد البيت: إنّا كَذَاكَ، إذَا كانَتْ هَمَرَّجَةٌ ... نَسْبِي ونَقْتُلُ حَتَّى يُسْلِمَ النَّاسُ\n\n\"همرجة\": اختلاط وفتنة. وروى ثعلب هذين البيتين. ثم قال، ولم يبين لمن كان هذا الخبر: \"قلت له (يعني: للفرزدق) : لم قلت: من قتل، وإبآس؟ قال: كيف أصنع وقد قلت: حتى يسلم الناس؟ قال قلت: فيم رفعته؟ قال: بما يسوءك وينوءك! \".\n\nثم قال أبو العباس ثعلب: \"وإنما رفعه، لأن الفعل لم يظهر بعده، كما تقول: ضربت زيدًا وعمرو = لم يظهر الفعل فرفعت، وكما تقول: ضربت زيدًا وعمرو مضروب\".]]\n\n* *\n\nالقول في تأويل قوله: ﴿شَنَآنُ قَوْمٍ﴾\n\nاختلفت القرأة في قراءة ذلك.\n\nفقرأه بعضهم: ﴿شَنَآنُ﴾ بتحريك\"الشين والنون\" إلى الفتح، بمعنى: بغض قوم، توجيهًا منهم ذلك إلى المصدر الذي يأتي على\"فَعَلان\"، نظير\"الطيران\" و\"النَّسَلان\" و\"العَسَلان\" و\"الرَّمَلان\".\n\n* *\n\nوقرأ ذلك آخرون: ﴿شَنْآنُ قَوْمٍ﴾ بتسكين\"النون\" وفتح\"الشين\" بمعنى: الاسم، توجيهًا منهم معناه إلى: لا يحملنكم بَغِيض قوم [[في المطبوعة والمخطوطة: \"بغض قوم\"، والصواب ما أثبت، كما يدل عليه السياق.]] فيخرج\"شَنْآن\" على تقدير\"فَعْلان\"، لأن\"فَعَل\" منه على\"فَعِلَ\" [[قوله: \"فعل\" الأولى، يعني الفعل الماضي، أما الثانية، فهي الميزان الصرفي، على وزن\"سكر\" بكسر العين.]] كما يقال:\"سكران\" من\"سكر\"، و\"عطشان\" من\"عطش\"، وما أشبه ذلك من الأسماء.\n\n* *\n\nقال أبو جعفر: والذي هو أولى القراءتين في ذلك بالصواب، قراءة من قرأ: ﴿شَنَآنُ قَومٍ﴾ بفتح\"النون\" محركة، لشائع تأويل أهل التأويل على أن معناه: بغض قوم = وتوجيههم ذلك إلى معنى المصدر دون معنى الاسم.\n\nوإذْ كان ذلك موجَّهًا إلى معنى المصدر، فالفصيح من كلام العرب فيما جاء من المصادر على\"الفَعلان\" بفتح\"الفاء\"، تحريك ثانيه دون تسكينه، كما وصفت من قولهم:\"الدَّرَجَان\" و\"الرَّمَلان\"، من\"درج\" و\"رمل\"، فكذلك\"الشنآن\" من\"شنئته أشنَؤُه شنآنًا\"، ومن العرب من يقول:\"شَنَانٌ\" على تقدير\"فعال\"، ولا أعلم قارئًا قرأ ذلك كذلك، ومن ذلك قول الشاعر: [[هو الأحوص بن محمد الأنصاري.]]\n\nوَمَا العَيْشُ إلا مَا تَلَذُّ وتَشْتَهِي ... وَإنْ لامَ فِيهِ ذُو الشَّنَانِ وَفَنَّدَا [[طبقات فحول الشعراء: ٥٣٩، الأغاني ١٣: ١٥١-١٥٣، مصارع العشاق: ٦٢، ٧٥، والشعر والشعراء: ٥٠١، واللسان (شنأ) ، وقلما يخلو منه كتاب بعد.]]\n\nوهذا في لغة من ترك الهمز من\"الشنآن\"، فصار على تقدير\"فعال\" وهو في الأصل\"فَعَلان\".\n\n* *\n\nذكر من قال من أهل التأويل:\"شنآن قوم\"، بغض قوم.\n\n١٠٩٩٣- حدثني المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"ولا يجرمنكم شنآن قوم\"، لا يحملنكم بغض قوم.\n\n١٠٩٩٤- وحدثني به المثنى مرة أخرى بإسناده، عن ابن عباس فقال: لا يحملنكم عداوة قوم أن تعتدوا.\n\n١٠٩٩٥- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"ولا يجرمنكم شنآن قوم\"، لا يجرمنكم بغض قوم.\n\n١٠٩٩٦- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"ولا يجرمنكم شنآن قوم\"، قال: بغضاؤهم، أن تعتدوا.\n\n* *\n\nالقول في تأويل قوله: ﴿أَنْ صَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ أَنْ تَعْتَدُوا﴾\n\nقال أبو جعفر: اختلفت القرأة في قراءة ذلك.\n\nفقرأه بعض أهل المدينة وعامة قرأة الكوفيين: ﴿أَنْ صَدُّوكُمْ﴾ بفتح\"الألف \" من\"أن\"، بمعنى: لا يجرمنكم بغض قوم بصدِّهم إياكم عن المسجد الحرام أن تعتدوا.\n\n* *\n\nوكان بعض قرأة الحجاز والبصرة يقرأ ذلك: ﴿ولا يجرمنكم شنآن قوم إن صدوكم﴾ ، بكسر\"الألف\" من\"إن\"، بمعنى: ولا يجرمنكم شنآن قوم إن هم أحدثوا لكم صدًّا عن المسجد الحرام أن تعتدوا = فزعموا أنها في قراءة ابن مسعود: ﴿إن يصدوكم﴾ ، فقرأوا ذلك كذلك اعتبارًا بقراءته. [[انظر معاني القرآن للفراء ١: ٣٠٠.]]\n\n* *\n\nقال أبو جعفر: والصواب من القول في ذلك عندي، أنهما قراءتان معروفتان مشهورتان في قرأة الأمصار، صحيح معنى كل واحدة منهما.\n\nوذلك أن النبي ﷺ صُدَّ عن البيت هو وأصحابه يوم الحديبية، وأنزلت عليه\"سورة المائدة\" بعد ذلك، فمن قرأ ﴿أَنْ صَدُّوكُمْ﴾ بفتح\"الألف\" من\"أن\"، فمعناه: لا يحملنكم بغض قوم، أيها الناس، من أجل أن صدوكم يوم الحديبية عن المسجد الحرام، أن تعتدوا عليهم.\n\nومن قرأ: ﴿إن صدوكم﴾ بكسر\"الألف\"، فمعناه: لا يجرمنكم شنآن قوم إن صدوكم عن المسجد الحرام إذا أردتم دخوله. لأن الذين حاربوا رسول الله ﷺ وأصحابه من قريش يوم فتح مكة، قد حاولوا صَدَّهم عن المسجد الحرام. فتقدم الله إلى المؤمنين = في قول من قرأ ذلك بكسر\"إن\" = بالنهي عن الاعتداء عليهم، إن هم صدوهم عن المسجد الحرام، قبل أن يكون ذلك من الصادِّين.\n\nغير أن الأمر، وإن كان كما وصفت، فإن قراءة ذلك بفتح\"الألف\"، أبينُ معنى. لأن هذه السورة لا تَدَافُعَ بين أهل العلم في أنها نزلت بعد يوم الحديبية.\n\nوإذْ كان ذلك كذلك، فالصدُّ قد كان تقدم من المشركين، فنهى الله المؤمنين عن الاعتداء على الصادِّين من أجل صدِّهم إياهم عن المسجد الحرام. [[انظر تفسير\"الصد\" فيما سلف ص: ٤١٠، تعليق: ١، والمراجع هناك.]]\n\n* *\n\nوأما قوله:\"أن تعتدوا\"، فإنه يعني: أن تجاوزوا الحدَّ الذي حدَّه الله لكم في أمرهم. [[انظر تفسير\"الاعتداء\" فيما سلف من فهارس اللغة.]]\n\n* *\n\nفتأويل الآية إذًا: ولا يحملنكم بغض قوم، لأن صدوكم عن المسجد الحرام، أيها المؤمنون، أن تعتدوا حكم الله فيهم، فتجاوزوه إلى ما نهاكم عنه، ولكن الزموا طاعة الله فيما أحببتم وكرهتم.\n\n* *\n\nوذكر أنها نزلت في النهي عن الطلب بذُحول الجاهلية. [[\"الذحول\" جمع\"ذحل\" (بفتح فسكون) : وهو الثأر.]]\n\nذكر من قال ذلك:\n\n١٠٩٩٧- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله:\"أن تعتدوا\"، رجل مؤمن من حلفاء محمد، قتل حليفًا لأبي سفيان من هذيل يوم الفتح بعرفة، لأنه كان يقتل حلفاء محمد، فقال محمد ﷺ: لعن الله من قتل بذَحْل الجاهلية.\n\n١٠٩٩٨- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n* *\n\nوقال آخرون: هذا منسوخ\n\nذكر من قال ذلك:\n\n١٠٩٩٩- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"ولا يجرمنكم شنآن قوم أن تعتدوا\"، قال: بغضاؤهم، حتى تأتوا ما لا يحل لكم. وقرأ:\"أن صدوكم عن المسجد الحرام أن تعتدوا وتعاونوا\"، وقال: هذا كله قد نسخ، نسخه الجهاد.\n\n* *\n\nقال أبو جعفر: وأولى القولين في ذلك بالصواب، قول مجاهد أنه غير منسوخ، لاحتماله: أن تعتدوا الحقَّ فيما أمرتكم به. وإذا احتمل ذلك، لم يجز أن يقال:\"هو منسوخ\"، إلا بحجة يجب التسليم لها.\n\n* *\n\nالقول في تأويل قوله: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإثْمِ وَالْعُدْوَانِ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"وتعاونوا على البر والتقوى\"، وليعن بعضكم، أيها المؤمنون، بعضًا =\"على البر\" =، وهو العمل بما أمر الله بالعمل به [[انظر تفسير\"البر\" فيما سلف ٢: ٨/٣: ٣٣٦-٣٣٨، ٥٥٦/٤: ٤٢٥/٦: ٥٨٧.]] =\"والتقوى\"، هو اتقاء ما أمر الله باتقائه واجتنابه من معاصيه. [[انظر تفسير\"التقوى\" فيما سلف من فهارس اللغة، مادة (وقى) .]]\n\n* *\n\nوقوله:\"ولا تعاونوا على الإثم والعدوان\"، يعني: ولا يعن بعضكم بعضًا =\"على الإثم\"، يعني: على ترك ما أمركم الله بفعله =\"والعدوان\"، يقول: ولا على أن تتجاوزوا ما حدَّ الله لكم في دينكم، وفرض لكم في أنفسكم وفي غيركم. [[انظر تفسير\"الإثم\" و\"العدوان\" فيما سلف من فهارس اللغة (أثم) (عدا) .]]\n\nوإنما معنى الكلام: ولا يجرمنكم شنآن قوم أن صدوكم عن المسجد الحرام أن تعتدوا، ولكن ليعن بعضكم بعضًا بالأمر بالانتهاء إلى ما حدَّه الله لكم في القوم الذين صدُّوكم عن المسجد الحرام وفي غيرهم، والانتهاء عما نهاكم الله أن تَأتوا فيهم وفي غيرهم، وفي سائر ما نهاكم عنه، ولا يعن بعضكم بعضًا على خلاف ذلك.\n\n* *\n\nوبما قلنا في\"البر والتقوى\" قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠٠٠- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"وتعاونوا على البر والتقوى\"،\"البر\" ما أمرت به، و\"التقوى\" ما نهيت عنه.\n\n١١٠٠١- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع، عن أبي العالية في قوله:\"وتعاونوا على البر والتقوى\" قال:\"البر\" ما أمرت به، و\"التقوى\" ما نهيت عنه.\n\n* *\n\nالقول في تأويل قوله: ﴿وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ (٢) ﴾\n\nقال أبو جعفر: وهذا وعيد من الله جل ثناؤه وتهدُّدٌ لمن اعتدى حدّه وتجاوز أمره [[في المطبوعة: \"وتهديد لمن اعتدى\"، وأثبت ما في المخطوطة.]] يقول عز ذكره:\"واتقوا الله\"، يعني: واحذروا الله، أيها المؤمنون، أن تلقوه في معادكم وقد اعتديتم حدَّه فيما حدَّ لكم، وخالفتم أمره فيما أمركم به، أو نهيه فيما نهاكم عنه، فتستوجبوا عقابه، وتستحقوا أليم عذابه. ثم وصف عقابه بالشدة فقال عز ذكره: إن الله شديدٌ عقابه لمن عاقبه من خلقه، لأنها نار لا يطفأ حَرُّها، ولا يخمد جمرها، ولا يسكن لهبها، نعوذ بالله منها ومن عمل يقرِّبنا منها."],[3,3,"القول في تأويل قوله: ﴿حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: حرَّم الله عليكم، أيها المؤمنون، الميتة.\n\n* *\n\nو\"الميتة\": كل ما له نفس سائلة من دواب البر وطيره، مما أباح الله أكلها، أهليَّها ووحشيَّها، فارقتها روحها بغير تذكية. [[\"التذكية\": الذبح.]]\n\nوقد قال بعضهم:\"الميتة\"، هو كل ما فارقته الحياة من دوابِّ البر وطيره بغير تذكية، مما أحل الله أكله. [[انظر تفسير\"الميتة\" فيما سلف ٣: ٣١٨، ٣١٩.]]\n\nوقد بيّنا العلة الموجبة صحة القول بما قلنا في ذلك، في كتابنا ﴿كتاب لطيف القول في الأحكام﴾ . [[مر اسم هذا الكتاب مرارًا، ومر في بعضها باسم\"اللطيف في أحكام شرائع الإسلام\"، ١: ١٠٩، وكان هنا في المخطوطة والمطبوعة: \"كتاب اللطيف القول في الأحكام\"، وهو غير مستقيم.]]\n\n* *\n\nوأما\"الدم\"، فإنه الدم المسفوح، دون ما كان منه غير مسفوح، لأن الله جل ثناؤه قال: ﴿قُلْ لا أَجِدُ فِي مَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَى طَاعِمٍ يَطْعَمُهُ إِلا أَنْ يَكُونَ مَيْتَةً أَوْ دَمًا مَسْفُوحًا أَوْ لَحْمَ خِنزيرٍ﴾ [سورة الأنعام: ١٤٥] ، فأما ما كان قد صار في معنى اللحم، كالكبد والطحال، وما كان في اللحم غير منسفح، فإن ذلك غير حرام، لإجماع الجميع على ذلك.\n\n* *\n\nوأما قوله:\"ولحم الخنزير\"، فإنه يعني: وحُرِّم عليكم لحم الخنزير، أهليُّه وبَرِّيّه.\n\nفالميتة والدم مخرجهما في الظاهر مخرج عموم، والمراد منهما الخصوص. وأما لحم الخنزير، فإن ظاهره كباطنه، وباطنه كظاهره، حرام جميعه، لم يخصص منه شيء.\n\n* *\n\nوأما قوله:\"وما أهلَّ لغير الله به\"، فإنه يعني: وما ذكر عليه غير اسم الله.\n\n* *\n\nوأصله من\"استهلال الصبي\"، وذلك إذا صاح حين يسقط من بطن أمه. ومنه\"إهلال المحرم بالحج\"، إذا لبّى به [[انظر تفسير\"الإهلال\" فيما سلف ٣: ٣١٩، ٣٢٠.]] ومنه قول ابن أحمر:\n\nيُهلُّ بالفَرْقَدِ رُكْبَانُهَا ... كَمَا يُهِلُّ الرَّاكِبُ المُعْتَمِرْ [[مجاز القرآن لأبي عبيدة ١: ١٥٠، الجمهرة ٢: ٣٨٧، اللسان (عمر) (هلل) . يصف مفازة لا يهتدي فيها. و\"المعتمر\"، المعتم بعمامة. و\"الفرقد\"، أراد\"الفرقدان\"، وهما كوكبان من بنات نعش الصغرى، أو هما نجمان في السماء لا يغربان، ولكنهما يطوفان بالجدي.\n\nوفي شرح البيت قولان. قال الأصمعي: \"إذا انجلى لهم السحاب عن الفرقد، أهلوا، أي: رفعوا أصواتهم بالتكبير، كما يهل الراكب الذي يريد عمرة الحج، لأنهم كانوا يهتدون بالفرقد\".\n\nوقال غيره: \"يريد أنهم في مفازة بعيدة من المياه، فإذا رأوا فرقدًا = وهو ولد البقرة الوحشية = أهلوا، أي: كبروا، لأنهم قد علموا أنهم قد قربوا من الماء\".\n\nقلت: والعرب تتخذ\"الفرقدين\" دليلا في الاهتداء بهما، لأنهما لا يطلبان في وقت من الليل إلا وجدا، قال الراعي: لا يَتَّخِذْنَ إذَا عَلَوْنَ مَفَازةً ... إلا بَيَاضَ الفَرْقَدَينِ دَليلا]]\n\n* *\n\nوإنما عنى بقوله:\"وما أهل لغير الله به\"، وما ذبح للآلهة وللأوثان، يسمى عليه غير اسم الله. [[انظر ما سلف ٣: ٣٢١.]]\n\n* *\n\nوبالذي قلنا في ذلك قال أهل التأويل، وقد ذكرنا الرواية عمن قال ذلك فيما مضى، فكرهنا إعادته. [[انظر الآثار السالفة من رقم: ٢٤٦٨- ٢٤٧٧.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَالْمُنْخَنِقَةُ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في صفة\"الانخناق\" الذي عنى الله جل ثناؤه بقوله:\"والمنخنقة\".\n\nفقال بعضهم بما:-\n\n١١٠٠٢- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"والمنخنقة\"، قال: التي تدخل رأسها بين شُعْبتين من شجرة، فتختنق فتموت.\n\n١١٠٠٢م- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك في المنخنقة، قال: التي تختنق فتموت.\n\n١١٠٠٣- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، حدثنا معمر، عن قتادة في قوله:\"والمنخنقة\"، التي تموت في خِنَاقها. [[\"الخناق\" (بكسر الخاء) : الحبل الذي يخنق به، وأراد الحبل الذي ربطت فيه من عند عنقها.]]\n\n* *\n\nوقال آخرون: هي التي توثق فيقتلها بالخناق وَثَاقها.\n\nذكر من قال ذلك:\n\n١١٠٠٤- حدثت عن الحسين قال، سمعت أبا معاذ يقول، أخبرنا عبيد قال، سمعت الضحاك يقول في قوله:\"والمنخنقة\"، قال: الشاة توثق، فيقتلها خِنَاقها، فهي حرام.\n\n* *\n\nوقال آخرون: بل هي البهيمة من النَّعم، كان المشركون يخنقونها حتى تموت، فحرَّم الله أكلها.\n\nذكر من قال ذلك:\n\n١١٠٠٥- حدثني المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية، عن علي، عن ابن عباس:\"والمنخنقة\" التي تُخنق فتموت. [[في المطبوعة: \"تختنق فتموت\"، وهو خطأ صرف مفسد لاستدلال الطبري، والصواب من المخطوطة.]]\n\n١١٠٠٦- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"والمنخنقة\"، كان أهل الجاهلية يخنقون الشاة، حتى إذا ماتت أكلوها. [[الأثر: ١١٠٠٦-\"بشر بن معاذ\"، مضى، ومضى إسناده هذا مئات من المرات، أقربه رقم: ١٠٩٩٥، ولكن كان في المخطوطة والمطبوعة هنا: \"حدثنا أنس قال، حدثنا يزيد\" وهو خطأ صرف.]]\n\n* *\n\nوأولى هذه الأقوال بالصواب، قول من قال:\"هي التي تختنق، إما في وثاقها، وإما بإدخال رأسها في الموضع الذي لا تقدر على التخلص منه، فتختنق حتى تموت\".\n\nوإنما قلنا ذلك أولى بالصواب في تأويل ذلك من غيره، لأن\"المنخنقة\"، هي الموصوفة بالانخناق، دون خنق غيرها لها، ولو كان معنيًّا بذلك أنها مفعول بها، لقيل:\"والمخنوقة\"، حتى يكون معنى الكلام ما قالوا.\n\n* *\n\nالقول في تأويل قوله: ﴿وَالْمَوْقُوذَةُ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"والموقوذة\"، والميتة وقيذًا.\n\n* *\n\nيقال منه:\"وقَذَهُ يَقِذُه وقْذًا\"، إذا ضربه حتى أشرف على الهلاك، ومنه قول الفرزدق:\n\nشَغَّارَةٍ تَقِذُ الفَصِيلَ بِرِجْلِهَا ... فَطَّارَةٍ لِقَوَادِمِ الأبْكَارِ [[ديوانه: ٤٥٢، النقائض: ٣٣٢، من هجائه جريرًا، قبله: كَمْ خَالَةٍ لَكَ، يا جَرِيرُ، وعَمّةٍ ... فَدْعَاءَ قَدْ حَلَبَتْ عَلَى عِشَارِي\n\nكُنَّا نُحَاذِرُ أَنْ تُضِيعَ لِقَاحَنَا ... وَلَهًا، إذَا سَمِعَتْ دُعاءَ يَسَارِ\n\nيقول: عماته وخالاته رعاة أجلاف، واستجاد لهن شر الصفات، فزعمها\"فدعاء\"، أي في الرسغ من أقدامها ميل وعوج، من المهنة في العمل منذ ولدت. وزعم أنهن كن عنده يحلبن\"عشاره\"، وهي النوق الحديثة العهد بالولادة، وأنفس الإبل عند أهلها إذا كانت عشارًا، وهي\"اللقاح\" أيضًا.\n\nو\"يسار\" اسم راع من عبيدة. يقول: إذا سمعت صوت يسار ساورها الشبق إليه، فطاش عقلها ولهًا وصبابة، فكانوا يخافون أن تهمل اللقاح حتى تهلك وتضيع.\n\nثم وصفها بالغلظة، بأقبح وصف، فزعم أنها إذا قامت تحلب الناقة، ثم دنا الفصيل من أمه، شغرت برجلها = رفعتها، كما يرفع الكلب رجله وهو يبول إلى خلف = فضربته ضربة يشرف بها على الهلاك، كأن ساقها رمح أو هراوة.\n\nوأما قوله: \"فطارة لقوادم الأبكار\"، فالأبكار جمع\"بكر\"، وهي الناقة التي ولدت بطنًا واحدًا، فأخلافها صغار قصار، لا يستمكن الحالب أن يحلبها ضبًا، وهو الحلب بالكف كلها، بل تحلب فطرًا، أي بالسبابة والوسطى، ويستعان بطرف الإبهام. و\"القوادم\" من النوق، لكل ناقة\"قادمان\"، وهما خلفا الضرع المقدمان.]]\n\n* *\n\nوبنحو ما قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠٠٧- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس:\"والموقوذة\"، قال: الموقوذة، التي تضرب بالخشب حتى توقَذَ بها فتموت. [[في المطبوعة: \"حتى تقذها فتموت\"، وفي المخطوطة: \"حتى توقذها فتموت\"، وصواب قراءتها ما أثبت. وقوله: \"بها\" أي بالخشبة، وانظر الآثار التالية، فهي دالة على صواب هذه القراءة.]]\n\n١١٠٠٨- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"والموقوذة\"، كان أهل الجاهلية يضربونها بالعِصيّ، حتى إذا ماتت أكلوها.\n\n١١٠٠٩- حدثنا محمد بن بشار قال، حدثنا روح قال، حدثنا شعبة، عن قتادة في قوله:\"والموقوذة\"، قال: كانوا يضربونها حتى يقذوها، ثم يأكلونها.\n\n١١٠١٠- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:\"والموقوذة\"، التي توقذ فتموت.\n\n١١٠١١- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك قال:\"الموقوذة\"، التي تضرب حتى تموت.\n\n١١٠١٢- حدثنا محمد بن الحسين قال، حدثنا أحمد بن مفضل قال، حدثنا أسباط، عن السدي:\"والموقوذة\"، قال: هي التي تضرب فتموت.\n\n١١٠١٣- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سلمان قال، سمعت الضحاك يقول في قوله:\"والموقوذة\"، كانت الشاة أو غيرها من الأنعام تضرب بالخشب لآلهتهم، حتى يقتلوها فيأكلوها.\n\n١١٠١٤- حدثنا العباس بن الوليد قال، أخبرني عقبة بن علقمة، حدثني إبراهيم بن أبي عبلة. قال، حدثني نعيم بن سلامة، عن أبي عبد الله الصنابحي قال: ليست\"الموقوذة\" إلا في مالك، وليس في الصيد وقيذ. [[الأثر: ١١٠١٤-\"العباس بن الوليد بن مزيد الآملي\"، شيخ الطبري، مضى برقم: ٨٩١.\n\nو\"عقبة بن علقمة بن حديج المعافري\"، من أصحاب الأوزاعي، كان خيارًا ثقة. مترجم في التهذيب.\n\nو\"إبراهيم بن أبي عبلة بن شمر، بن يقظان الرملي\". روى عنه مالك، والليث، وابن المبارك. ثقة. قال ضمرة بن ربيعة: \"ما رأيت أفصح منه\"، وكان يقول الشعر الحسن. مترجم في التهذيب، والكبير للبخاري ١/١/٣١٠.\n\nو\"نعيم بن سلامة الأزدي\"، ويقال: \"نعيم بن سلامان\". كان على خاتم سليمان بن عبد الملك وعمر بن عبد العزيز. لم يذكروا فيه جرحًا. مترجم في الكبير ٤/٢/٩٨، وابن أبي حاتم ٤/١/٤٦٢، وتعجيل المنفعة: ٤٢٣.\n\nو\"أبو عبد الله الصنابحي\"، هو: \"عبد الرحمن بن عسيلة بن عسل بن عسال المرادي\". رحل إلى النبي ﷺ، فوجده قد مات قبله بخمس ليال أو ست. كان ثقة قليل الحديث. أخرج الطبراني من طريق ابن محيريز قال: \"عدنا عبادة بن الصامت، فأقبل أبو عبد الله الصنابحي، فقال عبادة: من سره أن ينظر إلى رجل عرج به إلى السماء، فنظر إلى أهل الجنة وأهل النار، فرجع وهو يعمل على ما رأى، فلينظر إلى هذا\".]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَالْمُتَرَدِّيَةُ﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: وحرمت عليكم الميتة تردِّيًا من جبل أو في بئر، أو غير ذلك.\n\n* *\n\nو\"تردِّيها\"، رميُها بنفسها من مكان عالٍ مشرف إلى سُفْله.\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠١٥- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية بن صالح، عن علي بن أبي طلحة، عن ابن عباس:\"والمتردية\"، قال: التي تتردَّى من الجبل.\n\n١١٠١٦- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"والمتردية\"، كانت تتردى في البئر فتموت، فيأكلونها.\n\n١١٠١٧- حدثنا ابن بشار قال، حدثنا روح قال، حدثنا سعيد، عن قتادة:\"والمتردية\"، قال: التي تردَّت في البئر.\n\n١١٠١٨- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي في قوله:\"والمتردية\"، قال: هي التي تَرَدَّى من الجبل، أو في البئر، فتموت.\n\n١١٠١٩- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك:\"والمتردية\"، التي تردَّى من الجبل فتموت.\n\n١١٠٢٠- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، حدثنا عبيد قال، سمعت الضحاك يقول في قوله:\"والمتردية\"، قال: التي تَخِرُّ في ركيٍّ، أو من رأس جبل، فتموت. [[\"الركي\": البئر.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَالنَّطِيحَةُ﴾\n\nقال أبو جعفر: يعني بقوله:\"النطيحة\"، الشاة التي تنطحها أخرى فتموت من النطاح بغير تذكية. فحرم الله جل ثناؤه ذلك على المؤمنين، إن لم يدركوا ذكاته قبل موته.\n\n* *\n\nوأصل\"النطيحة\"،\"المنطوحة\"، صرفت من\"مفعولة\" إلى\"فعيلة\".\n\n* *\n\nفإن قال قائل: وكيف أثبتت\"الهاء\" هاء التأنيث فيها، وأنت تعلم أن العرب لا تكاد تثبت\"الهاء\" في نظائرها إذا صرفوها صرف\"النطيحة\" من\"مفعول\" إلى\"فعيل\"، إنما تقول:\"لحية دهين\" و\"عين كحيل\" و\"كف خضيب\"، ولا يقولون: كف خضيبة، ولا عين كحيلة؟ [[انظر ما سلف ٢: ٣٢٨، ٤٠١/٦: ٤١٤، ومواضع أخرى غابت عني.]]\n\nقيل: قد اختلف أهل العربية في ذلك.\n\nفقال بعض نحويي البصرة: أثبتت فيها\"الهاء\" = أعني في\"النطيحة\" = لأنها جعلت كالاسم مثل:\"الطويلة\" و\"الطريقة\".\n\nفكأن قائل هذا القول، وجه\"النطيحة\" إلى معنى\"الناطحة\".\n\nفتأويل الكلام على مذهبه: وحرمت عليكم الميتة نطاحًا، كأنه عنى: وحرمت عليكم الناطحة التي تموت من نِطاحها.\n\n* *\n\nوقال بعض نحويي الكوفة: إنما تحذف العرب\"الهاء\" من\"الفعيلة\" المصروفة عن\"المفعول\"، إذا جعلتها صفة لاسم قد تقدَّمها، فتقول:\"رأينا كفًّا خضيبًا، وعينًا كحيلا\"، فأما إذا حذفت\"الكف\" و\"العين\" والاسم الذي يكون\"فعيل\" نعتًا لها، واجتزأوا بـ \"فعيل\" منها، أثبتوا فيه هاء التأنيث، ليعلم بثبوتها فيه أنها صفة للمؤنث دون المذكر، فتقول:\"رأينا كحيلةً وخضيبة\" و\"أكيلة السبع\". قالوا: ولذلك أدخلت\"الهاء\" في\"النطيحة\"، لأنها صفة المؤنث، ولو أسقطت منها لم يُدْرَ أهي صفة مؤنث أو مذكر.\n\n* *\n\nوهذا القول هو أولى القولين في ذلك بالصواب، لشائع أقوال أهل التأويل [[في المطبوعة: \"بالصواب الشائع من أقوال أهل التأويل\"، وهو عبث وتغيير فاسد، والصواب من المخطوطة. وانظر شبيهة هذه العبارة فيما سلف ص: ٤٨٦ سطر: ١١، \"لشائع تأويل أهل التأويل\"، وهذا التعبير، هو الثاني فيما مر عليّ من تفسير أبي جعفر فيما سلف.]] بأن معنى:\"النطيحة\"، المنطوحة.\n\nذكر من قال ذلك:\n\n١١٠٢١- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن أبي عباس قوله:\"والنطيحة\"، قال: الشاة تنطح الشاة.\n\n١١٠٢٢- حدثنا ابن وكيع قال، حدثنا أبو أحمد الزبيري، عن قيس، عن أبي إسحاق، عن أبي ميسرة قال: كان يقرأ: ﴿وَالمَنْطُوحَةُ﴾ .\n\n١١٠٢٣- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك:\"والنطيحة\"، الشاتان ينتطحان فيموتان.\n\n١١٠٢٤- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"والنطيحة\"، هي التي تنطحها الغنم والبقر فتموت.\n\nيقول: هذا حرام، لأن ناسًا من العرب كانوا يأكلونه. [[الأثر: ١١٠٢٤- يأتي بتمامه برقم: ١١٠٤٧.]]\n\n١١٠٢٥- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"والنطيحة\"، كان الكبشان ينتطحان، فيموت أحدهما، فيأكلونه.\n\n١١٠٢٦- حدثنا ابن بشار قال، حدثنا روح قال، حدثنا سعيد، عن قتادة:\"والنطيحة\"، الكبشان ينتطحان، فيقتل أحدهما الآخر، فيأكلونه.\n\n١١٠٢٧- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، أخبرنا عبيد قال، سمعت الضحاك، يقول في قوله:\"والنطيحة\"، قال: الشاة تنطح الشاة فتموت.\n\n* *\n\nالقول في تأويل قوله: ﴿وَمَا أَكَلَ السَّبُعُ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"وما أكل السبع\"، وحرّم عليكم ما أكل السبع غير المعَلَّم من الصوائد.\n\n* *\n\nوكذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠٢٨- حدثني المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية، عن علي، عن ابن عباس:\"وما أكل السبع\"، يقول: ما أخذ السبع.\n\n١١٠٢٩- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن جويبر، عن الضحاك:\"وما أكل السبع\"، يقول: ما أخذ السبع.\n\n١١٠٣٠- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة: \"وما أكل السبع\"، قال: كان أهل الجاهلية إذا قتل السبع شيئًا من هذا أو أكل منه، أكلوا ما بقي.\n\n١١٠٣١- حدثنا ابن وكيع قال، حدثنا أبو أحمد الزبيري، عن قيس، عن عطاء بن السائب، عن أبي الربيع، عن ابن عباس أنه قرأ: ﴿وأكيل السبع﴾ .\n\n* *\n\nالقول في تأويل قوله: ﴿إِلا مَا ذَكَّيْتُمْ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"إلا ما ذكَّيتم\"، إلا ما طهرتموه بالذبح الذي جعله الله طهورًا.\n\n* *\n\nثم اختلف أهل التأويل فيما استثنى الله بقوله:\"إلا ما ذكيتم\".\n\nفقال بعضهم: استثنى من جميع ما سمى الله تحريمه من قوله:\"وما أهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع\".\n\nذكر من قال ذلك:\n\n١١٠٣٢- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس:\"إلا ما ذكيتم\"، يقول: ما أدركتَ ذكاته من هذا كله، يتحرّك له ذنب، أو تطرِف له عين، فاذبح واذكر اسم الله عليه، فهو حلال.\n\n١١٠٣٣- حدثنا ابن وكيع قال، حدثنا ابن فضيل، عن أشعث، عن الحسن:\"حرمت عليكم الميتة والدم ولحم الخنزير وما أهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم\"، قال الحسن: أيَّ هذا أدركتَ ذكاته فذكِّه وكُلْ. فقلت: يا أبا سعيد، كيف أعرف؟ قال: إذا طرَفت بعينها، أو ضربت بذَنبها.\n\n١١٠٣٤- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"إلا ما ذكيتم\"، قال: فكلُّ هذا الذي سماه الله عز وجل ههنا، ما خلا لحم الخنزير، إذا أدركتَ منه عينًا تطرف، أو ذنبًا يتحرك، أو قائمة تركض [[\"الركض\": حركة الرجل واضطرابها، أو الضرب بها. و\"ارتكض الشيء\": إذا اضطرب.]] فذكّيته، فقد أحلّ الله لك ذلك.\n\n١١٠٣٥- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة:\"إلا ما ذكيتم\"، من هذا كله. فإذا وجدتها تطرف عينها، أو تحرك أذنها من هذا كله، فهي لك حلال.\n\n١١٠٣٦- حدثنا القاسم قال، حدثنا الحسين قال، حدثني هشيم وعباد قالا أخبرنا حجاج، عن حصين، عن الشعبي، عن الحارث، عن علي قال: إذا أدركت ذكاة الموقوذة والمتردية والنطيحة، وهي تحرك يدًا أو رجلا فكلها.\n\n١١٠٣٧- حدثنا القاسم قال، حدثنا الحسين قال، حدثنا هشيم قال، أخبرنا معمر، عن إبراهيم قال: إذا أكل السبع من الصيد، أو الوقيذة أو النطيحة أو المتردية، فأدركت ذكاته، فكُل.\n\n١١٠٣٨- حدثنا أبو كريب قال، حدثنا مصعب بن سلام التميمي قال، حدثنا جعفر بن محمد، عن أبيه، عن علي بن أبي طالب قال: إذا ركضت برجلها، أو طرفت بعينها، وحركت ذنبها، فقد أجزأ. [[الأثر: ١١٠٣٨-\"مصعب بن سلام التميمي\" مضت ترجمته برقم: ٥٣٨٢.\n\nو\"جعفر بن محمد بن علي بن الحسين بن علي بن أبي طالب\"، هو\"جعفر الصادق\"، مضت ترجمته برقم: ٢٠٠٣.\n\nو\"أبوه\": \"محمد بن علي بن الحسين\"، وهو\"محمد الباقر\" مضى برقم: ٥١٢٣، ٥٤٦٣.]]\n\n١١٠٣٩- حدثنا ابن المثنى وابن بشار قالا حدثنا أبو عاصم قال، أخبرنا ابن جريج قال، أخبرني ابن طاوس، عن أبيه قال: إذ ذبحت فَمَصَعَت بذنبها، أو تحركت، فقد حلَّت لك = أو قال: فَحَسْبه. [[\"مصعت بذنبها\": حركته وضربت به. وكان في المطبوعة: \"أو قال: فحسب\"، والصواب من المخطوطة، أي: ذلك حسبه وكافيه ومجزئه، يعني من أراد أكلها.]]\n\n١١٠٤٠- حدثنا ابن المثنى قال، حدثنا الحجاج بن المنهال قال، حدثنا حماد، عن حميد، عن الحسن قال: إذا كانت الموقوذة تطرف ببصرها، أو تركض برجلها، أو تمصَع بذنبها، فاذبح وكُل.\n\n١١٠٤١- حدثني المثنى قال، حدثنا الحجاج قال، حدثنا حماد، عن قتادة، بمثله.\n\n١١٠٤٢- حدثني المثنى قال، حدثنا سويد قال، أخبرنا ابن المبارك، عن ابن جريج، عن أبي الزبير، أنه سمع عبيد بن عمير يقول: إذا طرفت بعينها، أو مصعت بذنبها، أو تحركت، فقد حلَّت لك.\n\n١١٠٤٣- حدثت عن الحسين قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سليمان قال، سمعت الضحاك يقول: كان أهل الجاهلية يأكلون هذا، فحرَّم الله في الإسلام إلا ما ذُكِّي منه، فما أُدرك فتحرّك منه رجل أو ذنب أو طَرف، فذكِّي، فهو حلال.\n\n١١٠٤٤- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"حرمت عليكم الميتة والدم ولحم الخنزير\"، وقوله:\"والمنخنقة والموقوذة والمتردِّية والنطيحة\"، الآية\"وما أكل السبع إلا ما ذكيتم\"، قال: هذا كله محرّم، إلا ما ذكيّ من هذا.\n\n* *\n\nفتأويل الآية على قول هؤلاء: حرمت الموقوذة والمتردِّية، إن ماتت من التردِّي والوقذ والنطح وفَرْس السبع، إلا أن تدركوا ذكاتها، فتدركوها قبل موتها، فتكون حينئذ حلالا أكلُها.\n\n* *\n\nوقال آخرون: هو استثناء من التحريم، وليس باستثناء من المحرَّمات التي ذكرها الله تعالى في قوله:\"حرمت عليكم الميتة\"، لأن الميتة لا ذكاة لها، ولا للخنزير. قالوا: وإنما معنى الآية: حرمت عليكم الميتة والدم وسائر ما سمينا مع ذلك، إلا ما ذكيتم مما أحلَّه الله لكم بالتذكية، فإنه لكم حلال. وممن قال ذلك جماعة من أهل المدينة.\n\nذكر بعض من قال ذلك:\n\n١١٠٤٥- حدثني يونس قال: أخبرنا ابن وهب قال، قال مالك، وسئل عن الشاة التي يخرِق جوفها السبع حتى تخرجَ أمعاؤها، فقال مالك: لا أرى أن تذكَّى، ولا يؤكل أي شيء يذكَّى منها.\n\n١١٠٤٦- حدثني يونس، عن أشهب قال: سئل مالك عن السبع يَعْدُو على الكبش فيدقُّ ظهره، أترى أن يذكَّى قبل أن يموت فيؤكل؟ قال: إن كان بلغ السَّحْر [[\"السحر\" (بفتح فسكون) : هو الرئة، أو ما التزق بالحلقوم والمريء من أعلى البطن.]] فلا أرى أن يؤكل. وإن كان إنما أصاب أطرافه، فلا أرى بذلك بأسًا. قيل له: وثب عليه فدقَّ ظهره؟ قال: لا يعجبني أن يؤكل، هذا لا يعيش منه. قيل له: فالذئب يعدو على الشاة فيشق بطنها ولا يشق الأمعاء؟ قال: إذا شق بطنها، فلا أرى أن تؤكل.\n\n* *\n\nوعلى هذا القول يجب أن يكون قوله:\"إلا ما ذكيتم\"، استثناء منقطعًا.\n\n= فيكون تأويل الآية: حرمت عليكم الميتة والدم وسائر ما ذكرنا، ولكن ما ذكيتم من الحيوانات التي أحللتها لكم بالتذكية حلال.\n\n* *\n\nقال أبو جعفر: وأولى القولين في ذلك عندنا بالصواب، القول الأول، وهو أن قوله:\"إلا ما ذكيتم\" استثناء من قوله:\"وما أهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع\"، لأن كل ذلك مستحق الصفة التي هو بها قبل حال موته [[في المخطوطة: \"موتها\"، وهما سواء.]] فيقال لما قرَّب المشركون لآلهتهم فسموه لهم:\"هو ما أهل لغير الله به\"، بمعنى سمى قربانًا لغير الله. وكذلك\"المنخنقة\"، إذا انخنقت وإن لم تمت، فهي منخنقة. وكذلك سائر ما حرمه الله جل وعز بعد قوله:\"وما أهل لغير الله به\"، إلا بالتذكية، فإنه يوصف بالصفة التي هو بها قبل موته، فحرمه الله على عباده إلا بالتذكية المحللة، دون الموت بالسبب الذي كان به موصوفًا. فإذ كان ذلك كذلك، فتأويل الآية: وحرم عليكم ما أهل لغير الله به والمنخنقة وكذا وكذا وكذا، إلا ما ذكيتم من ذلك.\n\nفـ\"ما\" = إذ كان ذلك تأويله = في موضع نصب بالاستثناء مما قبلها. وقد يجوز فيه الرفع.\n\nوإذ كان الأمر على ما وصفنا، فكل ما أدركت ذكاتُه من طائر أو بهيمة قبل خروج نفسه، ومفارقة روحه جسدَه، فحلال أكله، إذا كان مما أحلَّه الله لعباده.\n\n* *\n\nفإن قال لنا قائل: فإذ كان ذلك معناه عندك، فما وجه تكريره ما كرّر بقوله:\"وما أهل لغير الله به والمنخنقة والموقوذة والمتردية\"، وسائر ما عدَّد تحريمه في هذه الآية، وقد افتتح الآية بقوله:\"حرمت عليكم الميتة\"؟ وقد علمت أن قوله:\"حرمت عليكم الميتة\"، شامل كل ميتة، كان موته حتف أنفه من علة به من غير جناية أحد عليه، أو كان موته من ضرب ضاربٍ إياه، أو انخناق منه، أو انتطاح، أو فَرْس سبع؟ وهلا كان قوله = إن كان الأمر على ما وصفت في ذلك، من أنه معنيٌّ بالتحريم في كل ذلك: الميتة بالانخناق والنطاح والوقذ وأكل السبع أو غير ذلك، دون أن يكون معنيًّا به تحريمه إذا تردّى أو انخنق أو فرسه السبع، فبلغ ذلك منه ما يعلم أنه لا يعيش مما أصابه منه إلا باليسير من الحياة [[سياق هذه العبارة المطولة: \"وهلا كان قوله..: حرمت عليكم الميتة، مغنيًا من تكرير ما كرر.. وتعداده ما عدد\"، وما بينهما فصل وضعته بين خطين.]] \"حرمت عليكم الميتة\"، مغنيًا من تكرير ما كرر بقوله:\"وما أهل لغير الله به والمنخنقة\"، وسائر ما ذكر مع ذلك، وتَعْدادِه ما عدَّد؟\n\nقيل: وجه تكراره ذلك = وإن كان تحريم ذلك إذا مات من الأسباب التي هو بها موصوف، وقد تقدم بقوله:\"حرمت عليكم الميتة\" = أن الذين خوطبوا بهذه الآية كانوا لا يعدُّون\"الميتة\" من الحيوان، إلا ما مات من علة عارضة به غير الانخناق والتردِّي والانتطاح وفرس السبع. فأعلمهم الله أن حكم ذلك، حكم ما مات من العلل العارضة = وأن العلة الموجبة تحريم الميتة، ليست موتها من علة مرض أو أذى كان بها قبل هلاكها، ولكن العلة في ذلك أنها لم يذبحها من أجل ذبيحته بالمعنى الذي أحلها به [[في المطبوعة: \"من أحل ذبيحته\"، والصواب ما في المخطوطة، وهي فيها منقوطة. ويعني: من أجل أن تكون ذبيحة له ياكلها.]] كالذي:-\n\n١١٠٤٧- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي في قوله:\"والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم\"، يقول: هذا حرام، لأن ناسًا من العرب كانوا يأكلونه ولا يعدّونه ميتًا، إنما يعدون الميت الذي يموت من الوجع. فحرمه الله عليهم، إلا ما ذكروا اسم الله عليه، وأدركوا ذكاته وفيه الروح. [[الأثر: ١١٠٤٧- هو تمام الأثر السالف رقم: ١١٠٢٤.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَمَا ذُبِحَ عَلَى النُّصُبِ﴾\n\nقال أبو جعفر: يعني بقوله جل ثناؤه:\"وما ذبح على النصب\"، وحرم عليكم أيضًا الذي ذبح على النُّصُب.\n\nفـ\"ما\" في قوله:\"وما ذبح\"، رفْعٌ، عطفًا على\"ما\" التي في قوله:\"وما أكل السبع\".\n\nو\"النصب\"، الأوثان من الحجارة، جماعة أنصاب كانت تجمع في الموضع من الأرض، فكان المشركون يقرِّبون لها، وليست بأصنام.\n\nوكان ابن جريج يقول في صفته ما:-\n\n١١٠٤٨- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج قال، قال ابن جريج:\"النصب\" ليست بأصنام،\"الصنم\" يصوَّر وينقش، وهذه حجارة تنصب، ثلثمئة وستون حجرًا [[قوله: \"ثلثمئة وستون حجرًا\"، يعني عدة الأنصاب التي كانت حول الكعبة، انظر ابن سعد ٢/١/٩٨: \"وطاف رسول الله ﷺ، وحول الكعبة ثلثمئة وستون صنما\"، ولكن هذه أصنام لا أنصاب كما ترى.]] منهم من يقول ثلثمئة منها لخزاعة [[في المطبوعة والمخطوطة: \"بخزاعة\" بالباء، والصواب ما أثبت.]] = فكانوا إذا ذبحوا نضحوا الدم على ما أقبل من البيت [[\"نضح الدم أو الماء\": رشه به.]] وشرَّحوا اللحم وجعلوه على الحجارة. [[\"شرح اللحم\"، وهو أن يقطع بضعة من اللحم ويرققها، حتى تشف من رقتها. و\"الشريحة\": القطعة المرققة منه كذلك.]] فقال المسلمون: يا رسول الله، كان أهل الجاهلية يعظمون البيت بالدم، فنحن أحقُّ أن نعظمه! فكأن النبي ﷺ لم يكره ذلك، فأنزل الله: ﴿لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلا دِمَاؤُهَا﴾ [سورة الحج: ٣٧] .\n\n* *\n\nومما يحقق قول ابن جريج في أن\"الأنصاب\" غير\"الأصنام\"، ما:-\n\n١١٠٤٩- حدثنا به ابن وكيع قال: حدثنا ابن عيينة، عن ابن أبي نجيح، عن مجاهد:\"وما ذبح على النصب\"، قال: حجارة كان يذبح عليها أهل الجاهلية.\n\n١١٠٥٠- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله:\"النصب\"، قال: حجارة حول الكعبة، يذبح عليها أهل الجاهلية، ويبدِّلونها إذا شاؤوا بحجارة أعجب إليهم منها.\n\n١١٠٥١- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١١٠٥٢- حدثنا بشر بن معاذ قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"وما ذبح على النصب\"، و\"النصب\": حجارة كان أهل الجاهلية يعبدونها، ويذبحون لها، فنهى الله عن ذلك.\n\n١١٠٥٣- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:\"وما ذبح على النصب\"، يعني: أنصابَ الجاهلية.\n\n١١٠٥٤- حدثنا المثنى قال، حدثنا أبو صالح قال، حدثني معاوية، عن علي بن أبي طلحة، عن ابن عباس:\"وما ذبح على النصب\"، و\"النصب\"، أنصاب كانوا يذبحون ويُهِلُّون عليها.\n\n١١٠٥٥- حدثنا ابن حميد قال، حدثنا حكام، عن عنبسة، عن محمد بن عبد الرحمن، عن القاسم بن أبي بزة، عن مجاهد قوله:\"وما ذبح على النصب\"، قال: كان حول الكعبة حجارة كان يَذبح عليها أهل الجاهلية، ويبدِّلونها إذا شاؤوا بحجر هو أحبّ إليهم منها.\n\n١١٠٥٦- حدثت عن الحسين قال، سمعت أبا معاذ يقول، أخبرنا عبيد قال، سمعت الضحاك بن مزاحم يقول:\"الأنصاب\"، حجارة كانوا يهلّون لها، ويذبحون عليها.\n\n١١٠٥٧- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"وما ذبح على النُّصب\"، قال:\"ما ذبح على النصب\" و\"ما أهل لغير الله به\"، وهو واحد. [[في المطبوعة: \"هو واحد\"، بغير واو، والذي في المخطوطة أجود.]]\n\n* *\n\nالقول في تأويل قوله: ﴿وَأَنْ تَسْتَقْسِمُوا بِالأزْلامِ﴾\n\nقال أبو جعفر: يعني بقوله:\"وأن تستقسموا بالأزلام\"، وأن تطلبوا علم ما قُسِم لكم أو لم يقسم، بالأزلام.\n\n* *\n\nوهو\"استفعلت\" من\"القَسْم\" قَسْم الرزق والحاجات. وذلك أن أهل الجاهلية كان أحدهم إذا أراد سفرًا أو غزوًا أو نحو ذلك، أَجال القداح = وهي\"الأزلام\" وكانت قِداحًا مكتوبًا على بعضها:\"نهاني ربّي\"، وعلى بعضها:\"أمرني ربّي\" = فإن خرج القدح الذي هو مكتوب عليه:\"أمرني ربي\"، مضى لما أراد من سفر أو غزو أو تزويج وغير ذلك. وإن خرج الذي عليه مكتوب:\"نهاني ربي\"، كفّ عن المضي لذلك وأمسك، فقيل:\"وأن تستقسموا بالأزلام\"، لأنهم بفعلهم ذلك كانوا كأنهم يسألون أزلامهم أن يَقْسِمن لهم، ومنه قول الشاعر مفتخرًا بترك الاستقسام بها: [[أعياني أن أعرف قائله، وهو شبيه بكلام أمية بن أبي الصلت، وليس في ديوانه.]]\n\nوَلَمْ أَقْسِمْ فَتَرْبُثَنِي القُسُومُ [[مجاز القرآن لأبي عبيدة ١: ١٥٢، وقوله\"لم أقسم\"، من\"قسمت أمري أقسمه قسما\"، أي: قدرته ونظرت، وميلت فيه أن أفعله أو لا أفعله. وقالوا: \"تركت فلانًا يقتسم، وتركته يستقسم\": أي يفكر ويروي بين أمرين. وكذلك فعل من يستقسم بالأزلام، فاستعمل\"أقسم\" بمعنى\"الاستقسام بالأزلام\" في هذا البيت. و\"القسوم\" جمع\"قسم\" (بكسر القاف وسكون السين) : الحظ، وجمعه\"أقسام\"، ولكنه جمع على\"قسوم\"، كجمع\"حلم\" على\"حلوم\" و\"أحلام\".]]\n\n* *\n\nوأما\"الأزلام\"، فإن واحدها\"زَلَم\"، ويقال:\"زُلَم\"، وهي القداح التي وصفنا أمرها. [[\"زلم\" (بفتحتين) و\"زلم\" (بضم الزاي وفتح اللام) .]]\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠٥٨- حدثنا محمد بن بشار وابن وكيع قالا حدثنا عبد الرحمن بن مهدي، عن سفيان، عن أبي حصين، عن سعيد بن جبير:\"وأن تستقسموا بالأزلام\"، قال: القداح، كانوا إذا أرادوا أن يخرجوا في سفر جعلوا قداحًا للجلوس والخروج. فإن وقع الخروج خرجوا، وإن وقع الجلوس جلسوا.\n\n١١٠٥٩- حدثنا ابن وكيع قال، حدثنا أبي، عن شريك، عن أبي حصين، عن سعيد بن جبير:\"وأن تستقسموا بالأزلام\"، قال: حصًى بيضٌ كانوا يضربون بها.\n\n= قال أبو جعفر: قال لنا سفيان بن وكيع: هو الشطرنج. [[هذا قول في غاية الغرابة!! كأنه كان يجهل ما الشطرنج = أو كأنه كان يرى أنهم يفعلون ذلك بقطع الشطرنج، دون أن يكون هذا الفعل هو اللعب بالشطرنج.]]\n\n١١٠٦٠- حدثني يعقوب قال، حدثنا هشيم قال، أخبرنا عباد بن راشد البزّار، عن الحسن في قوله:\"وأن تستقسموا بالأزلام\"، قال: كانوا إذا أرادوا أمرًا أو سفرًا، يعمَدون إلى قداح ثلاثة، على واحد منها مكتوب:\"أؤمرني\"، وعلى الآخر:\"انهني\"، ويتركون الآخر محلَّلا بينهما ليس عليه شيء. ثم يجيلونها، فإن خرج الذي عليه\"أؤمرني\" مضوا لأمرهم. وإن خرج الذي عليه\"انهني\" كفُّوا، وإن خرج الذي ليس عليه شيء أعادوها. [[الأثر: ١١٠٦٠-\"عباد بن راشد التميمي البزار\"، ابن أخت داود بن أبي هند. روى عن ثابت البناني، والحسن البصري، وداود بن أبي هند، وقتادة. روى عنه هشيم، وعبد الرزاق، وأبو عامر العقدي، وغيرهم. ذكره البخاري في الضعفاء، وروى له مقرونًا بغيره، متكلم فيه. مترجم في التهذيب.]]\n\n١١٠٦١- حدثنا ابن وكيع قال، حدثنا ابن عيينة، عن ابن أبي نجيح، عن مجاهد:\"وأن تستقسموا بالأزلام\"، حجارة كانوا يكتبون عليها، يسمونها\"القِداح\".\n\n١١٠٦٢- حدثني محمد بن عمرو قال، حدثنا أبو عاصم قال، حدثنا عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله:\"بالأزلام\"، قال: القداح، يضربون لكل سفر وغزوٍ وتجارة.\n\n١١٠٦٣- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١١٠٦٤- حدثنا ابن وكيع قال، حدثنا يحيى بن آدم، عن زهير، عن إبراهيم بن مهاجر، عن مجاهد:\"وأن تستقسموا بالأزلام\"، قال: كِعابُ فارس التي يقمُرون بها، وسهام العرب.\n\n١١٠٦٥- حدثني أحمد بن حازم الغفاري قال، حدثنا أبو نعيم قال، حدثنا زهير، عن إبراهيم بن مهاجر، عن مجاهد:\"وأن تستقسموا بالأزلام\"، قال: سهام العرب، وكعاب فارس والروم، كانوا يتقامرون بها.\n\n١١٠٦٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة في قوله:\"وأن تستقسموا بالأزلام\"، قال: كان الرجل إذا أراد أن يخرج مسافرًا، كتب في قدح:\"هذا يأمرني بالمكث\" و\"هذا يأمرني بالخروج\"، وجعل معهما منيحة. [[في المطبوعة والمخطوطة: \"معها\"، والصواب التثنية. وفي المطبوعة: \"منيحًا\"، وهو صواب في المعنى. ولكني أثبت ما في المخطوطة. وذلك أن\"المنيح\" -كما في المطبوعة- هو القدح المستعار من قداح الميسر، وهو الغفل الذي لا نصيب له، إلا أن يمنح صاحبه شيئًا، فيستعار ويتيمن به. وأما \"المنيحة\"، فهي الناقة أو الشاة المعارة أيضًا، فنظر إلى معنى المستعار فسمى هذا الشيء الذي لا أمر له في الاستقسام\"منيحة\"، كما سموا شبيهه في الميسر\"منيحًا\" وهو المستعار.]] شيء لم يكتب فيه شيئًا، ثم استقسم بها حين يريد أن يخرج. فإن خرج الذي يأمر بالمكث مكث، وإن خرج الذي يأمر بالخروج خرج، وإن خرج الآخر أجالها ثانية حتى يخرج أحد القِدْحين.\n\n١١٠٦٧- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"وأن تستقسموا بالأزلام\"، وكان أهل الجاهلية إذا أراد أحدهم خروجًا، أخذ قدحًا فقال:\"هذا يأمر بالخروج\"، فإن خرج فهو مصيب في سفره خيرًا، ويأخذ قِدحًا آخر فيقول:\"هذا يأمر بالمكوث\"، فليس يصيب في سفره خيرًا، و\"المنيح\" بينهما. فنهى الله عن ذلك وقدَّم فيه.\n\n١١٠٦٨- حدثت عن الحسين بن الفرج قال، سمعت أبا معاذ يقول، أخبرنا عبيد قال، سمعت الضحاك يقول في قوله:\"وأن تستقسموا بالأزلام\"، قال: كانوا يستقسمون بها في الأمور.\n\n١١٠٦٩- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد:\"الأزلام\"، قداح لهم. كان أحدهم إذا أراد شيئًا من تلك الأمور كتب في تلك القداح ما أراد، فيضرب بها، فأي قدح خرج = وإن كان أبغض تلك = ارتكبه وعمل به.\n\n١١٠٧٠- حدثني محمد بن الحسين قال، حدثنا أحمد بن المفضل، قال، حدثنا أسباط، عن السدي:\"وأن تستقسموا بالأزلام\"، قال:\"الأزلام\"، قداح كانت في الجاهلية عند الكهنة، فإذا أراد الرجل أن يسافر، أو يتزوج، أو يحدث أمرًا، أتى الكاهن فأعطاه شيئًا، فضرب له بها. فإن خرج منها شيء يعجبه، أمره ففعل. وإن خرج منها شيء يكرهه، نهاه فانتهى، كما ضرب عبد المطلب على زمزم، وعلى عبد الله والإبل. [[انظر خبر عبد المطلب وعبد الله في سيرة ابن هشام ١: ١٦٠-١٦٤.]]\n\n١١٠٧١- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج، عن عبد الله بن كثير قال: سمعنا أنّ أهل الجاهلية كانوا يضربون بالقداح في الظَّعْن والإقامة أو الشيء يريدونه، فيخرج سهم الظعن فيظعنون، والإقامة فيقيمون.\n\n* *\n\nوقال ابن إسحاق في\"الأزلام\"، ما:-\n\n١١٠٧٢- حدثني به ابن حميد قال، حدثنا سلمة، عن ابن إسحاق قال: كانت هُبَل أعظم أصنام قريش بمكة، وكانت على بئر في جوف الكعبة، وكانت تلك البئْر هي التي يجمع فيها ما يُهدي للكعبة. وكانت عند هبل سبعة أقْدُح [[في المطبوعة: \"أقداح\"، وأثبت ما في المخطوطة، وجمع\"قدح\": أقداح، وقداح، وأقدح، كله صواب.]] كل قِدْح منها فيه كتاب. قدح فيه:\"العقل\" [[\"العقل\" الدية.]] إذا اختلفوا في العقل من يحمله منهم، ضربوا بالقداح السبعة، [فإن خرج العقل، فعلى من خرج حمله] [[هذه الزيادة بين القوسين من ابن هشام، ولا بد من زيادتها لتمام الكلام.]] وقدح فيه:\"نعم\" للأمر إذا أرادوه، يضرب به، فإن خرج قدح\"نعم\" عملوا به. وقدح فيه:\"لا\"، فإذا أرادوا أمرًا ضربوا به في القداح، فإذا خرج ذلك القدح، لم يفعلوا ذلك الأمر. وقِدْح فيه:\"منكم\". وقدح فيه:\"مُلْصَق\". [[في المخطوطة: \"يلصق\"، وفوقها\"كذا\"، أي هو كذلك في التي نسخ عنها، والصواب ما في المطبوعة، وسيرة ابن هشام.]] وقدح فيه:\"من غيركم\". وقدح فيه:\"المياه\"، إذا أرادوا أن يحفروا للماء ضربوا بالقداح وفيها ذلك القدح، فحيثما خرج عملوا به. وكانوا إذا أرادوا أن يختنوا غلامًا [[في المطبوعة: \"أن يجتبوا غلامًا\"، وهو لا معنى له، والمخطوطة غير منقوطة، والصواب، في سيرة ابن هشام، كما أثبتها.]] أو أن ينكحوا مَنكحًا، أو أن يدفنوا ميتًا، أو شكوا في نسب واحد منهم [[في المطبوعة: \"أو يشكوا\" مضارعًا، وأثبت ما في سيرة ابن هشام.]] ذهبوا به إلى هبل وبمئة درهم، وبجَزور، فأعطوها صاحب القداح الذي يضربها، ثم قرّبوا صاحبهم الذي يريدون به ما يريدون، ثم قالوا:\"يا إلهنا، هذا فلان بن فلان، قد أردنا به كذا وكذا، فأخرج الحق فيه\". ثم يقولون لصاحب القداح:\"اضرب\"، فيضرب، فإن -[خرج عليه\"منكم\" كان وسيطًا. وإن] خرج عليه:\"من غيركم\"، كان حليفًا [[ما بين القوسين زيادة من ابن هشام، وهي السياق بغير شك. و\"الوسيط\": هو الخالص النسب، الشريف في قومه.]] وإن خرج\"ملصق\" كان على منزلته منهم، لا نسب له ولا حلف، وإن خرج فيه شيء سوى هذا مما يعملون به\"نعم\"، عملوا به. وإن خرج\"لا\"، أخّروه عامهم ذلك حتى يأتوا به مرة أخرى. ينتهون في أمورهم إلى ذلك مما خرجت به القداح. [[الأثر: ١١٠٧٢- سيرة ابن هشام ١: ١٦٠، ١٦١.]]\n\n١١٠٧٣- حدثني المثنى قال، حدثنا أبو صالح قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"وأن تستقسموا بالأزلام\"، يعني: القداح، كانوا يستقسمون بها في الأمور.\n\n* *\n\nالقول في تأويل قوله: ﴿ذَلِكُمْ فِسْقٌ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"ذلكم\"، هذه الأمور التي ذكرها، وذلك: أكل الميتة، والدم، ولحم الخنزير، وسائر ما ذكر في هذه الآية مما حرم أكله، والاستقسام بالأزلام، =\"فسق\"، يعني: خروج عن أمر الله عز ذكره وطاعته، إلى ما نهى عنه وزجر، إلى معصيته. [[انظر تفسير\"الفسق\" فيما سلف ١: ٤٠٩، ٤١٠/٢: ١١٨، ٣٩٩/٤: ١٣٥-١٣٧/٦: ٩١، ٩٢/٧: ١٠٧.\n\nوفي المطبوعة: \"وزجر، وإلى معصيته\" بزيادة الواو، وكلتاهما صواب.]] كما:-\n\n١١٠٧٤- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس:\"ذلكم فسق\"، يعني: من أكل من ذلك كله فهو فسق.\n\n* *\n\nالقول في تأويل قوله: ﴿الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِنْ دِينِكُمْ﴾\n\nقال أبو جعفر: يعني بقوله جل ثناؤه:\"اليوم يئس الذين كفروا من دينكم\"، الآن انقطع طمع الأحزاب وأهل الكفر والجحود، أيها المؤمنون، =\"من دينكم\"، يقول: من دينكم أن تتركوه فترتدُّوا عنه راجعين إلى الشرك، كما:-\n\n١١٠٧٥- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"اليوم يئس الذين كفروا من دينكم\"، يعني: أن ترجعوا إلى دينهم أبدًا.\n\n١١٠٧٦- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي قوله:\"اليوم يئس الذين كفروا من دينكم\"، قال: أظنُّ، يئسوا أن ترجعوا عن دينكم. [[أنا في شك من قوله: \"أظن\" هنا، وهي في المخطوطة غير منقوطة.]]\n\n* *\n\nفإن قال قائل: وأيُّ يوم هذا اليوم الذي أخبرَ الله أن الذين كفروا يئسوا فيه من دين المؤمنين؟\n\nقيل: ذكر أن ذلك كان يوم عرفة، عام حج النبي ﷺ حجة الوداع، وذلك بعد دخول العرب في الإسلام.\n\nذكر من قال ذلك:\n\n١١٠٧٧- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج، قال مجاهد:\"اليوم يئس الذين كفروا من دينكم\"،\"اليوم أكملت لكم دينكم\"، هذا حين فعلت. قال ابن جريج: وقال آخرون [[قوله: \"وقال آخرون\" هو من قول ابن جريج فيما أرجح، ولذلك جعلته في الخبر.]] ذلك يوم عرفة، في يوم جمعة، لما نظر النبي ﷺ فلم ير إلا موحِّدًا، ولم ير مشركًا، حمد الله، فنزل عليه جبريل عليه السلام:\"اليوم يئس الذين كفروا من دينكم\"، أن يعودوا كما كانوا.\n\n١١٠٧٨- حدثني يونس قال، أخبرنا ابن وهب قال، قال ابن زيد في قوله:\"اليوم يئس الذين كفروا من دينكم\"، قال: هذا يوم عرفة.\n\n* *\n\nالقول في تأويل قوله: ﴿فَلا تَخْشَوْهُمْ﴾\n\nقال أبو جعفر: يعني بذلك: فلا تخشوا، أيها المؤمنون، هؤلاء الذين قد يئسوا من دينكم أن ترجعوا عنه من الكفار، ولا تخافوهم أن يظهروا عليكم، فيقهروكم ويردُّوكم عن دينكم =\"واخشون\"، يقول: ولكن خافونِ، إن أنتم خالفتم أمري واجترأتم على معصيتي، وتعدَّيتم حدودي، أن أُحِلَّ بكم عقابي، وأنزل بكم عذابي. [[انظر تفسير\"الخشية\" فيما سلف ١: ٥٥٩، ٥٦٠/٢: ٢٣٩، ٢٤٣/٨: ٥٤٨.]] كما:-\n\n١١٠٧٩- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج:\"فلا تخشوهم واخشون\"، فلا تخشوهم أن يظهروا عليكم.\n\n* *\n\nالقول في تأويل قوله: ﴿الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾\n\nقال أبو جعفر: اختلف أهل التأويل في تأويل ذلك.\n\nفقال بعضهم: يعني جل ثناؤه بقوله:\"اليوم أكملت لكم دينكم\"، اليوم أكملت لكم، أيها المؤمنون، فرائضي عليكم وحدودي، وأمري إياكم ونهيي، وحلالي وحرامي، وتنزيلي من ذلك ما أنزلت منه في كتابي، وتبياني ما بيَّنت لكم منه بوحيي على لسان رسولي، والأدلة التي نصبتُها لكم على جميع ما بكم الحاجة إليه من أمر دينكم، فأتممت لكم جميع ذلك، فلا زيادة فيه بعد هذا اليوم. قالوا: وكان ذلك في يوم عرفة، عام حجَّ النبي ﷺ حجة الوَدَاع. وقالوا: لم ينزل على النبي ﷺ بعد هذه الآية شيء من الفرائض، ولا تحليل شيء ولا تحريمه، وأن النبي ﷺ لم يعش بعد نزول هذه الآية إلا إحدى وثمانين ليلة.\n\nذكر من قال ذلك:\n\n١١٠٨٠- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"اليوم أكملت لكم دينكم\"، وهو الإسلام. قال: أخبر الله نبيَّه ﷺ والمؤمنين أنه قد أكمل لهم الإيمان، فلا يحتاجون إلى زيادة أبدًا، وقد أتمه الله عز ذكره فلا ينقصه أبدًا، وقد رضيه الله فلا يَسْخَطه أبدًا.\n\n١١٠٨١- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي قوله:\"اليوم أكملت لكم دينكم\"، هذا نزل يوم عرفة، فلم ينزل بعدها حلال ولا حرام. ورجع رسول الله ﷺ فمات. فقالت أسماء بنت عُمَيس: حججت مع رسول الله ﷺ تلك الحجة، فبينما نحن نسير، إذ تجلّى له جبريل ﷺ على الرَّاحلة، فلم تطق الراحلة من ثِقْل ما عليها من القرآن، فبركت، فأتيته فسجَّيت عليه برداء كان علي. [[\"سجاه بالثوب تسجية\": غطاه به.]]\n\n١١٠٨٢- حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج قال: مكث النبي ﷺ بعد ما نزلت هذه الآية، إحدى وثمانين ليلة، قوله:\"اليوم أكملت لكم دينكم\".\n\n١١٠٨٣- حدثنا سفيان قال، حدثنا ابن فضيل، عن هارون بن عنترة، عن أبيه قال: لما نزلت:\"اليوم أكملت لكم دينكم\"، وذلك يوم الحج الأكبر، بكى عمر، فقال له النبي ﷺ: ما يبكيك؟ قال: أبكاني أنّا كنا في زيادة من ديننا، فأما إذ كمل، فإنه لم يكمل شيء إلا نقص! فقال: صدقت. [[إنما عنى بنقصان الدين، أهل الدين، فإنهم إذا تطاول عليهم الأمد، قست قلوبهم، وقل تمسك بعضهم بما أمر به. ومعاذ الله أن يعني عمر، نقصان الدين نفسه. ومثله قوله ﷺ\"بدأ الإسلام غريبًا، وسيعود غريبًا كما بدأ، فطوبى للغرباء\".]]\n\n١١٠٨٤- حدثنا ابن وكيع قال، حدثنا أحمد بن بشير، عن هارون بن أبي وكيع، عن أبيه، فذكر نحو ذلك. [[الأثر: ١١٠٨٤-\"أحمد بن بشير الكوفي\"، مضى برقم: ٧٨١٩.\n\nو\"هرون بن أبي وكيع\"، هو: \"هرون بن عنترة بن عبد الرحمن\" الماضي في الأثر قبله، ومضت ترجمته برقم: ٤٠٥.\n\nوأبوه: \"عنترة بن عبد الرحمن\" وكنيته\"أبو وكيع\"، مضى أيضًا برقم: ٤٠٥.]]\n\n* *\n\nوقال آخرون: معنى ذلك:\"اليوم أكملت لكم دينكم\"، حجكم، فأفردتم بالبلد الحرام تحُجُّونه، أنتم أيها المؤمنون، دون المشركين، لا يخالطكم في حَجِّكم مشرك.\n\nذكر من قال ذلك:\n\n١١٠٨٥- حدثنا ابن وكيع قال، حدثنا يحيى بن أبي غَنِيَّة، عن أبيه، عن الحكم:\"اليوم أكملت لكم دينكم\"، قال: أكمل لهم دينهم: أن حجوا ولم يحجَّ معهم مشرك. [[الأثر: ١١٠٨٥-\"يحيى بن أبي غنية\" هو: \"يحيى بن عبد الملك بن حميد بن أبي غنية\"، مضى برقم: ١٠٥٩٧، وهو هذا الإسناد نفسه.\n\nوأبوه\"عبد الملك بن حميد بن أبي غنية\"، مضى أيضا برقم: ٨٥٣٥، ١٠٥٩٧.\n\nو\"الحكم\" هو\"الحكم بن عتيبة\" مضى مرارًا.\n\nوكان في المخطوطة والمطبوعة: \"يحيى بن أبي عتيبة\"، وهو تصحيف.]]\n\n١١٠٨٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة:\"اليوم أكملت لكم دينكم\"، قال: أخلص الله لهم دينهم، ونفى المشركين عن البيت.\n\n١١٠٨٧- حدثنا أحمد بن حازم قال، حدثنا أبو نعيم قال، حدثنا قيس، عن أبي حصين، عن سعيد بن جبير:\"اليوم أكملت لكم دينكم\"، قال: تمام الحج، ونفي المشركين عن البيت.\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في ذلك بالصواب، أن يقال: إن الله عز وجل أخبر نبيه ﷺ والمؤمنين به، أنه أكمل لهم = يوم أنزل هذه الآية على نبيه = دينَهم، بإفرادهم بالبلدَ الحرام [[في المطبوعة: \"بإفرادهم بالبلد الحرام\" بالباء، وهو الذي تقوله كتب اللغة، وأما الذي في المخطوطة، وهو ما أثبته. فله وجه صحيح في العربية، فيما أرى، فتركته على حاله. وظني أني قرأته كذلك متعديًا في بعض كتب أبي جعفر أو غيره، فإن عثرت عليه أثبته إن شاء الله.]] وإجلائه عنه المشركين، حتى حجَّه المسلمون دونهم لا يخالطهم المشركون.\n\nفأما الفرائض والأحكام، فإنه قد اختلف فيها: هل كانت أكملت ذلك اليوم، أم لا؟ فروي عن ابن عباس والسدّي ما ذكرنا عنهما قبل. [[يعني ما سلف رقم: ١١٠٨٠، ١١٠٨١.]]\n\nوروي عن البراء بن عازب أن آخر آية نزلت من القرآن: ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلالَةِ﴾ [سورة النساء: ١٧٦] . [[انظر ما سلف رقم: ١٠٨٧٠- ١٠٨٧٣.]]\n\n= ولا يدفع ذو علم أن الوحي لم ينقطع عن رسول الله ﷺ إلى أن قُبِض، بل كان الوحي قبل وفاته أكثر ما كان تتابعًا. فإذ كان ذلك كذلك = وكان قوله: ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلالَةِ﴾ آخرَها نزولا وكان ذلك من الأحكام والفرائض = كان معلومًا أن معنى قوله:\"اليوم أكملت لكم دينكم\"، على خلاف الوجه الذي تأوَّله من تأوَّله = أعني: كمال العبادات والأحكام والفرائض.\n\nفإن قال قائل: فما جعل قولَ من قال:\"قد نزل بعد ذلك فرض\"، أولى من قول من قال:\"لم ينزل\"؟\n\nقيل: لأن الذي قال:\"لم ينزل\"، مخبر أنه لا يعلم نزول فرض، والنفي لا يكون شهادة، والشهادة قول من قال:\"نزل\". وغير جائز دفع خبر الصادق فيما أمكن أن يكون فيه صادقًا.\n\n* *\n\nالقول في تأويل قوله: ﴿وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي﴾\n\nقال أبو جعفر: يعني جل ثناؤه بذلك: وأتممت نعمتي، أيها المؤمنون، بإظهاركم على عدوِّي وعدوكم من المشركين، ونفيِي إياهم عن بلادكم، وقطعي طمعهم من رجوعكم وعودكم إلى ما كنتم عليه من الشرك.\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٠٨٨- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قال: كان المشركون والمسلمون يحجُّون جميعًا، فلما نزلت\"براءة\"، فنفى المشركين عن البيت، وحجَّ المسلمون لا يشاركهم في البيت الحرام أحد من المشركين، فكان ذلك من تمام النعمة:\"وأتممت عليكم نعمتي\".\n\n١١٠٨٩- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي\" الآية، ذكر لنا أن هذه الآية نزلت على رسول الله ﷺ يوم عرفة، يوم جمعة، حين نفى الله المشركين عن المسجد الحرام، وأخلص للمسلمين حجَّهم.\n\n١١٠٩٠- حدثنا أبو كريب قال، حدثنا ابن إدريس قال، حدثنا داود، عن الشعبي قال: نزلت هذه الآية بعرفات، حيث هدم مَنار الجاهلية [[\"المنار\": علم الطريق، وحدود الأرض. وأراد به شرائع أهل الجاهلية.]] واضمحلَّ الشرك، ولم يحج معهم في ذلك العام مشرك.\n\n١١٠٩١- حدثنا ابن المثنى قال، حدثنا عبد الأعلى قال، حدثنا داود، عن عامر في هذه الآية:\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي\"، قال، نزلت على رسول الله ﷺ وهو واقف بعرفات، وقد أطاف به الناس، وتهدَّمت مَنار الجاهلية ومناسكهم، واضمحلّ الشرك، ولم يَطُف حول البيت عُرْيان، فأنزل الله:\"اليوم أكملت لكم دينكم\".\n\n١١٠٩٢- حدثني يعقوب قال، حدثنا ابن علية، عن داود، عن الشعبي، بنحوه.\n\n* *\n\nالقول في تأويل قوله: ﴿وَرَضِيتُ لَكُمُ الإسْلامَ دِينًا﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: ورضيت لكم الاستسلام لأمري، والانقياد لطاعتي، على ما شرعت لكم من حدوده وفرائضه ومعالمه [[انظر تفسير\"الإسلام\" فيما سلف من فهارس اللغة، مادة (سلم) .]] =\"دينًا\"، يعني بذلك: طاعة منكم لي. [[انظر تفسير\"الدين\" فيما سلف ١: ١٥٥، ٢٢١/٣: ٥٧١، ٥٧٢/٦: ٢٧٣-٢٧٥، ٥٦٤، ٥٧٠.]]\n\n* *\n\nفإن قال قائل: أوَ ما كان الله راضيًا الإسلامَ لعباده إلا يوم أنزل هذه الآية؟\n\nقيل: لم يزل الله راضيًا لخلقه الإسلام دينًا، ولكنه جل ثناؤه لم يزل يصرِّف نبيه محمدًا ﷺ وأصحابه في درجات الإسلام ومراتبه درجة بعد درجة، ومرتبة بعد مرتبة، وحالا بعد حال، حتى أكمل لهم شرائعه ومعالمه، وبلغ بهم أقصى درجاته ومراتبه، ثم قال حين أنزل عليهم هذه الآية:\"ورضيت لكم الإسلام\" بالصفة التي هو بها اليوم [[في المطبوعة والمخطوطة: \"ورضيت لكم الإسلام دينًا، بالصفة..\"، والصواب حذف\"دينًا\" من هذا الموضع، لأنها ستأتي بعد، وهو سهو من عجلة الناسخ.]] والحال التي أنتم عليها اليوم منه =\"دينًا\" فالزموه ولا تفارقوه.\n\n* *\n\nوكان قتادة يقول في ذلك، ما:-\n\n١١٠٩٣- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قال: ذكر لنا أنه يَمْثُل لأهل كل دين دينهم يوم القيامة، فأما الإيمان فيبشر أصحابه وأهله ويعدهم في الخير، حتى يجيء الإسلام فيقول:\"رب، أنت السلام وأنا الإسلام\"، فيقول:\"إياك اليوم أقبل، وبك اليوم أجزي\". [[الأثر: ١١٠٩٣- روى أبو داود الطيالسي في مسنده: ٣٢٤ من حديث أبي هريرة: \"حدثنا عباد بن راشد قال، حدثنا الحسن قال، حدثنا أبو هريرة ونحن إذ ذاك في المدينة قال: يجيء الإسلام يوم القيامة، فيقول الله عز وجل: \"أنت الإسلام وأنا السَّلام، اليومَ بك أُعْطِي وبك آخُذ\".]]\n\n* *\n\n= وأحسب أن قتادة وجّه معنى\"الإيمان\" بهذا الخبر إلى معنى التصديق والإقرار باللسان، لأن ذلك معنى\"الإيمان\" عند العرب [[انظر تفسير\"الإيمان\" فيما سلف من فهارس اللغة، مادة (أمن) .]] = ووجَّه معنى\"الإسلام\" إلى استسلام القلب وخضوعه لله بالتوحيد، وانقياد الجسد له بالطاعة فيما أمر ونهى، فلذلك قيل للإسلام:\"إياك اليوم أقبل، وبك اليوم أجزي\".\n\n* *\n\nذكر من قال: نزلت هذه الآية بعرفة في حجة الوداع على رسول الله ﷺ.\n\n١١٠٩٤- حدثنا محمد بن بشار وابن وكيع قالا حدثنا عبد الرحمن قال، حدثنا سفيان، عن قيس بن مسلم، عن طارق بن شهاب قال، قالت اليهود لعمر: إنكم تقرأون آية لو أنزلت فينا لاتخذناها عيدًا! فقال عمر: إني لأعلم حين أنزلت، وأين أنزلت، وأين رسول الله ﷺ حين أنزلت: أنزلت يوم عرفة، ورسول الله ﷺ واقف بعرفة = قال سفيان: وأشك، كان يوم الجمعة أم لا =\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينًا. \" [[الأثر: ١١٠٩٤- رواه أحمد في المسند رقم: ٢٧٢ عن عبد الرحمن، عن سفيان بمثله. ورواه البخاري (الفتح ٨: ٢٠٣) عن محمد بن بشار، عن عبد الرحمن، كطريق أبي جعفر، ورواه مسلم ١٨: ١٥٢، عن محمد بن المثنى وزهير بن حرب، عن عبد الرحمن.\n\nوفيها جميعًا\"لأعلم حيث أنزلت\"، و\"وأين رسول الله ﷺ حيث أنزلت\"، وقد أشار إلى ذلك الحافظ في الفتح.\n\nوذكره الحافظ ابن كثير في تفسيره ٢: ٦٧، وزاد نسبته للترمذي والنسائي. ثم قال: \"وشك سفيان رحمه الله. إن كان في الرواية فهو تورع، حيث شك هل أخبره شيخه بذلك أم لا. وإن كان شكا في كون الوقوف في حجة الوداع كان يوم جمعة، فهذا مالا إخاله يصدر عن الثوري رحمه الله، فإن هذا أمر معلوم مقطوع به، لم يختلف فيه أحد من أصحاب المغازي والسير ولا الفقهاء. وقد وردت في ذلك أحاديث متواترة لا يشك في صحتها، والله أعلم\".]]\n\n١١٠٩٥- حدثنا أبو كريب وابن وكيع قالا حدثنا ابن إدريس قال، سمعت أبي، عن قيس بن مسلم، عن طارق بن شهاب قال، قال يهودي لعمر: لو علمنا معشر اليهود حين نزلت هذه الآية:\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينًا\"، لو نعلم ذلك اليوم، اتخذنا ذلك اليوم عيدًا! فقال عمر: قد علمت اليوم الذي نزلت فيه، والساعة، وأين رسول الله ﷺ حين نزلت: نزلت ليلة الجمعة، ونحن مع رسول الله ﷺ بعرفات = لفظ الحديث لأبي كريب، وحديث ابن وكيع نحوه. [[الأثر: ١١٠٩٥- رواه من هذه الطريق مسلم في صحيحه ١٨: ١٥٣، عن أبي بن أبي شيبة وأبي كريب، عن عبد الله بن إدريس.\n\nوفيه: \"نزلت ليلة جمع\". قال النووي في شرحه: \"هكذا هو في النسخ، الرواية: ليلة جمع = وفي نسخة ابن ماهان: ليلة جمعة. وكلاهما صحيح. فمن روى\"ليلة جمع\"، فهي ليلة المزدلفة، وهو المراد بقوله: \"ونحن بعرفات\" في يوم جمعة، لأن ليلة جمع، هي عشية يوم عرفات، ويكون المراد بقوله: \"ليلة جمعة\"، يوم جمعة. ومراد عمر رضي الله عنه: إنا قد اتخذنا ذلك اليوم عيدًا من وجهين، فإنه يوم عرفة، ويوم جمعة، وكل واحد منهما عيد لأهل الإسلام\".]]\n\n١١٠٩٦- حدثنا ابن وكيع قال، حدثنا جعفر بن عون، عن أبي العميس، عن قيس بن مسلم، عن طارق، عن عمر، نحوه. [[الأثر: ١١٠٩٦- هذا الحديث، رواه البخاري (الفتح ١: ٩٧) من طريق الحسن بن الصباح، عن جعفر بن عون، عن أبي العميس.\n\nورواه أحمد في المسند رقم: ١٨٨، من طريق جعفر بن عون، عن أبي عميس.\n\nورواه مسلم في صحيحه ١٨: ١٥٤، من طريق عبد بن حميد، عن جعفر بن عون، والنسائي في السنن ٨: ١١٤.\n\nهذا، وقد بين الحافظ ابن حجر في الفتح (١: ٩٧) أن هذا الرجل من اليهود: \"هو كعب الأحبار، بين ذلك مسدد في مسنده، والطبري في تفسيره، والطبراني في الأوسط، كلهم من طريق رجاء بن أبي سلمة، عن عبادة بن نسي (بضم النون، وفتح المهملة) ، عن إسحق بن خرشة، عن قبيصة بن ذؤيب، عن كعب\". وهذا هو الأثر الآتي رقم: ١١١٠٠ (انظر التعليق عليه، وما فيه من الخطأ) وأشار في الموضع الآخر (الفتح ٨: ٢٠٣) إلى احتمال أن سؤال كعب وقع قبل إسلامه، لأن إسلامه كان في خلافة عمر على المشهور، وأطلق عليه ذلك باعتبار ما مضى.]]\n\n١١٠٩٧- حدثنا ابن وكيع قال، حدثنا أبي، عن حماد بن سلمة، عن عمار مولى بني هاشم قال: قرأ ابن عباس:\"اليوم أكملت لكم دينكم\"، وعنده رجل من أهل الكتاب فقال: لو علمنا أيَّ يوم نزلت هذه الآية، لاتخذناه عيدًا! فقال ابن عباس: فإنها نزلت يوم عرفة، يوم جمعة. [[الأثر: ١١٠٩٧- خرجه أبو داود الطيالسي في مسنده: ٣٥٣، رواه عن حماد، عن عمار بن أبي عمار، وسيأتي بطريق أخرى في الذي يليه.]]\n\n١١٠٩٨- حدثنا أبو كريب قال، حدثنا قبيصة قال، حدثنا حماد بن سلمة، عن عمار: أن ابن عباس قرأ:\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينًا\"، فقال يهودي: لو نزلت هذه الآية علينا، لاتخذنا يومها عيدًا! فقال ابن عباس: فإنها نزلت في يوم عيدين اثنين: يوم عيد، ويوم جمعة. [[الأثر: ١١٠٩٨- خرجه الترمذي في كتاب التفسير، من طريق عبد بن حميد، عن يزيد بن هرون، عن حماد، وفيه: \"نزلت في يوم عيدين، في يوم الجمعة، ويوم عرفة\". وقال الترمذي: \"هذا حديث حسن غريب من حديث ابن عباس\".\n\nوأشار إليه السيوطي في الدر المنثور ٢: ٢٥٨، وزاد نسبته إلى عبد بن حميد، والطبراني، والبيهقي في الدلائل.]]\n\n١١٠٩٩- حدثني المثنى قال، حدثنا الحجاج بن المنهال قال، حدثنا حماد، عن عمار بن أبي عمار، عن ابن عباس، نحوه.\n\n١١١٠٠- حدثني يعقوب بن إبراهيم قال، حدثنا ابن علية قال، حدثنا رجاء بن أبي سلمة قال، أخبرنا عبادة بن نسيّ قال، حدثنا أميرنا إسحاق = قال أبو جعفر: إسحاق، هو ابن خَرَشة = عن قبيصة قال، قال كعب: لو أن غير هذه الأمة نزلت عليهم هذه الآية، لنظروا اليوم الذي أنزلت فيه عليهم، فاتخذوه عيدًا يجتمعون فيه! فقال عمر: أيُّ آية يا كعب؟ فقال:\"اليوم أكملت لكم دينكم\". فقال عمر: قد علمت اليوم الذي أنزلت فيه، والمكان الذي أنزلت فيه: يوم جمعة، ويوم عرفة، وكلاهما بحمد الله لنا عيدٌ. [[الأثر: ١١١٠٠-\"رجاء بن أبي سلمة مهران\"، \"أبو المقدام\" الفلسطيني. روى عن عمر بن عبد العزيز، وعمرو بن شعيب والزهري وغيرهم. وروى عنه ابن عون، وهو من شيوخه، والحمادان، وابن علية. ثقة، كان من أفاضل أهل زمانه. مترجم في التهذيب.\n\nو\"عبادة بن نسي الكندي\"، الشامي الأردني، قاضي طبرية. روى عن أوس بن أوس الثقفي، وشداد بن أوس، وعبادة بن الصامت، وكعب بن عجرة، وغيرهم. روى عنه رجاء بن أبي سلمة، وغيره. قال ابن سعد في تابعي أهل الشام: \"ثقة\". وقال البخاري: \"عبادة بن نسى الكندي\" سيدهم. قال مسلمة بن عبد الملك: \"إن في كندة لثلاثة نفر، إن الله لينزل بهم الغيث، وينصر بهم على الأعداء: عبادة بن نسي، ورجاء بن حيوة، وعدي بن عدي\". مات سنة ١١٨. مترجم في التهذيب، وابن أبي حاتم ٣/١/٩٦.\n\nو\"نسي\" بضم النون، وفتح السين، والياء المشددة\". وأما \"إسحق\"، فإن أبا جعفر زعم أنه ابن خرشة، ولم أجد في الرواة ولا في الأمراء\"إسحق بن خرشة\". وأما \"ابن خرشة\"، فهو: \"عثمان بن إسحق بن خرشة (بفتح الخاء والراء) القرشي\" روى عنه الزهري، ولم يذكر لعبادة بن نسي رواية عنه، ولا هو كان أميرًا. ونسبه كما رواه ابن سعد ٥: ١٨٠ هو: \"عثمان بن إسحق بن عبد الله بن أبي خرشة بن عمرو بن ربيعة بن الحارث بن حبيب بن جذيمة بن مالك بن حسل بن عامر بن لؤي\"، ونسبه أيضًا المصعب في نسب قريش: ٤٣٢، وقال: \"روى عنه ابن شهاب، عن قبيصة بن ذؤيب حديث الجدة\"، وهو الحديث الذي رواه أصحاب السنن الأربعة (سنن أبي داود ٣: ١٦٧ رقم: ٢٨٩٤) ، من طريق مالك في الموطأ: ٥١٣ بروايته عن\"ابن شهاب، عن عثمان بن إسحق بن خرشة، عن قبيصة بن ذؤيب\".\n\nفلست أشك أن أبا جعفر قد وهم، فأراد تعريف\"إسحق\" في إسناده هذا، فسبق إلى وهمه\"ابن خرشة\"، وهو\"عثمان بن إسحق بن خرشة\" لا\"إسحق بن خرشة\".\n\nأما \"إسحق\" في هذا الخبر، فلست أشك أنه\"إسحق بن قبيصة بن ذؤيب\"، يرويه عن أبيه\"قبيصة بن ذؤيب\".\n\nوذلك، أولا: لأن\"إسحق بن قبيصة بن ذؤيب الخزاعي\"، يروي عن أبيه، وعن كعب الأحبار.\n\nثانيا: أن\"عبادة بن نسي\" الأردني، قاضي طبرية، مذكور في ترجمته، وأنه يروي عن إسحق بن قبيصة بن ذؤيب.\n\nثالثًا: أن\"إسحق بن قبيصة بن ذؤيب\" هو الذي كان أميرًا، كان عامل هشام على الأردن، كما قال أبو زرعة الدمشقي. وقال ابن سميع: \"كان على ديوان الزمني في أيام الوليد\". وعبادة بن نسي قاض من قضاة الأردن كما ذكرت.\n\nفالذي لا شك فيه عندي، أن\"إسحق\" في هذا الإسناد: هو إسحق بن قبيصة بن ذؤيب، يروي عن أبيه، وأن أبا جعفر قد وهم في بيانه، وخلط.\n\nوقد أشرت في التعليق على الأثر رقم: ١١٠٩٦، ما نقله الحافظ ابن حجر في فتح الباري (١: ٩٧) ، نقلا عن هذا الموضع من الطبري، ولكنه نسبه أيضًا إلى مسدد في مسنده، وإلى الطبراني في الأوسط، وليسا عندي، ولكن إذا كان ذلك في واحد منهما، فإن الخطأ فيه، أقدم من أبي جعفر. وكتبه محمود محمد شاكر.\n\nوفي المطبوعة هنا: \"وكلاهما بحمد الله\"، وفي المخطوطة: \"وكليهما\"، ولها وجه في العربية.]]\n\n١١١٠١- حدثنا ابن حميد قال، حدثنا حكام، عن عنبسة، عن عيسى بن جارية الأنصاري قال: كنا جلوسًا في الديوان، فقال لنا نصراني: يا أهل الإسلام، لقد نزلت عليكم آية لو نزلت علينا، لاتخذنا ذلك اليوم وتلك الساعة عيدًا ما بقي منا اثنان:\"اليوم أكملت لكم دينكم\"! فلم يجبه أحد منا، فلقيت محمد بن كعب القرظي، فسألته عن ذلك فقال: ألا رددتم عليه؟ فقال: قال عمر بن الخطاب: أنزلت على النبي ﷺ وهو واقف على الجبل يوم عرفة، فلا يزال ذلك اليوم عيدًا للمسلمين ما بقي منهم أحد. [[الأثر: ١١١٠١-\"حكام\" هو\"حكام بن سلم الكناني\"، ثقة، روى عنه الطبري فأكثر فيما سلف، و\"عنبسة\" هو: عنبسة بن سعيد بن الضريس الأسدي، مضى مرارًا أيضًا، ترجم في رقم: ٢٢٤، ٣٣٥٦، ٥٣٨٥.\n\nو\"عيسى بن جارية الأنصاري\"، روى عن جرير البجلي، وجابر بن عبد الله، وابن المسيب، وغيرهم، وروى عنه يعقوب القمي، وعنبسة بن سعيد. تكلم فيه ابن معين قال: \"عنده مناكير\". وقال أبو داود: \"منكر الحديث\". مترجم في التهذيب، وابن أبي حاتم ٣/١/٢٧٣.\n\nوكان في المطبوعة والمخطوطة: \"عيسى بن حارثة\"، وهو خطأ.]]\n\n١١١٠٢- حدثنا حميد بن مسعدة قال، حدثنا بشر بن المفضل قال، حدثنا داود، عن عامر قال: أنزلت على رسول الله ﷺ:\"اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينًا\"، عشيَّة عرفة، وهو في الموقف.\n\n١١١٠٣- حدثنا ابن المثنى قال، حدثنا عبد الوهاب قال، حدثنا داود قال: قلت لعامر: إن اليهود تقول: كيف لم تحفظ العرب هذا اليوم الذي أكمل الله لها دينها فيه؟ فقال عامر: أو ما حفظته؟ قلت له: فأيّ يوم؟ قال: يوم عرفة، أنزل الله في يوم عرفة.\n\n١١١٠٤- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة قال: بلغنا أنها نزلت يوم عرفة، ووافق يوم الجمعة.\n\n١١١٠٥- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن حبيب، عن ابن أبي نجيح، عن عكرمة: أن عمر بن الخطاب قال: نزلت\"سورة المائدة\" يوم عرفة، ووافق يوم الجمعة.\n\n١١١٠٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا ابن عيينة، عن ليث، عن شهر بن حوشب قال: نزلت\"سورة المائدة\" على النبي ﷺ وهو واقف بعرفة على راحلته، فتنوَّخَتْ لأن يُدَقَّ ذراعها. [[\"أنخت البعير فاستناخ\"، و\"نوخته، فتنوخ\": أي برك. قال ابن الأعرابي: \"يقال تنوخ البعير، ولا يقال: ناخ، ولا أناخ\".\n\nوقوله: \"لأن يدق ذراعها\"، أي: مخافة أن يدق ذراعها.]]\n\n١١١٠٧- حدثنا ابن حميد قال، حدثنا جرير، عن ليث، عن شهر بن حوشب، عن أسماء بنت يزيد قالت: نزلت\"سورة المائدة\" جميعًا وأنا آخذة بزمام ناقة رسول الله ﷺ العضباء. قالت: فكادت من ثقلها أن يُدَقَّ عضد الناقة. [[الأثر: ١١١٠٧-\"أسماء بنت يزيد بن السكن\" الأنصارية الأشهلية، \"أم سلمة\"، كانت فيمن جهز عائشة لرسول الله ﷺ وزفها، وكانت تخدم النبي، وبايعته، وشهدت اليرموك.\n\nوهذا الحديث رواه أحمد في مسنده ٦: ٤٥٥ من طريق أبي النضر، عن شيبان، عن ليث. وفيه: \"وكادت من ثقلها تدق..\" ليس فيه\"أن\".\n\nثم رواه أيضًا ص: ٤٥٨ من طريق إسحق بن يوسف، عن سفيان، عن ليث، وفيه: \"إن كادت من ثقلها لتكسر الناقة\".\n\nوذكره الهيثمي في مجمع الزوائد ٧: ١٣، وقال: \"رواه أحمد والطبراني، وفيه شهر بن حوشب، وهو ضعيف، وقد وثق\"، وقد مضى مرارًا توثيق أخي السيد أحمد لشهر.]]\n\n١١١٠٨- حدثني أبو عامر إسماعيل بن عمرو السكوني قال، حدثنا هشام بن عمار قال، حدثنا ابن عياش قال، حدثنا عمرو بن قيس السكوني: أنه سمع معاوية بن أبي سفيان على المنبر ينتزع بهذه الآية:\"اليوم أكملت لكم دينكم\"، حتى ختمها، فقال: نزلت في يوم عرفة، في يوم جمعة. [[الأثر: ١١١٠٨-\"إسمعيل بن عمرو السكوني\"، أبو عامر، الحمصي المقرئ، إمام مسجد حمص. روى عن علي بن عياش، والربيع بن روح، ويحيى بن صالح الوحاظي، قال ابن أبي حاتم: \"سمعت منه، وهو صدوق\". مترجم في ابن أبي حاتم ١/١/١٩٠.\n\nو\"هشام بن عمار بن نصير السلمي\"، أبو الوليد الدمشقي. روى عند البخاري وأبو داود والنسائي وابن ماجه. ثقة. مترجم في التهذيب.\n\nو\"ابن عياش\"، هو: إسمعيل بن عياش، مضى مرارًا.\n\nو\"عمرو بن قيس بن ثور بن مازن بن خيثمة الكندي السكوني\"، أبو ثور الشامي الحمصي. روى عن جده\"مازن بن خيثمة\"، وله صحبة، وعن عبد الله بن عمرو، ومعاوية ووفد عليه مع أبيه. قال إسمعيل بن عياش: و\"أدرك سبعين من الصحابة أو أكثر\". ثقة، صالح الحديث. مترجم في التهذيب.\n\nوهذا الخبر، خرجه الهيثمي في مجمع الزوائد مطولا، ثم قال: \"رواه الطبراني، ورجاله ثقات\".\n\nوقوله: \"انتزع بهذه الآية\"، أي تمثل بها وقرأها.]]\n\n* *\n\nوقال آخرون: بل نزلت هذه الآية = أعني قوله:\"اليوم أكملت لكم دينكم\" = يوم الاثنين. وقالوا: أنزلت\"سورة المائدة\" بالمدينة.\n\nذكر من قال ذلك:\n\n١١١٠٩- حدثني المثنى قال، حدثنا إسحاق قال، أخبرنا محمد بن حرب قال، حدثنا ابن لهيعة، عن خالد بن أبي عمران، عن حنش، عن ابن عباس: ولد نبيكم ﷺ يوم الاثنين، وخرج من مكة يوم الاثنين، ودخل المدينة يوم الاثنين، وأنزلت:\"سورة المائدة\" يوم الاثنين:\"اليوم أكملت لكم دينكم\"، ورفع الذكر يوم الاثنين. [[الأثر: ١١١٠٩-\"محمد بن حرب الخولاني\" الأبرش. قال أحمد: \"ليس به بأس\"، وقال ابن معين: \"ثقة\". مترجم في التهذيب.\n\nو\"ابن لهيعة\" هو\"عبد الله بن لهيعة\"، مضى برقم: ١٦٠، ٢٩٤١، ٥٣٥٥، ٥٥١٨، ومضى توثيق أخي السيد أحمد له.\n\nو\"خالد بن أبي عمران التجيبي\"، قاضي إفريقية. ثقة، وثقه ابن سعد والعجلي، وغيرهما.\n\nو\"حنش\" هو: \"حنش بن عبد الله السبائي الصنعاني\" مضى برقم: ١٩١٤، وهو تابعي ثقة.\n\nوهذا الخبر استوهاه الطبري كما سيأتي في آخر كلامه، وذلك لما قالوا من ضعف ابن لهيعة، وترك بعضهم الاحتجاج به.\n\nوروى هذا الخبر أحمد في مسنده برقم: ٢٥٠٦ من طريق موسى بن داود، عن ابن لهيعة، ونصه: \"ولد النبي ﷺ يوم الاثنين، واستنئ يوم الاثنين، وتوفي يوم الاثنين، وخرج مهاجرًا من مكة إلى المدينة يوم الاثنين، وقدم المدينة يوم الاثنين، ورفع الحجر الأسود يوم الاثنين\".\n\nوقال أخي السيد أحمد في التعليق عليه: \"إسناده صحيح. والحديث ذكره ابن كثير في التاريخ ٢: ٢٥٩، ٢٦٠، عن هذا الموضع، وقال: \"تفرد به أحمد\"، وهو في مجمع الزوائد ١: ١٩٦، ونسبه لأحمد والطبراني في الكبير وقال الهيثمي: \"وفيه ابن لهيعة، وهو ضعيف! وبقية رجاله ثقات من أهل الصحيح\".\n\nوليس في خبر أحمد\"وأنزلت سورة المائدة..\"، ولذلك لما ذكره ابن كثير في تفسيره، ٢: ٦٨، عن هذا الموضع من تفسير الطبري ونسبه للطبراني وابن مردويه، ثم قال: \"أثر غريب، وإسناده ضعيف، وقد رواه الإمام أحمد..\" ثم ساق حديث أحمد، ثم قال: \"هذا لفظ أحمد، ولم يذكر نزول المائدة يوم الاثنين، فالله أعلم. ولعل ابن عباس أراد أنها نزلت\"يوم عيدين اثنين، كما تقدم (يعني في الأثر رقم: ١١٠٩٨) ، فاشتبه على الراوي\".\n\nوهذا توجيه غير مرتضى، وربما كان الأرجح أنه غلط من أحد الرواة عن ابن لهيعة، فإن رواية أحمد، لا شك في قوتها وضبطها.\n\nوقوله: \"رفع الذكر يوم الاثنين\"، يعني وفاة رسول الله ﷺ، بأبي هو وأمي، وانقطاع الوحي من بعد قبضه ولحاقه بالرفيق الأعلى.]]\n\n١١١١٠- حدثني المثنى قال، حدثنا الحجاج بن المنهال قال، حدثنا همام، عن قتادة قال:\"المائدة\" مدنيّة.\n\n* *\n\nوقال آخرون: نزلت على رسول الله ﷺ في مسيره في حجة الوداع.\n\nذكر من قال ذلك:\n\n١١١١٢- حدثني المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن أبي جعفر، عن أبيه، عن الربيع بن أنس قال: نزلت\"سورة المائدة\" على رسول الله ﷺ في المسير في حجة الوداع، وهو راكب راحلته، فبركت به راحلته من ثقلها. [[سقط من الترقيم رقم: ١١١١١.]]\n\n* *\n\nوقال آخرون: ليس ذلك بيوم معلوم عند الناس، وإنما معناه: اليوم الذي أعلمه أنا دون خلقي، أكملت لكم دينكم.\n\nذكر من قال ذلك:\n\n١١١١٣- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس:\"اليوم أكملت لكم دينكم\"، يقول: ليس بيوم معلوم يعلمه الناس.\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في وقت نزول الآية، القولُ الذي روي عن عمر بن الخطاب: أنها نزلت يوم عرفة يوم جمعة، لصحة سنده، وَوَهْيِ أسانيد غيره. [[قوله: \"ووهي أسانيد غيره\". سلف في ٨: ٨٠ تعليق ١، أن الذي في المخطوطة هناك.\n\n\"وهاء\"، ولذلك أثبتها، لأني وجدتها أيضًا في تهذيب الآثار للطبري\"وهاء\"، ثم هذه مرة أخرى، أجد في المخطوطة\"وهي\"، فاختلفت المخطوطة كما ترى في كتابتها في موضع آخر. راجع ما كتبته في التعليق هناك.]]\n\n* *\n\nالقول في تأويل قوله: ﴿فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ﴾\n\nقال أبو جعفر: يعني تعالى ذكره بقول:\"فمن اضطر\"، فمن أصابه ضُرٌّ [[انظر تفسير\"اضطر\" فيما سلف ٣: ٥٦، ٣٢١.]] =\"في مخمصة\"، يعني: في مجاعة.\n\n* *\n\n= وهي\"مفعلة\"، مثل\"المجبنة\" و\"المبخلة\" و\"المنجبة\"، من\"خَمَصِ البطنِ\"، وهو اضطماره، وأظنه هو في هذا الموضع معنيٌّ به: اضطماره من الجوع وشدة السَّغَب. وقد يكون في غير هذا الموضع اضطمارا من غير الجوع والسَّغب، ولكن من خلقة، كما قال نابغة بني ذبيان في صفة امرأة بخَمَص البطن: [[\"خمص\" (بفتح الخاء والميم) . وهذا تفصيل جيد في معنى\"الخمص\" و\"المخمصة\"، لا تصيب مثله في معاجم اللغة.]]\n\nوَالبَطنُ ذُو عُكَنٍ خَمِيصٌ لَيِّنٌ ... وَالنَّحْرُ تَنْفُجُهُ بثَدْيٍ مُقْعَدِ [[ديوانه: ٦٦ واللسان (قعد) وروايته: \"لطيف طيه\"، ولا شاهد فيه عندئذ. وهو من قصيدته التي استجاد فيها صفة المتجردة، صاحبة النعمان بن المنذر، والتي أفضت إلى ما كان بينهما من المهاجرة.\n\nو\"العكن\": أطواء البطن لا من السمن فحسب، كما يقول أصحاب اللغة، فإن هذا البيت شاهد على خلافه. وإنما\"العكن\" هنا ما تثنى من أطواء البطن من رقة جلدها ونعومته، ورخاصة جسدها ولينه، فلذلك يتثنى. ولو كان ذلك من\"السمن\"، كما يقول أهل اللغة، لم يقل بعد\"خميص لين\"، ويصفه بالضمور والرقة (في رواية أبي جعفر) ، ولا\"لطيف طيه\"، وهو كناية عن الضمور والرقة أيضًا، وذلك من صفتها ضد السمن. فمن شرح\"العكن\" في هذا البيت وأشباهه بأنها من السمن، فقد أخطأ، وأحال معاني الشعر عن وجوهها.\n\nوقوله: \"والنحر تنفجه\"، \"النحر\": أعلى الصدر، وهو موضع القلادة منها. وكل ما ارتفع فقد\"نفج وانتفج وتنفج\"، و\"نفجه الرجل ينفجه نفجًا\". ويقال: \"نفج ثدي المرأة قميصها\": إذا رفعه. وأسند إليها أنها تنفج نحرها بثدييها، وإن كان ذلك خلقة لا فعل لها فيه، لأنه نظر إلى ما يساور المرأة حين تختال لتفتن الناظرين، فتتخذ سمتًا وهيأة تنهب بحلم الحليم. فأصاب النابغة غاية الإصابة في الإشارة إلى سر المرأة في حركتها وشمائلها.\n\nولكن الذين تعرضوا لتفسير مثل هذا الشعر، أساءوا إليه من حيث أرادوا الإحسان، فقال الوزير أبو بكر في شرحه ديوان النابغة: \"ويروى: والإتب تنفجه، -والإتب ثوب تلبسه- وهو أليق بالمعنى، لأن الثدي ينفخ الثوب، أي يرفعه ويعظمه\". ثم قال أيضًا: \"وروي: والنحر تنفجه\" أي ترفعه عن الثوب\"، وهذا مثل على الخلط في فهم الشعر، وإفساد لمعانيه. والذي استحسنه الوزير، معنى مغسول سخيف في مثل هذا الموضع من شعر النابغة، أضاع به تعب الشاعر في شعره.\n\nو\"ثدي مقعد\": ناتئ على النحر، إذا كان ناهدًا لم ينثن بعد.]] فمعلوم أنه لم يرد صفتها بقوله:\"خميص\" بالهزال والضرّ من الجوع، ولكنه أراد وصفها بلطافة طيِّ ما على الأوراك والأفخاذ من جسدها، لأن ذلك مما يحمد من النساء. ولكن الذي في معنى الوصف بالاضطمار والهزال من الضر من ذلك، قول أعشى بني ثعلبة:\n\nتَبِيتُونَ فِي المَشْتَى مِلاءً بُطُونُكُمْ ... وَجَارَاتُكُمْ غَرْثَى يَبِتْنَ خَمَائِصَا [[ديوانه: ١٠٩، ومجاز القرآن لأبي عبيدة ١: ١٥٣، من إحدى قصائده التي قالها في خبر المنافرة بين علقمة بن علاثة، وعامر بن الطفيل (الأغاني ١٥: ٥٠) ، وبعد البيت: يُراقِبْنَ مِنْ جُوعٍ خِلالَ مَخَافةٍ ... نُجُومَ الشِّتَاء العَاتِمَاتِ الغوامِصَا\n\n\"غرثى\"، جياع، ويروى\"جوعى\". ووصف النجوم بقوله: \"العاتمات\" أراد أنها تظلم من الغبرة التي في السماء، وذلك في الجدب (وهو الشتاء) ، لأن نجوم الشتاء أشد إضاءة لنقاء السماء، فهن يلتمسن وقت خفائها. و\"الغوامص\" يعني: التي قل ضوءها من الغبرة. وقال شارح ديوانه: \"يبتن جياعًا خائفات ينتظرن طلوع النجوم السحرية، ليخرجن يطلبن شيئًا، كيلا يعرفن\". وقوله: \"خلال مخافة\" من أحسن الكلام في هذا البيت.]]\n\nيعني بذلك: يبتن مضطمرات البطون من الجوع والسغب والضرّ. فمن هذا المعنى قوله:\"في مخمصة\".\n\n* *\n\nوكان بعض نحويي البصرة يقول:\"المخمصة\"، المصدر من\"خَمَصَه الجوع\".\n\n* *\n\nوكان غيره من أهل العربية يرى أنها اسم للمصدر، وليست بمصدر، ولذلك تقع\"المفعلة\" اسمًا في المصادر للتأنيث والتذكير.\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١١١٤- حدثني المثنى قال، حدثنا أبو صالح قال، حدثني معاوية، عن علي، عن عباس:\"فمن اضطر في مخمصة\"، يعني: في مجاعة.\n\n١١١١٥- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"فمن اضطر في مخمصة\"، أي: في مجاعة.\n\n* *\n\n١١١١٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة، مثله. [[الأثر: ١١١١٦- في المطبوعة والمخطوطة: \"حدثنا الحسن بن يحيى قال، أخبرنا معمر\" وهو إسناد ناقص، سقط منه\"قال أخبرنا عبد الرزاق\"، وهو إسناد دائر في التفسير، أقربه رقم: ١١١٠٤.]]\n\n١١١١٧- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"فمن اضطر في مخمصة\"، قال: ذكر الميتة وما فيها، فأحلها في الاضطرار [[في المطبوعة: \"وأحلها\" بالواو، وفي المخطوطة: \"فأكلها\"، وهو تحريف.]] =\"في مخمصة\"، يقول: في مجاعة.\n\n١١١١٨- حدثني يونس قال، أخبرنا ابن وهب قال: سمعت ابن زيد يقول في قوله:\"فمن اضطر في مخمصة\"، قال، المخمصة، الجوع.\n\n* *\n\nالقول في تأويل قوله: ﴿غَيْرَ مُتَجَانِفٍ لإثْمٍ﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: فمن اضطر في مخمصة إلى أكل ما حَرَّمتُ عليه منكم، أيها المؤمنون، من الميتة، والدم ولحم الخنزير وسائر ما حرمت عليه بهذه الآية =\"غير متجانف لإثم\"، يقول: لا متجانفًا لإثم. [[في المطبوعة: \"إلا متجانفًا\" فأفسد المعنى إفسادًا، والصواب من المخطوطة، وفيها: \"لا متجانف\"، والصواب ما أثبت.]]\n\n= فلذلك نصب\"غير\" لخروجها من الاسم الذي في قوله:\"فمن اضطر\" [[\"الخروج\"، الحال، كما سلف في فهارس المصطلحات.]] وهي بمعنى:\"لا\"، فنصب بالمعنى الذي كان به منصوبًا\"المتجانف\"، لو جاء الكلام:\"لا متجانفًا\". [[في هذين الموضعين أيضًا في المطبوعة: \"وهي بمعنى: إلا\" ثم: \"لو جاء الكلام: إلا متجانفًا\"، وهو خطأ محض، والصواب ما أثبته من المخطوطة.\n\nوانظر تفسير\"غير\" بمعنى\"لا\" فيما سلف ٣: ٣٢٢، في تفسير قوله تعالى من سورة البقرة: ١٧٣: \"غير باغ ولا عاد\"، بمعنى: لا باغيًا ولا عاديًا = منصوبًا على الحال.]]\n\n* *\n\nوأما\"المتجانف لإثم\"، فإنه المتمايل له، المنحرف إليه. وهو في هذا الموضع مراد به المتعمِّد له، القاصد إليه، من\"جَنَف القوم عليّ\"، إذا مالوا. وكل أعوج فهو\"أجنف\"، عند العرب.\n\n* *\n\nوقد بينا معنى\"الجنف\" بشواهده في قوله: ﴿فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا﴾ [سورة البقرة: ١٨٢] ، بما أغنى عن إعادته في هذا الموضع. [[انظر تفسير\"الجنف\" فيما سلف ٣: ٤٠٥-٤٠٨.\n\n= وتفسير\"الإثم\" فيما سلف من فهارس اللغة، مادة (أثم) .]]\n\n* *\n\nوأما تجانف آكل الميتة في أكلها وفي غيرها مما حرم الله أكله على المؤمنين بهذه الآية، للإثم في حال أكله [[السياق: \"وأما تجانف آكل الميتة ... للإثم في حال أكله ... \".]] فهو: تعمده أكل ذلك لغير دفع الضرورة النازلة به [[في المطبوعة: \"فهو تعمده الأكل لغير دفع الضرورة\"، غير ما في المخطوطة بلا معنى.]] ولكن لمعصية الله، وخلاف أمره فيما أمره به من ترك أكل ذلك.\n\n* *\n\nوبنحو الذي قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١١١٩- حدثني المثنى قال، حدثنا أبو صالح قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"فمن اضطر في مخمصة غير متجانف لإثم\"، يعني: إلى ما حُرِّم، مما سمَّى في صدر هذه الآية =\"غير متجانف لإثم\"، يقول: غير متعمد لإثم.\n\n١١١٢٠- حدثني المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد:\"غير متجانف لإثم\"، غير متعمد لإثم. قال: إلى حِرْم الله، ما حَرّم [[\"حرم الله\" (بكسر الحاء، وسكون الراء) ، هو الحرام نقيض الحلال. وقوله بعد ذلك: \"ما حرم\"، تفسير لقوله: \"حرم الله\".]] رخّص للمضطر إذا كان غير متعمد لإثم، أن يأكله من جهد. فمن بَغَى، أو عدا، أو خرج في معصيةٍ لله، فإنه محرم عليه أن يأكله.\n\n١١١٢١- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"غير متجانف لإثم\"، أي: غير متعرِّض لمعصية.\n\n١١١٢٢- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن قتادة:\"غير متجانف لإثم\"، غير متعمد لإثم، غير متعرِّض.\n\n١١١٢٣- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"غير متجانف لإثم\"، يقول: غير متعرض لإثم، أي: يبتغي فيه شهوة، أو يعتدي في أكله.\n\n١١١٢٤- حدثنا يونس قال، أخبرنا ابن وهب قال، قال ابن زيد فى قوله:\"غير متجانف لإثم\"، لا يأكل ذلك ابتغاءَ الإثم، ولا جراءة عليه.\n\n* *\n\nالقول في تأويل قوله: ﴿فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ (٣) ﴾\n\nقال أبو جعفر: وفي هذا الكلام متروك، اكتفى بدلالة ما ذكر عليه منه. وذلك أن معنى الكلام: فمن اضطر في مخمصة إلى ما حرمت عليه مما ذكرت في هذه الآية، غير متجانف لإثم فأكله، فإن الله غفور رحيم = فترك ذكر\"فأكله\"، وذكر\"له\" [[يعني بقوله: \"وذكر: له\"، معطوف على قوله: \"وترك ذكر: فأكله\"، والمعنى: وترك ذكر: \"إلى ما حرمت عليه فأكله\". وكان الأجود عندي أن يبين ذلك فيذكره كما ذكرته.\n\nوأما قوله: \"وذكر: له\"، يعني في قوله: \"فإن الله له غفور ... \".]] لدلالة سائر ما ذكر من الكلام عليهما.\n\n* *\n\nوأما قوله:\"فإن الله غفور رحيم\"، فإن معناه: فإن الله لمن أكل ما حرمت عليه بهذه الآية أكله، في مخمصة، غير متجانف لإثم =\"غفور رحيم\"، يقول: يستر له عن أكله ما أكل من ذلك، بعفوه عن مؤاخذته إياه، وصفحه عنه وعن عقوبته عليه =\"رحيم\"، يقول: وهو به رفيق. ومن رحمته ورفقه به [[في المطبوعة: \"من رحمته\" بإسقاط الواو، وأثبتها من المخطوطة.]] أباح له أكل ما أباح له أكله من الميتة وسائر ما ذكر معها في هذه الآية، في حال خوفه على نفسه من كَلَب الجوع وضُرِّ الحاجة العارضة ببدنه.\n\n* *\n\nفإن قال قائل: وما الأكل الذي وعد الله المضطر إلى الميتة وسائر المحرَّمات معها بهذه الآية، غفرانَهُ إذا أكل منها؟\n\nقيل: ما:-\n\n١١١٢٥- حدثني عبد الأعلى بن واصل الأسدي قال، حدثنا محمد بن القاسم الأسدي، عن الأوزاعي، عن حسان بن عطية، عن أبي واقد الليثي قال: قلنا: يا رسول الله، إنا بأرض تصيبنا فيها مخمصة، فما يصلح لنا من الميتة؟ قال: إذا لم تصطبحوا، أو تغتبقوا، أو تحتفئوا بقلا فشأنَكم بها. [[الأثر: ١١١٢٥- خبر الأوزاعي، عن حسان بن عطية، يرويه الطبري بعد برقم: ١١١٣٢، عن الأوزاعي، عن حسان مرسلا. ثم يرويه برقم: ١١١٣٣، عن الأوزاعي، عن حسان، عن رجل قد سمى له. وهي خبر واحد.\n\n\"عبد الأعلى بن واصل بن عبد الأعلى بن هلال الأسدي\"، شيخ الطبري، روى له الترمذي، والنسائي، وأبو حاتم. قال أبو حاتم: \"صدوق\"، وقال النسائي: \"ثقة\". مترجم في التهذيب.\n\nو\"محمد بن القاسم الأسدي\" رمي بالكذب والوضع. قال أبو داود: \"غير ثقة ولا مأمون، أحاديثه موضوعة\"، وتكلم فيه أحمد بن حنبل وضعفه، روى محمد بن القاسم، عن الأوزاعي. مترجم في التهذيب.\n\nو\"الأوزاعي\" هو الإمام المشهور.\n\nو\"حسان بن عطية المحاربي\"، كان من أفاضل أهل زمانه، وثقه أحمد، وابن معين، والعجلي، روى عن أبي أمامة، وعنبسة بن أبي سفيان، وسعيد بن المسيب. ونصوا على أنه أرسل عن أبي واقد الليثي، وكأنهم يعنون هذا الخبر بعينه.\n\nو\"أبو واقد الليثي\" قيل اسمه: \"الحارث بن مالك\"، وقيل: \"الحارث بن عوف\"، وقيل: \"عوف بن الحارث بن أسد\"، من بني ليث بن بكر بن عبد مناة، من كنانة. صحابي، روى عن النبي ﷺ، وعن أبي بكر وعمر. وروى عنه ابناه عبد الملك وواقد، وعبيد الله بن عبد الله بن عتبة، وعطاء بن يسار، وعروة بن الزبير، وغيرهم.\n\nوإسناد أبي جعفر هذا، إسناد ضعيف، لضعف محمد بن القاسم، ولكنه روي من وجه صحيح، كما سترى في التخريج.\n\nفرواه أحمد في مسنده ٥: ٢١٨ (حلبي) عن محمد بن القاسم، عن الأوزاعي، وهو نفس إسناد الطبري، فهو ضعيف.\n\nثم رواه مرة أخرى في نفس الصفحة، عن الوليد بن مسلم، عن الأوزاعي. (قلت: في المسند: حدثنا الوليد، حدثنا مسلم، حدثنا الأوزاعي = وهو خطأ لا شك فيه، صوابه: الوليد بن مسلم، كما نقله عن هذا الموضع من المسند، ابن كثير في تفسيره ٢: ٦٩) .\n\nوقال ابن كثير بعد نقله هذا الخبر الثاني من خبري أحمد: \"تفرد به أحمد من هذا الوجه، وهو إسناد صحيح على شرط الصحيحين\".\n\nولكن الهيثمي خرجه في مجمع الزوائد ٤: ١٦٥، وقال: \"رواه أحمد بإسنادين، رجال أحدهما رجال الصحيح [يعني الحديث الثاني من حديثي أحمد] ، إلا أن المزي قال: لم يسمع حسان بن عطية من أبي واقد، والله أعلم\".\n\nثم خرجه الهيثمي أيضًا في مجمع الزوائد ٥: ١٦٥ وقال: \"رواه الطبراني، ورجاله ثقات\". ولم يذكر مقالة المزي، ولا انقطاع الخبر.\n\nورواه الحاكم في المستدرك ٤: ١٢٥، من طريق أبي قلابة الرقاشي، عن أبي عاصم، عن الأوزاعي، عن حسان بن عطية، عن أبي واقد، بمثله. وقال: \"هذا حديث صحيح على شرط الشيخين، ولم يخرجاه\". وتعقبه الذهبي فقال: \"فيه انقطاع\"، إشارة ما قاله المزي، فيما رواه صاحب مجمع الزوائد.\n\nورواه البيهقي في السنن ٩: ٣٥٦ من ثلاث طرق: محمد بن القاسم الأسدي، عن الأوزاعي، كرواية أحمد والطبري.\n\nومن طريق أبي عبيد، عن محمد بن كثير، عن الأوزاعي، عن حسان، عن أبي واقد.\n\nثم رواه من طريق الوليد بن مسلم (وهو طريق أحمد الثاني) ، ولكن فيه زيادة، وذلك أنه رواه عن إسحق بن إبراهيم الحنظلي، عن الوليد بن مسلم، عن الأوزاعي، عن حسان بن عطية، عن ابن مرثد = أو أبي مرثد = عن أبي واقد الليثي.\n\nوإلى هذه الطريق أشار ابن كثير في تفسيره ٣: ٦٩، بعد أن روى حديث أحمد في المسند فقال: \"ولكن رواه بعضهم عن الأوزاعي، عن حسان بن عطية، عن مسلم بن يزيد، عن أبي واقد، به، ومنهم من رواه عن الأوزاعي، عن حسان، عن مرثد = أو أبي مرثد = عن أبي واقد، به\"، فخالف ما في سنن البيهقي، قال: \"مرثد\"، والذي فيها\"ابن مرثد\".\n\nولم أجد ذكرًا في كتب الرجال لمسلم بن يزيد، أو مرثد، أو ابن مرثد. فإسناد هذه الخبر، كما ترى، هو على صحته منقطع.\n\nوخرجه السيوطي في الدر المنثور ٢: ٢٥٩، ولم ينسب لغير أحمد والحاكم.\n\n* *\n\nوقوله: \"إذا لم تصطبحوا\"، أي: إذا لم تجدوا صبوحًا، و\"الصبوح\" (بفتح الصاد) : هو ما يحلب من اللبن بالغداة ويشرب عندئذ. و\"اصطبح القوم\": شربوا الصبوح. و\"صبح الرجل ضيفه\": سقاه الصبوح بالغداة.\n\nوقوله: \"أو تغتبقوا\"، أي: إذا لم تجدوا غبوقًا، و\"الغبوق\" (بفتح الغين) : هو ما يحلب من اللبن بالعشي، ويشرب عندئذ.\"غبق الرجل ضيفه\"، سقاه غبوقًا. و\"اغتبق القوم\": شربوا الغبوق بالعشي.\n\nأما \"تحتفئوا\"، فسيأتي تفسيرها بعد الأثر رقم: ١١١٣٣، ص: ٥٤٢، تعليق: ٢.]]\n\n١١١٢٦- حدثنا أبو كريب قال، حدثنا هشيم، عن الخصيب بن زيد التميمي قال، حدثنا الحسن: أن رجلا سأل رسول الله ﷺ فقال: إلى متى يحلُّ لي الحرام؟ قال فقال: إلى أن يروَى أهلك من اللبن، أو تجيء مِيرَتُهم\". [[الأثر: ١١١٢٦-\"الخصيب بن زيد التميمي\"، سمع عن الحسن، مرسل، روى عنه هشيم، هكذا قال البخاري في الكبير ٢/١/٢٠١. وفي التهذيب: \"وثقه أحمد\"، وذكره ابن حبان في الثقات. وفي ابن أبي حاتم ١/٢/٣٩٦، كتب\"خصيب بن بدر التميمي\"، والصواب\"خصيب بن زيد\" كما قال البخاري.\n\nو\"الميرة\" (بكسر الميم) : هو جلب الطعام. وفي المخطوطة: \"وتجيء\" بالواو، وأثبت ما في المطبوعة، وابن كثير ٣: ٦٩.]]\n\n١١١٢٧- حدثني يعقوب بن إبراهيم قال، حدثنا هشيم قال، أخبرنا خصيب بن زيد التميمي قال، حدثنا الحسن: أن رجلا سأل النبي ﷺ، فذكر مثله = إلا أنه قال: أو تُجْبَى ميرتهم. [[في المطبوعة: \"أو تحيا ميرتهم\"، من\"الحياة\"، وفي المخطوطة: \"تجبى\" غير منقوطة، فرأيت أن أقرأها كذلك، من\"جبى الماء في الحوض يجيبه\": جمعه، و\"جبى الخراج\" جمعه. ولو قرئت: \"يجني\" من\"جنى يجني\"، كما تجنى الثمرة، لكان مجازا. وللذي في المطبوعة: \"يحيى\"، وجه. ولكني رجحت ما أثبت. ولم أجد الخبر في مكان آخر بهذه الرواية.]]\n\n١١١٢٨- حدثنا ابن حميد قال، حدثنا سلمة، عن ابن إسحاق قال، حدثني عمر بن عبد الله بن عروة، عن جده عروة بن الزبير، عمن حدثه: أن رجلا من الأعراب أتى النبي ﷺ يستفتيه في الذي حرّم الله عليه، والذي أحل له، فقال النبي ﷺ: تحل لك الطيبات، وتحرُم عليك الخبائث، إلا أن تفتقر إلى طعام [لا يحل لك] ، [[الزيادة بين القوسين، لا يتم الكلام إلا بها، من مجمع الزوائد.]] فتأكل منه حتى تستغني عنه. فقال الرجل: وما فقري الذي يُحِلّ لي؟ وما غناي الذي يغنيني عن ذلك؟ [[نص ما رواه في مجمع الزوائد: \"ما فقري، وما الذي آكل من ذلك إذا بلغته؟ وما غناي الذي يغنيني عنه\".]] فقال النبي ﷺ: إذا كنت ترجو نتاجًا، فتبلَّغ بلحوم ماشيتك إلى نِتاجك، أو كنت ترجو غنًى تطلبه، فتبلَّغ من ذلك شيئًا، [[\"تبلغ بشيء من الطعام أو غيره\": اكتفى به. وقوله: \"شيئا\"، أي: قليلا، غير مفرط فيه.\n\nوانظر تفسير\"شيء\" بمعنى\"قليل\" فيما سلف ٦: ٤٤٨، تعليق ٢/٨: ٤٠٣، تعليق: ١.]] فأطعم أهلك ما بدا لك حتى تستغني عنه. فقال الأعرابي: ما غِناي الذي أدعه إذا وجدته؟ فقال النبي ﷺ: إذا أرويت أهلك غَبُوقًا من الليل. [[في مجمع الزوائد: \"غبوقًا من اللبن\"، وما في الطبري أجود.]] فاجتنب ما حرَّم الله عليك من طعام. [وأمّا] مالُك [[الزيادة بين القوسين، لا يتم الكلام إلا بها، زدتها من مجمع الزوائد، ومن الدر المنثور. وأما قوله بعد: \"ميسور كله\"، أي: موسع عليك فيه.]] فإنه ميسور كله، ليس فيه حرام. \" [[الأثر: ١١١٢٨- خرجه الهيثمي في مجمع الزوائد مطولا، من\"حديث سمرة بن جندب، عن رسول الله ﷺ أنه أتاه رجل من الأعراب\"، ثم قال: \"رواه الطبراني في الكبير، والبزار باختصار. وفي إسناد الطبراني مساتير، وإسناد البزار ضعيف\".\n\nوذكره ابن كثير من تفسيره ٣: ٧٠ عن هذا الموضع من التفسير، وفيه: \"عروة بن الزبير، عن جدته\"، والصواب ما في الطبري، والدر المنثور، وبما تبين من أن الخبر من حديث سمرة بن جندب. وخرجه في الدر المنثور ٢: ٢٦٠، ولم ينسبه لغير الطبري.]]\n\n١١١٢٩- حدثني يعقوب بن إبراهيم قال، حدثنا ابن علية، عن ابن عون قال: وجدت عند الحسن كتاب سمرة، فقرأته عليه، وكان فيه: ويُجْزي من الاضطرار غَبُوق أو صَبُوح. [[الأثر: ١١١٢٩-\"سمرة\"، هو\"سمرة بن جندب بن هلال الفزاري\"، صاحب رسول الله ﷺ. وكتابه هذا هو رسالته إلى بنيه، قال ابن سيرين: \"في رسالة سمرة إلى بنيه، علم كثير\". وانظر الأثر التالي.]]\n\n١١١٣٠- حدثنا هناد وأبو هشام الرفاعي قالا حدثنا يحيى بن أبي زائدة، عن ابن عون قال: قرأت في كتاب سَمُرة بن جندب: يكفي من الاضطرار = أو: من الضرورة = غبوقٌ أو صبوح. [[الأثر: ١١١٣٠- هذا الأثر، رواه البيهقي في السنن عن أبي عبيد، عن معاذ، عن ابن عون: قال: \"رأيت عند الحسن كتب سمرة لبنيه: أنه يجزئ من الاضطرار - أو الضارورة..\" و\"الضرورة\" و\"الضارورة\"، واحد، وهما اسم لمصدر\"الاضطرار\".]]\n\n١١١٣١- حدثني علي بن سعيد الكندي وأبو كريب قالا حدثنا عبد الله بن إدريس، عن هشام بن حسان، عن الحسن قال: إذا اضطر الرجل إلى الميتة، أكل منها قوتَه = يعني: مُسْكَتَه. [[\"المسكة\" (بضم الميم وسكون السين) : هي ما يمسك الأبدان من الطعام والشراب. وكذلك\"القوت\": هو ما يقوم به بدن الإنسان من الطعام، وما يمسك الرمق من الرزق.]]\n\n١١١٣٢- حدثنا هنّاد بن السري قال، حدثنا ابن مبارك، عن الأوزاعي، عن حسان بن عطية قال: قال رجل: يا رسول الله، إنا بأرض مَخْمصة، فما يحلّ لنا من الميتة؟ ومتى تحلّ لنا الميتة؟ قال: إذا لم تصطبحوا، أو تغتبقوا، ولم تحتفئوا بقلا فشأنَكم بها. [[الأثران: ١١١٣٢، ١١١٣٣- هما خبر أبي واقد الليثي الذي مضى برقم: ١١١٢٥، وانظر التعليق عليه هناك.]]\n\n١١١٣٣- حدثنا هناد بن السري قال، حدثنا عيسى بن يونس، عن الأوزاعي، عن حسان بن عطية، عن رجل قد سمي لنا: أن رجلا قال للنبي ﷺ: إنا نكون بأرض مخمصة، فمتى تحل لنا الميتة؟ قال: إذا لم تغتبقوا، ولم تصطبحوا، ولم تحتفئوا بقلا فشأنكم بها. [[الأثران: ١١١٣٢، ١١١٣٣- هما خبر أبي واقد الليثي الذي مضى برقم: ١١١٢٥، وانظر التعليق عليه هناك.]]\n\n* *\n\nقال أبو جعفر: يروى هذا على أربعة أوجه:\"تحتفئوا\" بالهمزة =\"وتحتفيوا\" بتخفيف\"الياء\" و\"الحاء\" = و\"تحتفّوا\"، بتشديد الفاء = و\"تحتفوا\" بالحاء، والتخفيف، ويحتمل الهمز [[ما ذكره أبو جعفر هو روايات هذا الحرف بالحاء، ولكنه روي أيضًا بالجيم مهموزًا: \"تجتفئوا\" من قولهم: \"جفأ البقل يجفؤه جفأ، واجتفأ\": إذا اقتلعه من أصله.\n\nوروي بالجيم غير مهموز\"تجتفوا\"، بمعنى المهموز: \"جفيت البقل واجتفيته\".\n\nوروي بالخاء المعجمة: \"تختفوا\" من\"أخفى الشيء\" إذا أظهره بعد خفائه، كأنه قد أزال خفاءه.\n\nوأما ما رواه الطبري بالحاء، فتفسير\"تحتفئوا\" من\"الحفأ\" وهو البردي. يقال: \"احتفا الحفأ\": اقتلعه من منبته.\n\nوأما \"تحتفيوا\" (بكسر الفاء وضم الياء) من قولهم: \"احتفى الحفأ، البقل\" إذا اقتلعه من وجه الأرض بالأظافير، وأصله الهمز.\n\nوأما \"تحتفوا\" بتشديد الفاء، فمن قولهم: \"احتف الطعام\" إذا أكل جميع ما في القدر، ومن قولهم: \"احتفت المرأة\": أزالت شعر وجهها نتفًا بخيطين، فكأنهم ينتفون البقل من وجه الأرض لصغره.\n\nوأما \"تحتفوا\" فمن\"احتفى البقل\": إذا اقتلعه، وهو غير مهموز.\n\nهذا، وقد قال الأزهري: \"قال أبو سعيد: صوابه: تحتفوا، بتخفيف الفاء من غير همز. وكل شيء استؤصل فقد احتفى، ومنه: إحفاء الشعر. قال: واحتفى البقل: إذا أخذه من وجه الأرض بأطراف أصابعه من قصره وقلته = قال: ومن قال: تحتفئوا، بالهمز، من الحفأ، البردي، فهو باطل، لأن البردي ليس من البقل. والبقول: ما نبت من العشب على وجه الأرض مما لا عرق له. قال: ولا بردي في بلاد العرب = ويروى: ما لم تجتفئوا، بالجيم. قال: والاجتفاء أيضًا بالجيم باطل، لأن الاجتفاء: كب الآنية إذا جفأتها = ويروى: ما لم تحتفوا، بتشديد الفاء، من: احتففت الشيء، إذا أخذته كله، كما تحف المرأة وجهها من الشعر\".]] ."],[4,4,"القول في تأويل قوله: ﴿يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَمَا عَلَّمْتُمْ مِنَ الْجَوَارِحِ مُكَلِّبِينَ﴾\n\nقال أبو جعفر: يعني بذلك جل ثناؤه: يسألك، يا محمد، أصحابك: ما الذي أحل لهم أكله من المطاعم والمآكل؟ فقل لهم: أحِل لكم منها =\"الطيبات\"، وهي الحلال الذي أذن لكم ربكم في أكله من الذبائح [[انظر تفسير\"الطيبات\" فيما سلف ٣: ٣٠١/ ٥: ٥٥٥/٦: ٣٦١ / ٨: ٤٠٩ / ٩: ٣٩١.]] وأحل لكم أيضًا مع ذلك، صيدُ ما علّمتم من\"الجوارح\"، وهن الكَواسب من سباع البهائم.\n\n* *\n\nوالطير سميت\"جوارح\"، لجرحها لأربابها، وكسبها إيّاهم أقواتَهم من الصيد. يقال منه:\"جرح فلان لأهله خيرًا\"، إذا أكسبهم خيرًا، و\"فلان جارِحَة أهله\"، يعني بذلك: كاسبهم، و\"لا جارحة لفلانة\"، إذا لم يكن لها كاسب [[انظر مجاز القرآن لأبي عبيدة ١: ١٥٤.]] ومنه قول أعشى بني ثعلبة.\n\nذاتَ حَدٍّ مُنْضِجٍ مِيسَمُهَا ... تُذْكِرَ الجَارِحَ مَا كَانَ اجْتَرَحْ [[ديوانه: ١٦٤، وهي من قصيدة له طويلة، مجد فيها إياس بن قبيصة الطائي، ملك الحيرة. ثم ختم القصيدة بذكر الخمر، وذكر شبابه وما كان فيه من لهو ومروءة وبأس، فقال يصف لاذع قوله فيمن يعاديه (برواية الديوان) : وَلَقَدْ أَمْنَحُ مَنْ عَادَيْتُهُ ... كَلِمًا يَحْسِمْنَ مِنْ داءِ الكَشَحْ\n\nوقطَعْتُ نَاظِرَيْهِ ظاهِرًا ... لا يكونُ مِثْلَ لَطْمٍ وكَمَحْ\n\nذَا حَبَارٍ مُنْضِجٍ مِيسَمُهُ ... يُذْكِرُ الجَارِمَ مَا كَانَ اجتَرَحْ\n\nقوله: \"كلما\" جمع\"كلمة\"، يعني به: هجاءه وشعره. وفي الديوان: \"كلما\" مضبوطة بضم الكاف وتشديد اللام المفتوحة، ونقل عن الديوان\"كل ما\"، وهو خطأ فيما أرجح. و\"حسم الداء يحسمه\": قطعه بالدواء. و\"حسم العرق\": قطعه، ثم كواه لئلا يسيل دمه. و\"الكشح\" (بفتح الكاف والشين) : داء يصيب الإنسان في كشحه فيكوى.\"الكشح\" (بفتح فسكون) : ما بين الخاصرة إلى الضلع الخلف، وهما كشحان في الإنسان. و\"طوى فلان كشحه\": أي أعرض وولاك كشحه، من البغض والعداوة. وأراد بقوله: \"داء الكشح\"، العداوة والبغضاء. يقول: أهجوه هجاء يشفيه من داء البغض!\n\nوقوله: \"وقطعت ناظريه\" أي: كويته كية ظاهرة في وسط جبينه، بين عينيه إلى أنفه: وقوله: \"ظاهرًا\" صفة لمحذوف، أي كيا ظاهر الأثر. ليس أثره كأثر اللطم أو الكمح. و\"الكمح\" (بفتحتين) : هو أثر كمح الفرس باللجام، أي رده وجذبه باللجام ليقف، فيترك ذلك أثرًا حيث موقع اللجام. وهو حرف لم تذكره كتب اللغة، وشرحته من سياق معنى الشعر. يقول: أثر اللطم غير بين فهو يزول، وأثر كمح اللجام سهل يأتي متتابعًا فلا يؤذي، أما هذا الظاهر فهو مكواة من النار (كما يبينه البيت الثالث) . وأنا في شك من رواية هذا البيت.\n\nوقوله: \"ذا حبار\"، أي ذا أثر، صفة ثانية لقوله: \"ظاهرًا\"، و\"الحبار\" (بفتح الحاء) الأثر في الجلد من ضرب أو كي أو غيرها. ومثله\"الحبر\" (بكسر فسكون) . وفي الديوان\"ذا جبار\" (بضم الجيم) ، وهو لا معنى له، صواب إنشاده ما أثبت. و\"الميسم\": الحديدة التي يكوى بها. يشبه هجاه بالمكواة الحامية تنضج الجلد، وتبقي فيه أثرًا لا يزول، ولا تزال تذكره بما اجترم.\n\nوأما رواية أبي جعفر، فهي في المخطوطة: \"ذات حد\" (بالحاء المفتوحة) ، فإن صحت كذلك فهي صفة لقوله: \"كلما يحسمن\"، و\"الحد\": صلابة الشيء وشدته ونفاذه، كما يقال\"حد الظهيرة\"، أي: أشد حرها. وإن صحت روايته كما كان في المطبوعة: \"ذات خد\"، (بالخاء المعجمة) : من\"الخد\" و\"الأخدود\"، وهو الشق، و\"خدت الضربة جلده\" إذا شقته وتركت فيه خدًا. و\"أخاديد السياط\"، آثارها في الجلد. وكلتاهما جيدة المعنى.\n\n* *\n\nتنبيه: ديوان الأعشى المطبوع في أوربة، ديوان كثير الخطأ والتحريف والتصحيف، فمن أجل ذلك اجتهدت في تصحيح هذا الشعر، وفي كثير غيره مما سلف من شعر الأعشى.]] يعني: اكتسب.\n\nوترك من قوله:\"وما علمتم\"،\"وصيد\" ما علمتم من الجوارح، اكتفاء بدلالة ما ذكر من الكلام على ما تُرِك ذكره.\n\n* *\n\nوذلك أن القوم، فيما بلغنا، كانوا سألوا رسول الله ﷺ حين أمرهم بقتل الكلاب، عما يحلّ لهم اتخاذه منها وصَيْده، فأنزل الله عز ذكره فيما سألوا عنه من ذلك هذه الآية. فاستثنى مما كان حرّم اتخاذه منها، وأمر بقُنْيَة كلاب الصيد [[\"القنية\" (بضم القاف، أو بكسرها، وسكون النون) : اقتناء الأشياء واتخاذها لما ينتفع بها فيه.]] وكلاب الماشية، وكلاب الحرث، وأذن لهم باتخاذ ذلك.\n\nذكر الخبر بذلك:\n\n١١١٣٤- حدثنا أبو كريب قال، حدثنا زيد بن حباب العكلي قال، حدثنا موسى بن عبيدة قال، أخبرنا أبان بن صالح، عن القعقاع بن حكيم، عن سلمى أم رافع، عن أبي رافع قال: جاء جبريل إلى النبي ﷺ يستأذن عليه، فأذن له فقال: قد أذنَّا لك يا رسول الله! [[يعني بقوله: \"رسول الله\"، جبريل رسول الله بوحيه إلى النبي صلى الله عليهما.]] قال: أجل، ولكنا لا ندخل بيتًا فيه كلب! قال أبو رافع: فأمرني أن أقتل كل كلب بالمدينة، فقتلت حتى انتهيت إلى امرأة عندها كلب ينبح عليها، فتركته رحمة لها، ثم جئت إلى رسول الله ﷺ فأخبرته، فأمرني فرجعت إلى الكلب فقتلته. فجاؤوا فقالوا: يا رسول الله، ما يحل لنا من هذه الأمة التي أمرت بقتلها؟ قال: فسكت رسول الله ﷺ، فأنزل الله:\"يسألونك ماذا أحِل لهم قل أحل لكم الطيبات وما علَّمتم من الجوارح مكلبين\". [[الأثر: ١١١٣٤-\"زيد بن الحباب العكلي\"، مضى برقم: ٢١٨٥، ٥٣٥٠، ٨١٦٥، وهو ثقة، من شيوخ أحمد.\n\nو\"موسى بن عبيدة بن نشيط الربذي\"، مضى برقم: ١٨٧٥، ١٨٧٦، ٣٢٩١، ٨٣٦١، وهو ضعيف جدًا. قال أحمد: \"منكر الحديث، لا تحل الرواية عنه\". وفي تفسير ابن كثير: \"يونس بن عبيدة\"، وهو خطأ يصحح.\n\nو\"أبان بن صالح بن عمير بن عبيد\"، ثقة. مضى برقم: ٤٣٣٧، ٤٣٣٨، وكان في المطبوعة هنا: \"حدثنا موسى بن عبيدة، قال أخبرنا صالح، وفي المخطوطة: \"قال أنا صالح\"، وهو خطأ في كلتيهما، والصواب ما أثبته، عن الحاكم، والبيهقي، وابن كثير.\n\nو\"القعقاع بن حكيم الكناني\"، تابعي ثقة، مضى برقم: ٣٠٤.\n\nو\"سلمى أم رافع\"، مولاة النبي ﷺ، وهي زوجة أبي رافع، روت عن النبي ﷺ، وعن فاطمة الزهراء.\n\nو\"أبو رافع\" مولى رسول الله ﷺ.\n\nوإسناد هذا الخبر ضعيف، لضعف موسى بن عبيدة الربذي. ورواه ابن أبي حاتم أيضًا من طريق حجاج بن حمزة، عن زيد بن حباب، عن موسى بن عبيدة، كما نقله ابن كثير في تفسيره ٣: ٧٢، ٧٣. وذكره الهيثمي في مجمع الزوائد ٤: ٤٢، ٤٣، وقال: \"رواه الطبراني في الكبير، وفيه موسى بن عبيدة الربذي، وهو ضعيف\".\n\nأما البيهقي في السنن ٩: ٢٣٥، والحاكم في المستدرك ٢: ٣١١، فقد روياه مختصرًا من طريق معلى بن منصور، عن ابن أبي زائدة، عن محمد بن إسحق، عن أبان بن صالح، وهو أصح من إسناد أبي جعفر وابن أبي حاتم. وقال الحاكم: \"هذا حديث صحيح الإسناد ولم يخرجاه، ووافقه الذهبي.\n\nوقد روي حديث أبي رافع، بغير هذا اللفظ، من طرق. انظر الهيثمي في مجمع الزوائد ٤: ٤٢، ٤٣، ومسند أحمد ٦: ٨-١٠، ٣٩١.\n\nوقوله: \"عندها كلب ينبح عليها\"، أي: يرد عنها بنباحه ما تخاف من سبع، وينذرها بمجيء ضيف إن استروح رائحته. وجاء بيانه في الأثر الذي رواه أحمد في مسنده ٦: ٣٩١: \"قالت: إني امرأة مضيعة، وإن هذا الكلب يطرد عني السبع، ويؤذنني بالجائي\".]]\n\n١١١٣٥-حدثنا القاسم قال، حدثنا الحسين قال، حدثني حجاج، عن ابن جريج، عن عكرمة: أنّ النبي ﷺ بعث أبا رافع في قتل الكلاب، فقتل حتى بلغ العَوالي [[\"العوالي\": أماكن بأعلى أراضي المدينة، وأدناها من المدينة على أربعة أميال، وأبعدها من جهة نجد ثمانية أميال]] فدخل عاصم بن عدي، وسعد بن خيثمة، وعويم بن ساعدة، فقالوا: ماذا أحلَّ لنا يا رسول الله؟ فنزلت:\"يسألونك ماذا أحل لهم قل أحل لكم الطيبات وما علمتم من الجوارح مكلِّبين\".\n\n١١١٣٦- حدثنا المثنى قال، حدثنا إسحاق قال، حدثنا عبد الله بن الزبير قال، حدثونا عن محمد بن كعب القرظي قال: لما أمر النبي ﷺ بقتل الكلاب، قالوا: يا رسول الله، فماذا يحل لنا من هذه الأمة؟ فنزلت:\"يسألونك ماذا أحل لهم\"، الآية.\n\n* *\n\nثم اختلف أهل التأويل في\"الجوارح\" التي عنى الله بقوله:\"وما علمتم من الجوارح\".\n\nفقال بعضهم: هو كل ما عُلِّم الصيدَ فتعلّمه، من بهيمة أو طائر.\n\nذكر من قال ذلك:\n\n١١١٣٧- حدثنا ابن حميد قال، حدثنا ابن المبارك، عن إسماعيل بن مسلم، عن الحسن في قوله:\"وما علمتم من الجوارح مكلبين\"، قال: كل ما عُلِّم فصادَ، من كلب أو صقر أو فهدٍ أو غيره.\n\n١١١٣٨- حدثنا ابن وكيع قال، حدثنا ابن فضيل، عن إسماعيل بن مسلم، عن الحسن:\"مكلبين\"، قال: كل ما علم فصاد من كلب أو فهد أو غيره.\n\n١١١٣٩- حدثنا ابن حميد قال، حدثنا ابن المبارك، عن معمر، عن ابن أبي نجيح، عن مجاهد في صيد الفهد قال: هو من الجوارح.\n\n١١١٤٠- حدثنا ابن حميد قال، حدثنا حكام، عن عنبسة، عن محمد بن عبد الرحمن، عن القاسم بن أبي بزة، عن مجاهد في قوله:\"وما علمتم من الجوارح مكلبين\"، قال: الطير والكلاب.\n\n١١١٤١- حدثنا ابن وكيع قال، حدثنا أبو خالد الأحمر، عن الحجاج، عن عطاء، عن القاسم بن أبي بزة، عن مجاهد، مثله.\n\n١١١٤٢- حدثنا ابن وكيع قال، حدثنا ابن عيينة، عن حميد، عن مجاهد:\"مكلِّبيين\"، قال: من الكلاب والطير.\n\n١١١٤٣- حدثنا محمد بن عمرو قال، حدثنا أبو عاصم، عن عيسى، عن ابن أبي نجيح، عن مجاهد في قول الله:\"من الجوارح مكلبين\"، قال: من الطير والكلاب.\n\n١١١٤٤- حدثنا المثنى قال، حدثنا أبو حذيفة قال، حدثنا شبل، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١١١٤٥- حدثني يعقوب بن إبراهيم قال، حدثنا ابن علية قال، حدثنا شعبة = ح، وحدثنا ابن وكيع قال، حدثنا أبي، عن شعبة =، عن الهيثم، عن طلحة بن مصرف قال، قال خيثمة بن عبد الرحمن: هذا ما قد بيَّنت لك: أن الصقر والبازي من الجوارح. [[الأثر: ١١١٤٥، ١١١٤٦-\"الهيثم\" هو: \"الهيثم بن حبيب\"، وهو\"الهيثم بن أبي الهيثم\" الصيرفي الكوفي. أثنى عليه أحمد وقال: \"ما أحسن أحاديثه وأشد استقامتها\". مترجم في التهذيب.\n\nو\"طلحة بن مصرف الإيامي\"، مضى برقم: ٥٤٣١.\n\nو\"خيثمة بن عبد الرحمن بن أبي سبرة الجعفي\" تابعي ثقة، مضى برقم: ٨٢٦٧.]]\n\n١١١٤٦- حدثنا محمد بن المثنى قال، حدثنا محمد بن جعفر قال، حدثنا شعبة قال، سمعت الهيثم يحدث، عن طلحة الإيامي، عن خيثمة قال: بيّنت لك: [[في المطبوعة: \"أنبئت أن الصقر\"، وفي المخطوطة: \"أتيت لك أن الصقر\"، وكأن الصواب ما أثبت، استظهارًا من الأثر السالف.]] أن الصقر والباز والكلب من الجوارح. [[الأثر: ١١١٤٥، ١١١٤٦-\"الهيثم\" هو: \"الهيثم بن حبيب\"، وهو\"الهيثم بن أبي الهيثم\" الصيرفي الكوفي. أثنى عليه أحمد وقال: \"ما أحسن أحاديثه وأشد استقامتها\". مترجم في التهذيب.\n\nو\"طلحة بن مصرف الإيامي\"، مضى برقم: ٥٤٣١.\n\nو\"خيثمة بن عبد الرحمن بن أبي سبرة الجعفي\" تابعي ثقة، مضى برقم: ٨٢٦٧.]]\n\n١١١٤٧- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا عبد الله بن عمر، عن نافع، عن علي بن حسين قال: الباز والصقر من الجوارح.\n\n١١١٤٨- حدثنا ابن وكيع قال، حدثنا يحيى بن يمان، عن شريك، عن جابر، عن أبي جعفر قال: الباز والصقر من\"الجوارح المكلِّبين\". [[في المطبوعة: \"من الجوارح المكلبين\"، وأثبت ما في المخطوطة، وهو صواب.]] .\n\n١١١٤٩- حدثني المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"وما علمتم من الجوارح مكلبين\"، يعني بـ \"الجوارح\"، الكلابَ الضواريَ والفهود والصقور وأشباهها.\n\n١١١٥٠- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا معمر، عن ابن طاوس، عن أبيه:\"وما علمتم من الجوارح مكلبين\"، قال: من الكلاب، وغيرها من الصقور والبِيزان [[\"البيزان\" (بكسر الباء) جمع\"باز\"، بغير ياء في آخره، ويجمع أيضًا على\"أبواز\". وقولهم\"باز\" لغة في\"بازي\" وجمع\"بازي\"\"بزاة\" و\"بواز\"]] وأشباهِ ذلك مما يعلّم.\n\n١١١٥١- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قوله:\"وما علمتم من الجوارح مكلبين\"، الجوارح: الكلاب والصقور المعلَّمة.\n\n١١١٥٢- حدثني سعيد بن الربيع الرازيّ قال، حدثنا سفيان، عن عمرو بن دينار، سمع عبيد بن عمير يقول في قوله:\"من الجوارح مكلبين\"، قال: الكلاب والطير.\n\n* *\n\nوقال آخرون: إنما عنى الله جل ثناؤه بقوله:\"وما علمتم من الجوارح مكلبين\"، الكلابَ دون غيرها من السِّباع.\n\nذكر من قال ذلك:\n\n١١١٥٣- حدثنا ابن حميد قال، حدثنا أبو تميلة قال، حدثنا عبيد، عن الضحاك:\"وما علمتم من الجوار مكلبين\"، قال: هي الكلاب.\n\n١١١٥٤- حدثنا محمد بن الحسين قال، حدثنا أحمد بن مفضل قال، حدثنا أسباط، عن السدي قوله:\"وما علمتم من الجوارح مكلبين\"، يقول: أحل لكم صيد الكلاب التي علَّمتوهن.\n\n١١١٥٥- حدثنا هناد قال، حدثنا ابن أبي زائدة قال، أخبرنا ابن جريج، عن نافع، عن ابن عمر، قال: أمَّا ما صاد من الطير = والبُزاةُ من الطير = فما أدركت فهو لك، وإلا فلا تطعمه. [[في المطبوعة: \"فلا تطمعه\"، وهو خطأ في الطباعة]]\n\n* *\n\nقال أبو جعفر: وأولى القولين بتأويل الآية قول من قال:\"كل ما صاد من الطير والسباع فمن الجوارح، وأنّ صيد جميع ذلك حلال إذا صادَ بعد التعليم\"، لأن الله جل ثناؤه عم بقوله:\"وما علمتم من الجوارح مكلبين\"، كلَّ جارحة، ولم يخصص منها شيئًا. فكل\"جارحة\"، كانت بالصفة التي وصف الله من كل طائر وسبع، فحلال أكل صيدها.\n\n* *\n\nوقد روي عن النبيّ ﷺ بنحو ما قلنا في ذلك خبَرٌ، مع ما في الآية من الدلالة التي ذكرنا على صحة ما قلنا في ذلك، وهو ما:-\n\n١١١٥٦- حدثنا به هناد قال، حدثنا عيسى بن يونس، عن مجالد، عن الشعبي، عن عدي بن حاتم قال: سألت رسول الله ﷺ عن صيد البازي فقال: ما أمسك عليك فَكُل. [[الأثر: ١١١٥٦-\"هناد\" هو\"هناد بن السري بن مصعب الدارمي\"، ثقة. مضى برقم: ٢٠٥٨، ٢٧٥٨، ٢٩٩٨، ٣٩٦٠.\n\nو\"عيسى بن يونس بن أبي إسحق السبيعي\"، الفقيه ابن الفقيه ابن الفقيه، ثقة حافظ رضي، مات سنة ١٨٧. مترجم في التهذيب.\n\nو\"مجالد\" هو: \"مجالد بن سعيد بن عمير الهمداني\"، مضى برقم: ١٦١٤، ٢٩٨٧، ٢٩٨٨ وقد مضى أنه ثقة، ضعفه بعض الأئمة، وأن الراجح في شأنه، تصحيح حديث القدماء عنه، وأن أعدل ما قيل فيه، قول عبد الرحمن بن مهدي: \"حديث مجالد عند الأحداث، يحيى بن سعيد وأبي أسامة، ليس بشيء. ولكن حديث شعبة وحماد بن زيد وهشيم، وهؤلاء القدماء\"، وقول ابن أبي حاتم: \"يعني أنه تغير حفظه في آخر عمره. مات سنة ١٤٤\".\n\nوخبر الشعبي عن عدي بن حاتم، رواه مسلم والبخاري عن طريق زكريا بن أبي زائدة، عن الشعبي، عن عدي بن حاتم، أن عديا سأل رسول الله عن صيد الكلب. فقال: أمسك عليك فكل، الحديث (انظر سنن البيهقي ٩: ٢٣٥، ٢٣٦) .\n\nورواه الأئمة أيضًا من طريق عبد الله بن أبي السفر عن الشعبي، = ومن طريق عاصم الأحول، عن الشعبي = ومن طريق بيان عن الشعبي. ورووه أيضًا من طرق عن عدي بن حاتم، وليس فيها ذكر\"الباز\". (انظر السنن الكبرى للبيهقي ٩: ٢٣٥-٢٣٨) ، وانظر ما سيأتي رقم: ١١٢١٠.\n\nثم روى البيهقي بإسناده عن عبد الله بن نمير، عن مجالد، عن الشعبي، عن عدي بن حاتم: أن النبي ﷺ قال: ما علمت من كلب أو باز ثم أرسلته، وذكرت اسم الله، فكل مما أمسك عليك، الحديث. ثم قال البيهقي: \".. إلا أن ذكر البازي في هذه الرواية، لم يأت به الحفاظ الذين قدمنا ذكرهم عن الشعبي، وإنما أتى به مجالد، والله أعلم\".\n\nورواية عيسى بن يونس، عن مجالد، تعد من رواية القدماء عن مجالد قبل أن يتغير حفظه. وعيسى بن يونس ثقة ثبت، فكأن أبا جعفر صحح هذا الحديث واحتج به، لأنه رواية ثقة، عن ثقة قبل تغيره.]]\n\n* *\n\n= فأباح ﷺ صيد البازي وجعله من الجوارح. ففي ذلك دِلالة بيِّنة على فساد قول من قال:\"عنى الله بقوله:\"وما علمتم من الجوارح\"، ما علمنا من الكلاب خاصة، دون غيرها من سائر الجوارح\".\n\n* *\n\nفإن ظن ظانّ أن في قوله:\"مكلبين\"، دلالةً على أن الجوارح التي ذكرت في قوله:\"وما علمتم من الجوارح\"، هي الكلاب خاصة، فقد ظن غير الصواب.\n\nوذلك أن معنى الآية: قل أحِلَّ لكم، أيها الناس، في حال مصيركم أصحابَ كلاب = الطيباتُ، وصيدُ ما علمتوه الصيد من كواسب السباع والطير. فقوله:\"مكلبين\"، صفة للقانص، وإن صاد بغير الكلاب في بعض أحيانه. وهو نظير قول القائل يخاطب قومًا:\"أحلّ لكم الطيباتُ وما علمتم من الجوارح مكلبين مؤمنين\". فمعلوم أنه إنما عنى قائل ذلك، إخبارَ القوم أنّ الله جل ذكره أحل لهم، في حال كونهم أهلَ إيمان، الطيبات وصيد الجوارح التي أعلَمهم أنه لا يحل لهم منه إلا ما صادوه به [[في المطبوعة: \"ما صادوه بها\"، وما في المخطوطة صواب أيضًا.]] فكذلك قوله:\"أحل لكم الطيبات وما علمتم من الجوارح مكلبين\" لذلك نظيره، في أن التكليب للقانص = بالكلاب كان صيده أو بغيرها = لا أنه إعلام من الله عز ذكره أنه لا يحل من الصيد إلا ما صادته الكلاب.\n\n* *\n\nالقول في تأويل قوله: ﴿تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللَّهُ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"تعلمونهن\"، تؤدِّبون الجوارح فتعلمونهن طلب الصيد لكم =\"مما علمكم الله\"، يعني بذلك: من التأديب الذي أدَّبكم الله، والعلم الذي علمكم. [[انظر معاني القرآن للفراء ١: ٣٠٢.]]\n\n* *\n\nوقد قال بعض أهل التأويل: معنى قوله:\"مما علمكم الله\"، كما علمكم الله.\n\nذكر من قال ذلك:\n\n١١١٥٧- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"تعلمونهن مما علمكم الله\"، يقول: تعلمونهن من الطَّلب كما علمكم الله.\n\n* *\n\n= ولسنا نعرف في كلام العرب\"من\" بمعنى\"الكاف\"، لأن\"من\" تدخل في كلامهم بمعنى التبعيض، و\"الكاف\" بمعنى التشبيه. وإنما يوضع الحرف مكان آخر غيره، إذا تقارب معنياهما. فأما إذا اختلفت معانيهما، فغير موجود في كلامهم وضع أحدهما عَقِيب الآخر. وكتاب الله وتنزيله أحرَى الكلام أن يجنَّب ما خرج عن المفهوم والغاية في الفصاحة من كلام من نزل بلسانه........... . [[أرجح أنه قد سقط قبل هذا الخبر، كلام من كلام أبي جعفر، وذلك بدلالة قوله بعد: \"قيل: اختلف أهل التأويل في ذلك\". والذي أستظهره من كلامه في آخر سياقه هذه الأقوال من اختلاف الأئمة (ص: ٥٦٤) ، أن أبا جعفر ساق سؤالا كعادته، عن معنى\"تعليم الجوارح\"، ثم أجاب عنه بذكر اختلاف أهل التأويل. ولم أستجز أن أضع شيئًا مكان النقط التي وضعتها للدلالة على هذا السقط، لأني أخشى ان أخطئ في وصل الكلام بالخبر الذي رواه بعده برقم: ١١١٥٨\"انظر ص: ٥٥٣، تعليق: ٢، ٣.]]\n\n١١١٥٨- حدثنا أبو كريب قال، حدثنا إسماعيل بن صُبيح قال، حدثنا أبو هانئ عمر بن بشير قال، حدثنا عامر: أن عدي بن حاتم الطائي قال: أتى رجل رسول الله ﷺ يسأله عن صيد الكلاب، فلم يدر ما يقول له، حتى نزلت هذه الآية:\"تعلمونهن مما علمكم الله\". [[الأثر: ١١١٥٨-\"إسمعيل بن صبيح اليشكري\"، ثقة مضى برقم: ٢٩٩٦، ٨٦٤٠.\n\nو\"أبو هانئ\"\"عمر بن بشير الهمداني\"، قال أحمد: \"صالح الحديث\". وقال يحيى بن معين: \"ضعيف\". وذكره ابن حبان في الثقات، وقال أبو حاتم الرازي: \"ليس بقوي، يكتب حديثه، وجابر الجعفي أحب إلي منه\". وذكره ابن شاهين، والعقيلي في الضعفاء. مترجم في ابن أبي حاتم ٣/١/١٠٠، ولسان الميزان ٤: ٢٨٧، ومضى أيضًا برقم: ٤٤٢٢.\n\nوكان في المطبوعة: \"حدثنا أبو هانئ عن أبي بشر\"، وهو خطأ محض، وتغيير سيئ لما كان في المخطوطة: \"حدثنا أبو هانئ عمر بن بشر\"، والصواب ما أثبت.\n\nو\"عامر\" هو الشعبي.\n\nوهو حديث ضعيف لضعف\"أبي هانئ\". وخرجه السيوطي في الدر المنثور ٢: ٢٦٠، ونسبه أيضًا لعبد بن حميد، والقصة فيه: \"أن عدي بن حاتم الطائي، أتى رسول الله ﷺ\".]]\n\n* *\n\nقيل: اختلف أهل التأويل في ذلك. [[انظر التعليق السالف ص: ٥٥٢، تعليق: ٢، والتعليق التالي.]]\n\nفقال بعضهم [[في المخطوطة: \"فقال بعضهم هو جوارحًا صيدها، فقال لنا: وما علمتم من الجوارح مكلبين أن يستشلى ... \"، ووضع الناسخ بين\"هو\" و\"جوارحًا\" من فوق حرف\"لا\" وبعد\"مكلبين\" من فوق، حرف\"إلى\"، وهي طريقتهم قديمًا إذا أرادوا حذف ما بين\"لا\" و\"إلى\"، والظاهر أن قوله: \"جوارحا صيدها، فقال لنا: من الجوارح مكلبين\" هو بعض الجملة التي سقطت في موضع النقط التي وضعتها آنفًا، وأشرت إليها في التعليق السالف، وما قبله: ص ٥٥٢، تعليق: ٢.]] : هو أن يَسْتَشْلِي لطلب الصيد إذا أرسله صاحبه [[قوله: \"يستشلي\"، بالبناء للمعلوم، أراد به هنا: أن يغري بطلب الصيد. وقد ذكر أهل اللغة: \"أشلى الكلب واستشلاه\" إذا دعاه باسمه، وقد أنكر ثعلب أن\"أشلى الكلب\" بمعنى أغراه بالصيد، وأجازه غيره. ومن أجازه فقد أصاب، وقد قال الشافعي في الأم ٢: ١٩١:\n\n\"الكلب المعّلم: الذي إذَا أُشْلِيَ اسْتَشْلَى\"\n\nفاستعمل\"استشلى\" مطاوعًا لقوله: \"أشلى الكلب\" بمعنى: أغراه بالصيد. ثم عاد الشافعي فاستعمل\"استشلى الكلب\" بمعنى: \"أشلى الكلب\" غير مطاوع، فقال في الأم ٢: ١٩٢: \"وتعليمُ الطائر كلِّه واحد، البازي والصقر والشاهين وغيرها: وهو أن يجمع أن يُدْعَى فيجيب، ويُسْتَشْلَى فيطير\".\n\nثم عاد فاستعمل\"استشلى\" بالمعنيين جميعًا، مطاوعًا وغير مطاوع، في جملة طويلة في الأم ٢: ١٩٣ أثبت بعضها.:\n\n\" ... وإذا اسْتَشْلَى الرجُل كلبه على الصَّيْد -قريبًا كان منه أو بعيدًا- فانزجَرَ واسْتَشْلَى باستشلائه ... \".\n\nفصح بذلك ما استعمله أبو جعفر، هذا بخلاف ما جاء في الشعر، مما يسقط اعتراض ثعلب على\"أشلى\" بمعنى: أغرى.]] ويمسك عليه إذا أخذه فلا يأكل منه، ويستجيب له إذا دعاه، ولا يفرُّ منه إذا أراده. فإذا تتابع ذلك منه مرارًا كان\"معلَّمًا\". وهذا قول جماعة من أهل الحجاز وبعض أهل العراق.\n\nذكر من قال ذلك:\n\n١١١٥٩- حدثنا محمد بن بشار قال، حدثنا أبو عاصم قال، أخبرنا ابن جريج قال، قال عطاء: كل شيء قتله صائدك قبل أن يعلَّم ويُمسك ويصيد، فهو ميتة. ولا يكون قتله إياه ذكاة، حتى يعلَّم ويُمسك ويصيد. فإن كان ذلك ثم قتل، فهو ذكاته.\n\n١١١٦٠- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قال: إن المعلم من الكلاب: أن يمسك صيدَه فلا يأكل منه حتى يأتيه صاحبه. فإن أكل من صيده قبل أن يأتيه صاحبه فيدرك ذكاته، فلا يأكل من صيده.\n\n١١١٦١- حدثنا أبو كريب قال، حدثنا ابن عيينة، عن عمرو، عن طاوس، عن ابن عباس قال: إذا أكل الكلب فلا تأكل، فإنما أمسك على نفسه.\n\n١١١٦٢- حدثنا أبو كريب ويعقوب بن إبراهيم قالا حدثنا إسماعيل بن إبراهيم قال، حدثنا أبو المعلى، عن سعيد بن جبير قال، قال ابن عباس: إذا أرسل الرجل الكلبَ فأكل من صيده فقد أفسده، وإن كان ذكر اسم الله حين أرسله = فزعم أنه إنما أمسك على نفسه [[قوله: \"فزعم أنه إنما أمسك على نفسه\"، هذا من قول سعيد بن جبير، حكاية لقول ابن عباس. و\"زعم\" في هذا الموضع بمعنى: قال. لا بمعنى\"زعم\" فيما يذم من القول والظن. وهو يأتي كثيرًا في كلامهم، فاحفظه.]] = والله يقول:\"من الجوارح مكلّبين تعلمونهن مما علمكم الله\"، فزعم أنه إذا أكل من صيده قبل أن يأتيه صاحبه أنه ليس بمعلَّم، وأنه ينبغي أن يُضرب ويعلَّم حتى يترك ذلك الخُلُق. [[الأثر: ١١١٦٢-\"أبو المعلى\" العطار، هو: \"يحيى بن ميمون الضبي\"، ثقة كثير الحديث مترجم في التهذيب، وقد مضى في الإسنادين رقم: ٨٣٤٦، ٨٣٤٧.]]\n\n١١١٦٣- حدثنا أبو كريب قال، حدثنا معمر الرقي، عن حجاج، عن عطاء، عن ابن عباس قال: إذا أخذ الكلب فقَتل فأكل، فهو سَبُع. [[الأثر: ١١١٦٣-\"معمر الرقي\"، هو: \"معمر بن سلمان النخعي، الرقي\". وثقه أحمد. مترجم في التهذيب.]]\n\n١١١٦٤- حدثنا ابن المثنى قال، حدثني عبد الأعلى قال، حدثنا داود، عن عامر، عن ابن عباس قال: لا يأكل منه، فإنه لو كان معلَّمًا لم يأكل منه، ولم يتعلم ما علَّمتَه. إنما أمسك على نفسه، ولم يُمسك عليك.\n\n١١١٦٥- حدثنا ابن المثنى قال، حدثنا يزيد بن هارون قال، أخبرنا داود، عن الشعبي، عن ابن عباس، بنحوه.\n\n١١١٦٦- حدثنا محمد بن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن حماد، عن إبراهيم، عن ابن عباس قال: إذا أكل الكلب فلا تأكل. [[في المطبوعة: \"إذا أكلت الكلاب\" بالجمع، وأثبت ما في المخطوطة، وإن كان الناسخ كتب أولا: \"أكلت\" ثم عاد فمجمج الحروف حتى جعل اللام والتاء في\"أكلت\"\"أكل\".]]\n\n١١١٦٧- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن أبي إسحاق، عن الشعبي، عن ابن عباس، بمثله.\n\n١١١٦٨- حدثنا حميد بن مسعدة قال، حدثنا بشر بن المفضل قال، حدثنا ابن عون قال: قلت لعامر الشعبي: الرجل يرسل كلبَه فيأكل منه، أنأكل منه؟ قال: لا لم يتعلَّم الذي علَّمته.\n\n١١١٦٩- حدثنا أبو كريب قال، حدثنا ابن إدريس، عن ليث، عن مجاهد، عن ابن عمر قال: إذا أكل الكلب من صيده فاضربه، فإنه ليس بمعلَّم.\n\n١١١٧٠- حدثنا سوّار بن عبد الله قال، حدثنا يحيى بن سعيد، عن ابن جريج، عن ابن طاوس، عن أبيه قال: إذا أكل الكلب فهو ميتة، فلا تأكله.\n\n١١١٧١- حدثنا الحسن بن عرفة قال، حدثنا هشيم، عن أبي بشر، عن سعيد بن جبير = وسَيَّار، عن الشعبي = ومغيرة، عن إبراهيم = أنهم قالوا في الكلب إذا أكل من صيده: فلا تأكل، فإنما أمسك على نفسه.\n\n١١١٧٢- حدثنا ابن بشار قال، حدثنا أبو عاصم قال، أخبرنا ابن جريج قال، قال عطاء: إن وجدت الكلب قد أكل من الصيد، فما وجدتَه ميتًا فدعه، فإنه مما لم يمسك عليك صيدًا. إنما هو سبع أمسك على نفسه ولم يمسك عليك، وإن كان قد عُلِّم.\n\n١١١٧٣- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي، بنحوه.\n\n* *\n\nوقال آخرون نحو هذه المقالة، غير أنهم حَدُّوا لمعرفة الكلاب بأن كلبه قد قَبِل التعليم وصار من الجوارح الحلال صيدها [[\"الكلاب\" (بتشديد اللام) : هو صاحب الكلاب. و\"المكلب\" (بتشديد اللام المكسورة) : هو الذي يعلم الكلاب أخذ الصيد. ولكنه وضع\"الكلاب\" هنا موضع\"المكلب\". وهو جيد صحيح.]] أن يفعل ذلك كلبه مرات ثلاثًا. وهذا قول محكيٌّ عن أبي يوسف ومحمد بن الحسن.\n\n* *\n\nوقال آخرون ممن قال هذه المقالة: لا حدَّ لعلم الكلاب بذلك من كلبه، أكثر من أن يفعل كلبه ما وصفنا أنه له تعليم. قالوا: فإذا فعل ذلك فقد صار معلَّمًا حلالا صيده. وهذا قول بعض المتأخرين.\n\nوفرَّق بعض قائلي هذه المقالة بين تعليم البازي وسائر الطيور الجارحة وتعليم الكلب وضاري السبِّاع الجارحة، فقال: جائز أكل ما أكل منه البازي من الصيد. قالوا: وإنما تعليم البازي أن يطير إذا استُشْلِي، ويجيب إذا دُعِي، ولا ينفر من صاحبه إذا أراد أخذَه. قالوا: وليس من شروط تعليمه أن لا يأكل من الصيد.\n\nذكر من قال ذلك:\n\n١١١٧٤- حدثنا هناد بن السري قال، حدثنا هشيم، عن مغيرة، عن إبراهيم وحجاج، عن عطاء قال: لا بأس بصيد البازي وإن أكل منه.\n\n١١١٧٥- حدثنا أبو كريب قال، حدثنا أسباط قال، حدثنا أبو إسحاق الشيباني، عن حماد، عن إبراهيم، عن ابن عباس أنه قال في الطير: إذا أرسلتَه فقتل، فكُل. فإن الكلبَ إذا ضربته لم يَعُدْ. وإن تعليم الطير أن يرجع إلى صاحبه، وليس يضرب إذا أكل من الصيد ونتف من الريش. [[في المطبوعة: \"فإذا أكل من الصيد ونتف من الريش فكل\"، بزيادة\"فكل\"، عن المخطوطة، وكان فيها مثل ما في المطبوعة: \"فإذا أكل ... \"، ورجحت أن الصواب\"إذا أكل ... ، \" بحذف الفاء، ويستقيم الكلام على ما في الترجمة.]]\n\n١١١٧٦- حدثنا ابن حميد قال، حدثنا يحيى بن واضح قال، حدثنا أبو حمزة، عن جابر، عن الشعبي قال: ليس البازي والصقر كالكلب، فإذا أرسلتهما فأمسكا فأكلا فدعوتهما فأتياك، فكل منه.\n\n١١١٧٧- حدثنا هناد قال، حدثنا أبو زُبَيْد، عن مطرف، عن حماد، قال إبراهيم: كُلْ صيد البازي وإن أكل منه.\n\n١١١٧٨- حدثنا هناد قال، حدثنا وكيع، عن سفيان، عن حماد، عن إبراهيم = وجابر، عن الشعبي، قالا كُلْ من صيد البازِ وإن أكل. [[في المطبوعة: \"صيد البازي\" بالياء آخره، والذي في المخطوطة صواب. وانظر ما سلف ص: ٥٤٨، تعليق: ٤.]]\n\n١١١٧٩- حدثنا ابن حميد قال، حدثنا جرير، عن مغيرة، عن حماد، عن إبراهيم: إذا أكل البازي والصقر من الصيد، فكُل، فإنه لا يعلَّم. [[يعني: فإنه لا يعلم أن لا يأكل من الصيد كما يعلم الكلب.]]\n\n١١١٨٠- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن حماد، عن إبراهيم قال: لا بأس بما أكل منه البازي.\n\n١١١٨١- حدثنا ابن المثنى قال، حدثنا محمد بن جعفر قال، حدثنا شعبة، عن حماد: أنه قال في البازي إذا أكل منه، قال: كُلْ. [[في المطبوعة: \"إذا أكل منه فكل\"، وأثبت ما في المخطوطة، فهو صواب محض.]]\n\n* *\n\nوقال آخرون منهم: سواء تعليم الطير والبهائم والسباع، لا يكون نوع من ذلك معلَّمًا إلا بما يكون به سائر الأنواع معلَّمًا. وقالوا: لا يحل أكل شيء من الصيد الذي صادته جارحة فأكلت منه [[في المخطوطة: \"لا يجعل كل شيء من الصيد..\"، والصواب ما في المطبوعة.]] كائنة ما كانت تلك الجارحة، بهيمةً، أو طائرًا. [[في المخطوطة: \"بهيمة أو طائر\" بالرفع، والصواب، ما في المطبوعة.]] قالوا: لأن من شروط تعليمها الذي يحل به صيدها: أن تمسك ما صادت على صاحبها، فلا تأكل منه.\n\nذكر من قال ذلك:\n\n١١١٨٢- حدثنا هناد وأبو كريب قالا حدثنا ابن أبي زائدة قال، حدثنا محمد بن سالم، عن عامر قال: قال علي: إذا أكل البازي من صيده فلا تأكل. [[الأثر: ١١١٨٢-\"محمد بن سالم الهمداني\"، أبو سهل الكوفي. ضعيف الحديث متروك. مترجم في التهذيب. ومضى في الإسناد رقم: ٤٨٢٤.]]\n\n١١١٨٣- حدثنا ابن المثنى قال، حدثنا ابن جعفر، عن شعبة، عن مجاهد بن سعيد، عن الشعبي قال: إذا أكل البازي منه فلا تأكل.\n\n١١١٨٤- حدثنا هناد قال، حدثنا وكيع، عن سفيان، عن سالم، عن سعيد بن جبير قال: إذا أكل البازي فلا تأكل.\n\n١١١٨٥- حدثنا هناد قال، حدثنا وكيع، عن عمر بن الوليد الشنيّ قال: سمعت عكرمة قال: إذا أكل البازي فلا تأكل. [[الأثر: ١١١٨٥-\"عمر بن الوليد الشني\"، أبو سلمة العبدي، من عبد القيس. روى عن عكرمة، وشهاب بن عباد العصري. روى عنه وكيع، وأبو نعيم. قال أبو حاتم: \"ما أرى بحديثه بأسًا، وعامة حديثه عن عكرمة فقط، ما أقل ما يجاوز به إلى ابن عباس\". وقال يحيى القطان: \"ليس هو عندي ممن أعتمد عليه، ولكنه لا بأس به\". مترجم في ابن أبي حاتم ٣/١/١٣٩، ولسان الميزان ٤: ٣٣٧.\n\nوكان في المطبوعة: \"عمرو بن الوليد السهمي\"، وليس صوابًا، غير ما في المخطوطة وهو الذي أثبت.]]\n\n١١١٨٦- حدثنا ابن بشار قال، حدثنا أبو عاصم قال، أخبرنا ابن جريج قال، قال عطاء: الكلب والبازي كلُّه واحد، لا تأكل ما أكل منه من الصيد، إلا أن تدرك ذَكاته فتذكِّيه. قال: قلت لعطاء: البازي ينتف الريش؟ قال: فما أدركته ولم يأكل فكل. قال ذلك غير مرَّة.\n\n* *\n\nوقال آخرون: تعليم كل جارحة من البهائم والطير واحد. قالوا: وتعليمه الذي يحلُّ به صيده: أن يُشْلَى على الصيد فيَسْتَشلي ويأخذ الصيد [[انظر ما سلف ص: ٥٥٣، تعليق: ٤.]] ويدعوه صاحبه فيجيب، ولا يفرّ منه إذا أخذه. [[في المطبوعة والمخطوطة: \"أولا يفر منه\"، والصواب بالواو كما أثبته.]] قالوا: فإذا فعل الجارح ذلك كان\"معلمًا\" [[في المطبوعة والمخطوطة: \"قال\" بالإفراد، والذي قبله والذي بعده يقتضي أن تكون\"قالوا\".]] داخلا في المعنى الذي قال الله:\"وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما أمسكن عليكم\". قالوا: وليس من شرط تعليم ذلك أن لا يأكل من الصيد. قالوا: وكيف يجوز أن يكون ذلك من شرطه، وهو يؤدَّب بأكله؟\n\nذكر من قال ذلك:\n\n١١١٨٧- حدثنا ابن أبي الشوارب قال، حدثنا يزيد بن زريع قال، حدثنا سعيد، عن قتادة، عن سعيد = أو سعد =، عن سلمان قال: إذا أرسلت كلبك على صيد، وذكرتَ اسم الله، فأكل ثلثيه وبقي ثلثه، فكل ما بقي. [[الأثر: ١١١٨٧-\"سعيد\" الأول، هو\"سعيد بن أبي عروبة\".\n\nو\"سعيد\" الثاني، هو\"سعيد بن المسيب\".\n\nو\"سلمان\"، هو ابن الإسلام، \"سلمان الخير الفارسي\"، صاحب رسول الله ﷺ. وكان في المخطوطة في هذا الأثر، والذي يليه\"سليمان\"، ثم استقامت المخطوطة على الصواب. وسيأتي بعد الأثر رقم ١١٢١١، في تعقيب أبي جعفر أن سعيد بن المسيب، غير معلوم له سماع من سلمان الفارسي.\n\nأما قوله: \"أو سعد\"، فلم أعرف ما أراد به، ولم أعرف من يكون\"سعد\" الذي يروي عنه قتادة، والذي يروي عن سلمان. وسيأتي في الآثار التالية، رواية مثل ذلك عن\"سعد بن أبي وقاص\". فأخشى أن يكون في الإسناد تقديم وتأخير: \"قتادة، عن سعيد، عن سلمان، أو سعد\". وأنا في شك من ذلك أيضًا.\n\nوهذا الأثر رواه البيهقي في السنن ٩: ٢٣٧.]]\n\n١١١٨٨- حدثنا حميد بن مسعدة قال، حدثنا بشر بن المفضل قال، حدثنا حميد قال، حدثني القاسم بن ربيعة، عمن حدثه، عن سلمان = وبكر بن عبد الله، عمن حدثه، عن سلمان =: أن الكلب يأخذ الصيد فيأكل منه، قال: كل، وإن أكل ثلثيه، إذا أرسلته وذكرت اسم الله، وكان معلمًا. [[الأثر: ١١١٨٨-\"بكر بن عبد الله المزني\"، مضى برقم: ٤٨٧٧، ٤٨٧٨، ٨٩٣٦، ٩٧٣٢.\n\nوكان في هذا الموضع من المخطوطة أيضًا\"سليمان\"، وانظر التعليق على الأثر السالف.]]\n\n١١١٨٩- حدثنا ابن بشار وابن المثنى قالا حدثنا محمد بن جعفر قال، حدثنا شعبة قال، سمعت قتادة يحدث، عن سعيد بن المسيب قال، قال سلمان: كل وإن أكل ثلثيه = يعني: الصيدَ إذا أكل منه الكلب.\n\n١١١٩٠- حدثنا هناد قال، حدثنا وكيع، عن شعبة، عن قتادة، عن سعيد بن المسيب، عن سلمان، نحوه.\n\n١١١٩١- حدثنا ابن المثنى قال، حدثنا ابن أبي عدي وعبد العزيز بن عبد الصمد، عن شعبة = ح وحدثنا هناد قال، حدثنا عبدة = جميعًا، عن سعيد، عن قتادة: عن سعيد بن المسيب قال، قال سلمان: إذا أرسلت كلبك المعلَّم وذكرت اسمَ الله، فأكل ثلثيه وبقي ثلثه، فكل. [[في المطبوعة: \"فأكل ثلثه فكل\"، أسقط من الكلام ما ثبت في المخطوطة.]] .\n\n١١١٩٢- حدثنا هناد قال، حدثنا عبدة، عن سعيد، عن قتادة، عن سعيد، عن سلمان، نحوه.\n\n١١١٩٣- حدثنا مجاهد بن موسى قال، حدثنا يزيد، عن بكر بن عبد الله المزني والقاسم: أن سلمان قال: إذا أكل الكلب فكل، وإن أكل ثلثيه.\n\n١١١٩٤- حدثني يعقوب بن إبراهيم قال، حدثنا ابن علية، عن داود بن أبي الفرات، عن محمد بن زيد، عن سعيد بن المسيب قال: قال سلمان: إذا أرسلت كلبك المعلَّم أو بازَك، فسميَّت فأكل نصفه أو ثلثيه، فكل بقيَّته. [[الأثر: ١١١٩٤-\"داود بن أبي الفرات\" هو\"داود بن عمر بن الفرات الكندي\". ثقة، يروي عن\"محمد بن زيد بن علي الكندي\". مترجم في التهذيب، والكبير للبخاري ٢/١/٢١٥.\n\nو\"محمد بن زيد بن علي الكندي\" ويقال\"العبدي\"، قاضي مرو، ثقة صالح الحديث. مترجم في التهذيب، والكبير ١/١/٨٤.]]\n\n١١١٩٥- حدثني يونس بن عبد الأعلى قال، أخبرنا ابن وهب قال، أخبرني مخرمة بن بكير، عن أبيه، عن حميد بن مالك بن خثيم الدؤلي: أنه سأل سعد بن أبي وقاص عن الصيد يأكل منه الكلب، فقال: كل، وإن لم يبق منه إلا حِذْية - يعني: بَضْعة. [[الأثر: ١١١٩٥-\"مخرمة بن بكير بن عبد الله بن الأشج\"، مضى برقم: ٣٣٥٩.\n\nوأبوه\"بكير بن عبد الله بن الأشج\"، أو \"بكير بن الأشج\"، مضى برقم: ٢٧٤٧، و\"حميد بن مالك بن خثيم الدؤلي\" أو: \"حميد بن عبد الله بن مالك\" وسيأتي كذلك في الأثرين: ١١٢٠٧، ١١٢٠٨، تابعي ثقة، روى عن أبي هريرة وسعد بن أبي وقاص. مترجم في التهذيب.\n\nو\"الحذية\" و\"الحذوة\" (بكسر الحاء) : هو ما قطع من اللحم طولا، أو القطعة الصغيرة من اللحم. وأما \"البضعة\" فهي بفتح الباء وسكون الضاد. وكان في المخطوطة: \"يعني بعضه\"، والصواب ما في المطبوعة.]]\n\n١١١٩٦- حدثنا محمد بن المثنى قال، حدثني عبد الصمد قال، حدثنا شعبة، عن عبد ربه بن سعيد قال: سمعت بكير بن الأشج يحدّث، عن سعد قال: كُل، وإن أكل ثلثيه. [[الأثر: ١١١٦٩-\"عبد ربه بن سعيد بن قيس بن عمرو الأنصاري\"، روى عن جده قيس بن عمرو. ثقة. مترجم في التهذيب.]]\n\n١١١٩٧- حدثنا ابن المثنى قال، حدثنا سعيد بن الربيع قال، حدثنا شعبة، عن عبد ربه بن سعيد قال: سمعت بكير بن الأشج، عن سعيد بن المسيب = قال شعبة: قلت: سمعته من سعيد؟ قال: لا = قال: كل وإن أكل ثلثيه = قال: ثم إن شعبة قال في حديثه: عن سعد. قال: كل، وإن أكل نصفه.\n\n١١١٩٨- حدثنا ابن المثنى قال، حدثني عبد الأعلى قال، حدثنا داود، عن عامر، عن أبي هريرة قال: إذا أرسلت كلبك فأكل منه، فإن أكل ثلثيه وبقي ثلثه، فكل.\n\n١١١٩٩- حدثنا ابن المثنى قال، حدثنا يزيد بن هارون قال، أخبرنا داود بن أبي هند، عن الشعبي، عن أبي هريرة، بنحوه.\n\n١١٢٠٠- حدثنا هناد قال، حدثنا أبو معاوية، عن داود بن أبي هند، عن الشعبي، عن أبي هريرة، نحوه.\n\n١١٢٠١- حدثنا ابن المثنى قال، حدثني سالم بن نوح العطار، عن عمر= يعني: ابن عامر = عن قتادة، عن سعيد بن المسيب، عن سلمان قال: إذا أرسلت كلبك المعلَّم فأخذ فقتل، فكل، وإن أكل ثلثيه. [[الأثر: ١١٢٠١-\"سالم بن نوح العطار\" = و\"عمر بن عامر السلمي\"، مضيا برقم: ٢٨٥٢.]]\n\n١١٢٠٢- حدثنا محمد بن عبد الأعلى قال، حدثنا المعتمر قال، سمعت عبيد الله [[في المطبوعة: \"عبد الله\"، والصواب من المخطوطة، وهي غير منقوطة.]] = ح وحدثنا هناد قال، حدثنا عبدة، عن عبيد الله بن عمر= عن نافع، عن عبد الله بن عمر قال: إذا أرسلت كلبك المعلَّم وذكرت اسم الله، فكل ما أمسك عليك، أكل أو لم يأكل.\n\n١١٢٠٣- حدثنا ابن المثنى، قال، حدثنا عبد الوهاب قال، حدثنا عبيد الله، عن نافع، عن ابن عمر، بنحوه.\n\n١١٢٠٤- حدثنا يونس قال، أخبرنا ابن وهب قال، أخبرني ابن أبي ذئب: أن نافعًا حدَّثهم: أن عبد الله بن عمر كان لا يرى بأكل الصيد بأسًا، إذا قتله الكلب أكل منه.\n\n١١٢٠٥- حدثني يونس به مرة أخرى فقال، أخبرنا ابن وهب قال، حدثني عبيد الله بن عمرو، ابن أبي ذئب، وغير واحد: أن نافعًا حدَّثهم، عن عبد الله بن عمر، فذكر نحوه.\n\n١١٢٠٦- حدثنا ابن حميد قال، حدثنا يحيى بن واضح قال، حدثنا محمد بن أبي ذئب، عن نافع، عن ابن عمر: أنه كان لا يرى بأسًا بما أكل الكلبُ الضاري.\n\n١١٢٠٧- حدثنا هناد قال، حدثنا وكيع، عن ابن أبي ذئب، عن بكير بن عبد الله بن الأشج، عن حميد بن عبد الله، عن سعد قال: قلت لنا: كلاب ضوارٍ يأكلن ويبقين؟ قال: كل، وإن لم يبق إلا بَضْعة.\n\n١١٢٠٨- حدثنا هناد قال، حدثنا قبيصة، عن سفيان، عن ابن أبي ذئب، عن يعقوب بن عبد الله بن الأشج، عن حميد قال: سألت سعدًا، فذكر نحوه. [[الأثران: ١١٢٠٧، ١١٢٠٨-\"حميد بن عبد الله\"، هو\"حميد بن مالك بن خثيم\" الذي مضى في الأثر: ١١١٩٥، وانظر التعليق عليه هناك.\n\nو\"يعقوب بن عبد الله بن الأشج\" أخو\"بكير بن عبد الله بن الأشج\" الذي سلف برقم: ١١١٩٥ وهو ثقة. مترجم في التهذيب.]]\n\n* *\n\nقال أبو جعفر: وأولى الأقوال في ذلك بالصواب عندنا في تأويل قوله:\"تعلمونهن مما علمكم الله\": أن\"التعليم\" الذي ذكره الله في هذه الآية للجوارح، إنما هو أن يعلِّم الرجل جارحَه الاستشلاء إذا أُشلي على الصيد [[انظر القول في\"الإشلاء\" و\"الاستشلاء\" فيما سلف ص: ٥٥٣، تعليق: ٤.]] وطلبه إياه إذا أغرى، أو إمساكه عليه، إذا أخذه من غير أن يأكل منه شيئًا، وألا يفرّ منه إذا أراده، وأن يجيبه إذا دعاه. فذلك، هو تعليم جميع الجوارح، طيرها وبهائمها. فإن أكل من الصيد جارحةُ صائد [[في المطبوعة: \"وإن أكل ... \" بالواو، والجيد ما في المخطوطة، بالفاء.]] فجارحه حينئذ غير معلَّم. [[في المطبوعة: \"فجارحه\" بغير تاء التأنيث، والجيد ما في المخطوطة.]] فإن أدرك صيده صاحبُه حيًّا فذكّاه، حلَّ له أكله. وإن أدركه ميتًا، لم يحلَّ له أكله، لأنه مما أكله السَّبُع الذي حرمه الله تعالى بقوله: ﴿وَمَا أَكَلَ السَّبُعُ﴾ ، ولم يدرك ذكاته.\n\nوإنما قلنا: ذلك أولى الأقوال في ذلك بالصواب، لتظاهر الأخبار عن رسول الله ﷺ، بما:-\n\n١١٢٠٩- حدثنا به ابن حميد قال، حدثنا ابن المبارك، عن عاصم بن سليمان الأحول، عن الشعبي، عن عدي بن حاتم: أنه سأل النبي ﷺ عن الصيد فقال: إذا أرسلتَ كلبك فاذكر اسم الله عليه، فإن أدركته وقد قتل وأكل منه فلا تأكل منه شيئًا، فإنما أمسكَ على نفسه. \" [[الأثر: ١١٢٠٩- حديث صحيح. رواه البخاري (الفتح ٩: ٥٢٧) ، ومسلم ١٣: ٧٨، ٧٩، وأحمد في المسند ٤: ٢٥٧، ٣٧٩، وأبو داود في سننه ٣: ١٤٥ رقم: ٢٨٤٩، والبيهقي في السنن ٩: ٢٣٦، ٢٣٨، ٢٤٢، ٢٤٤ من طرق، مطولا.]]\n\n١١٢١٠- حدثنا أبو كريب وأبو هشام الرفاعي قالا حدثنا محمد بن فضيل، عن بيان بن بشر، عن عامر، عن عدي بن حاتم قال: سألت رسول الله ﷺ فقلت: إنا قوم نتصيَّد بهذه الكلاب؟ فقال: إذا أرسلت كلابَك المعلَّمة وذكرت اسم الله عليها، فكل ما أمسكن عليك وإن قتلن، إلا أن يأكل الكلبُ، فإن أكل فلا تأكل، فإني أخاف أن يكون إنما حَبَسه على نفسه. \" [[الأثر: ١١٢١٠- حديث صحيح. رواه البخاري من طريق قتيبة بن سعيد، عن محمد بن فضيل (الفتح ٩: ٥٢٧، ٥٢٨) ، ومسلم من طريق أبي بكر بن أبي شيبة، عن محمد بن فضيل ١٣: ٧٥، وأحمد في مسنده ٤: ٢٥٨، والبيهقي في السنن ٩: ٢٣٦، ٢٣٧، وأبو داود في سنن ٣: ١٤٥، رقم: ٢٨٤٨ مطولا.]]\n\n* *\n\nفإن قال قائل: فما أنت قائل فيما حدثك به:-\n\n١١٢١١- عمران بن بكّار الكلاعي قال، حدثنا عبد العزيز بن موسى قال، حدثنا محمد بن دينار، عن أبي إياس، عن سعيد بن المسيب، عن سلمان الفارسي، عن النبي ﷺ قال: إذا أرسل الرجل كلبه على الصيد فأدركه وقد أكل منه، فليأكل ما بقي. [[الأثر: ١١٢١١-\"عمران بن بكار الكلاعي\"، شيخ الطبري. مضى برقم: ١٤٩، ٢٠٧١.\n\nو\"عبد العزيز بن موسى بن روح اللاحوني\"، أبو روح، البهراني الحمصي. قال أبو حاتم: \"صدوق ثقة مأمون\". مترجم في التهذيب.\n\nو\"محمد بن دينار الأزدي الطاحي\"، وهو\"ابن أبي الفرات\"، و\"أبو بكر بن أبي الفرات\" قال النسائي: \"ليس به بأس\"، وقال في موضع آخر: \"ضعيف\"، وقال أبو داود: \"تغير قبل أن يموت\"، وقال الدارقطني: \"ضعيف\"، وقال مرة: \"متروك\". مترجم في التهذيب.\n\nو\"أبو إياس\"، هو\"معاوية بن قرة بن إياس المزني\"، تابعي ثقة. مترجم في التهذيب.\n\nوهذا الأثر قد تكلم الطبري في إسناده فيما يلي، ونقل ابن كثير في تفسيره ٣: ٧٥، ما قاله الطبري، ثم عقب عليه بقوله: \"وهذا الذي قاله ابن جرير صحيح، ولكن قد روي هذا المعنى مرفوعًا من وجوه أخر، فقال أبو داود: حدثنا محمد بن المنهال الضرير، حدثنا يزيد بن زريع، حدثنا حبيب المعلم، عن عمرو بن شعيب، عن أبيه، عن جده ... \" وساق حديث أبي داود في سننه ٣: ١٤٧، رقم: ٢٨٥٧، ثم قال ابن كثير: \"هكذا رواه أبو داود، وقد أخرجه النسائي. وكذا رواه أبو داود من طريق يونس بن سيف، عن أبي إدريس الخولاني، عن أبي ثعلبة ... \" ثم ساق حديث أبي داود في سننه ٣: ١٤٧، رقم: ٢٨٥٦، ثم قال: \"وهذان إسنادان جيدان\".]] قيل: هذا خبر في إسناده نظر، فإن\"سعيدًا\" غير معلوم له سماع من\"سلمان\"، والثقات من أهل الآثار يقفون هذا الكلام على سلمان، ويروونه عنه من قِبَله غير مرفوع إلى النبي ﷺ. والحفَّاظ الثقات إذا تتابعوا على نقل شيء بصفة، فخالفهم واحد منفردٌ ليس له حفظهم، كانت الجماعة الأثبات أحقَّ بصحة ما نقلوا من الفرد الذي ليس له حفظهم. [[انظر التعليق على الأثر السالف، رقم: ١١٢١١.]]\n\n* *\n\nقال أبو جعفر: وإذا كان الأمر في الكلب على ما ذكرتُ: من أنه إذا أكل من الصيد فغيرُ معلَّم، فكذلك حكم كل جارحة: في أن ما أكل منها من الصيد فغير معلَّم، لا يحل له أكل صيده إلا أن يدرك ذكاته.\n\n* *\n\nالقول في تأويل قوله: ﴿فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ﴾\n\nقال أبو جعفر: يعني بقوله:\"فكلوا مما أمسكن عليكم\"، فكلوا، أيها الناس، مما أمسكت عليكم جوارحكم.\n\n* *\n\nواختلف أهل التأويل في معنى ذلك.\n\nفقال بعضهم: ذلك على الظاهر والعموم كما عممه الله، حلال أكل كلِّ ما أمسكت علينا الكلاب والجوارح المعلَّمة من الصيد الحلال أكله، أكل منه الجارح والكلاب أو لم يأكل منه، أدركتْ ذكاته فذُكِّي أو لم تدرَك ذكاته حتى قتلته الجوارح بجرحها إياه أو بغير جَرْح.\n\nوهذا قول الذين قالوا:\"تعليم الجوارح الذي يحلّ به صيدها أن تعلَّم الاستشلاء على الصيد، وطلبه إذا أشْليت عليه، وأخذه، وترك الهرب من صاحبها، دون ترك الأكل من صيدها إذا صادته\". وقد ذكرنا قول قائلي هذه المقالة والرواية عنهم بأسانيدها الواردة آنفًا. [[انظر ما سلف من الآثار من رقم: ١١١٨٧، وما بعده.]]\n\n* *\n\nوقال آخرون: بل ذلك على الخصوص دون العموم. قالوا: ومعناه: فكلوا مما أمسكن عليكم من الصيد جميعه دون بعضه. قالوا: فإن أكلت الجوارح منه بعضًا وأمسكت بعضًا، فالذي أمسكت منه غير جائز أكلُه وقد أكلت بعضه، لأنها إنما أمسكت ما أمسكت من ذلك الصيد بعد الذي أكلت منه، على أنفسها لا علينا، والله تعالى ذكره إنما أباح لنا كلَ ما أمسكته جوارحنا المعلمة علينا بقوله:\"فكلوا مما أمسكن عليكم\"، دون ما أمسكته على أنفسها. وهذا قول من قال:\" تعليم الجوارح الذي يحلُّ به صيدها: أن تَستشلى للصيد إذا أشليت، فتطلبه وتأخذه، فتمسكه على صاحبها فلا تأكل منه شيئًا، ولا تفر من صاحبها\". وقد ذكرنا ممن قال ذلك فيما مضى منهم جماعة كثيرة [[انظر ما سلف من الآثار، من رقم: ١١١٨٢، وما بعده.]] ونذكر منهم جماعة أخَر في هذا الموضع. [[في المطبوعة: \"جماعة آخرين\"، وأثبت ما في المخطوطة.]]\n\n١١٢١٢- حدثنا المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"فكلوا مما أمسكن عليكم\"، يقول: كلوا مما قتلن = قال علي: وكان ابن عباس يقول: إن قتل وأكل فلا تأكل، وإن أمسك فأدركته حيًّا فذكِّه.\n\n١١٢١٣- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس قال: إن أكل المعلَّم من الكلاب من صيده قبل أن يأتيه صاحبه فيدرك ذكاته، فلا يأكل من صيده.\n\n١١٢١٤- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"فكلوا مما أمسكن عليكم\"، إذا صادَ الكلب فأمسكه وقد قتله ولم يأكل منه، فهو حِلٌّ. فإن أكل منه، فيقال: إنما أمسك على نفسه. [[في المخطوطة: \"إنما أمسك فلا تأكل......\" أسقط\"على نفسه\"، والصواب إثباتها كما في المطبوعة.]] فلا تأكل منه شيئًا، إنه ليس بمعلَّم.\n\n١١٢١٥- حدثنا بشر بن معاذ قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة:\"يسألونك ماذا أحل لهم\" إلى قوله:\"فكلوا مما أمسكن عليكم واذكروا اسم الله عليه\"، قال: إذا أرسلت كلبك المعلَّم أو طيرك أو سهمك، فذكرت اسم الله، فأخذ أو قتل، فكل.\n\n١١٢١٦- حدثت عن الحسين قال، سمعت أبا معاذ يقول، أخبرنا عبيد بن سليمان قال، سمعت الضحاك يقول: إذا أرسلت كلبك المعلّم فذكرت اسم الله حين ترسله، فأمسك أو قتل، فهو حلال. فإذا أكل منه فلا تأكله، فإنما أمسكه على نفسه.\n\n١١٢١٧- حدثنا القاسم قال، حدثنا الحسين قال، حدثنا أبو معاوية، عن عاصم، عن الشعبي، عن عديّ قوله:\"فكلوا مما أمسكن عليكم\"، قال: قلت يا رسول الله، إن أرضي أرضُ صيد؟ قال:\"إذا أرسلت كلبك وسميت، فكل مما أمسك عليك كلبُك وإن قتل. فإن أكل فلا تأكل، فإنه إنما أمسك على نفسه. [[الأثر: ١١٢١٧- حديث صحيح، أخرجه البخاري (الفتح ٩: ٥٢٧) ، نحوًا من لفظه. ورواه بهذا اللفظ مطولا، أحمد في مسنده ٤: ٢٥٧، وانظر التعليق على الأثر السالف رقم: ١١٢٠٩.]]\n\nوقد بينا أولى القولين في ذلك بالصواب قبلُ، فأغنى ذلك عن إعادته وتكراره. [[انظر ما سلف ص: ٥٦٤.]]\n\n* *\n\nفإن قال قائل: وما وجه دخول\"من\"، في قوله:\"فكلوا مما أمسكن عليكم\"، وقد أحل الله لنا صيد جوارحنا الحلالِ، و\"من\" إنما تدخل في الكلام مبعِّضَة لما دخلت فيه؟\n\nقيل: قد اختلف في معنى دخولها في هذا الموضع أهل العربية.\n\nفقال بعض نحويي البصرة: دخلت\"من\" في هذا الموضع لغير معنًى، كما تدخله العرب في قولهم:\"كان من مطر\" و\"كان من حديث\". قال: ومن ذلك قوله: ﴿وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئَاتِكُمْ﴾ [سورة البقرة: ٢٧١] ، وقوله: ﴿وَيُنزلُ مِنَ السَّمَاءِ مِنْ جِبَالٍ فِيهَا مِنْ بَرَدٍ﴾ [سورة النور: ٤٣] ، قال: وهو فيما فسِّر: وينزل من السماء جبالا فيها برد. قال: وقال بعضهم: و\"ينزل من السماء من جبال فيها من برد\"، أي: من السماء من برد، بجعل\"الجبال من برد\" في السماء، وبجعل الإنزال منها. [[انظر ما سلف ٢: ١٢٦، ١٢٧ / ٥: ٥٨٦/٦: ٥٥١/٧: ٤٨٩.]]\n\n* *\n\nوكان غيره من أهل العربية ينكر ذلك ويقول: لم تدخل\"من\" إلا لمعنى مفهوم، لا يجوز الكلام ولا يصلح إلا به. وذلك أنها دالة على التبعيض. وكان يقول: معنى قولهم\"قد كان من مطر\" و\"كان من حديث\"؛ هل كان من مَطَرِ مَطَرَ عندكم؟ وهل من حديث حُدِّث عندكم؟ [[في المطبوعة والمخطوطة: \"حديث حديث عندكم\"؛ والصواب ما أثبت. ويعني قائل ذلك أن قوله\"قد كان من مطر\" إلخ، إنما هو جواب لقول القائل: هل كان من مطر مطر عندكم؟]] ويقول: معنى: ﴿وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئَاتِكُمْ﴾ ، أي: ويكفر عنكم من سيِّئاتكم ما يشاء ويريد = وفي قوله: ﴿وَيُنزلُ مِنَ السَّمَاءِ مِنْ جِبَالٍ فِيهَا مِنْ بَرَدٍ﴾ ، فيجيز حذف\"من\" من\"من برد\" [[في المطبوعة والمخطوطة: \"حذف من من برد\"، والصواب زيادة\"من\" الثالثة كما أثبتها.]] ولا يجيز حذفها من\"الجبال\"، ويتأول معنى ذلك: وينزل من السماء أمثالَ جبالٍ بردٍ، ثم أدخلت\"من\" في\"البرد\"، لأن\"البرد\" مفسَّر عنده من\"الأمثال\" [[\"المفسر\": المميز. و\"التفسير\": التمييز. وانظر فهارس المصطلحات.]] أعني:\"أمثال الجبال\"، وقد أقيمت\"الجبال\" مقام\"الأمثال\"، و\"الجبال\" وهي\"جبال برد\" فلا يجيز حذف\"من\" من\"الجبال\"، لأنها دالة على أن الذي في السماء الذي أنزل منه البرد، أمثالُ جبال بردٍ. وأجاز حذف\"من\" من\"البرد\"، لأن\"البرد\" مفسَّر عن\"الأمثال\"، كما تقول:\"عندي رطلان زيتًا\" و\"عندي رطلان من زيت\"، وليس عندك\"الرطل\"، وإنما عندك المقدار. فـ\"من\" تدخل في المفسِّر وتخرج منه. وكذلك عند قائل هذا القول: من السماء، من أمثال جبال، وليس بجبال. وقال: وإن كان:\"أنزل من جبال في السماء من برد جبالا\"، ثم حذف\"الجبال\" الثانية، و\"الجبال\" الأول في السماء، جاز. تقول:\"أكلت من الطعام\"، تريد: أكلت من الطعام طعامًا، ثم تحذف\"الطعام\" ولا تسقط\"من\".\n\n* *\n\nقال أبو جعفر: والصواب من القول في ذلك: أن\"من\" لا تدخل في الكلام إلا لمعنى مفهوم، وقد يجوز حذفها في بعض الكلام وبالكلام إليها حاجة، لدلالة ما يظهر من الكلام عليها. فأما أن تكون في الكلام لغير معنى أفادته بدخولها، فذلك قد بيَّنا فيما مضى أنه غير جائز أن يكون فيما صحّ من الكلام. [[انظر المواضع السالفة التي أشرنا إليها في التعليق: ٢، ص ٥٦٩.]]\n\nومعنى دخولها في قوله:\"فكلوا مما أمسكن عليكم\"، للتبعيض، إذ كانت الجوارح تمسك على أصحابها ما أحل الله لهم لحومه، وحرَّم عليهم فَرْثه ودمَه، فقال جل ثناؤه:\"فكلوا\" = مما أمسكتْ عليكم جوارحكم [[في المطبوعة والمخطوطة: \"مما أمسكن عليكم جوارحكم\"، والصواب الجيد ما أثبت، إنما خلط النساخ بين (النون) ، و\"التاء\".]] = الطيبات التي أحللت لكم من لحومها، دون ما حرمت عليكم من خبائثه من الفرث والدم وما أشبه ذلك، مما لم أطيبه لكم. فذلك معنى دخول\"من\" في ذلك.\n\nوأما قوله: ﴿وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئَاتِكُمْ﴾ ، فقد بينا وجه دخولها فيه فيما مضى، بما أغنى عن إعادته. [[انظر ما سلف ٥: ٥٨٦، والمواضع الأخرى في التعليق السالف ص: ٥٦٩، رقم: ٢.]]\n\nوأما دخولها في قوله: ﴿وَيُنزلُ مِنَ السَّمَاءِ مِنْ جِبَالٍ﴾ ، فسنبينه إذا أتينا عليه إن شاء الله. [[انظر ج ١٨: ١١٨، ١١٩ (بولاق) من هذا التفسير، ولم يف أبو جعفر بما وعد، فلم يبينه بيانًا كافيًا حيث أشار إليه. وقد كان في المطبوعة هنا: \"إن شاء الله تعالى\". وأثبت ما في المخطوطة.]] .\n\n* *\n\nالقول في تأويل قوله: ﴿وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله: ﴿واذكروا اسم الله عليه﴾ [[في المطبوعة والمخطوطة: \"واذكروا اسم الله على ما أمسكت ... \" والصواب إثبات\"عليه\" من تمام الآية، وما بعده تفسير قوله: \"عليه\".]] على ما أمسكت عليكم جوارحكم من الصيد. كما:-\n\n١١٢١٨- حدثنا المثنى قال، حدثنا عبد الله قال، حدثني معاوية، عن علي، عن ابن عباس قوله:\"واذكروا اسم الله عليه\"، يقول: إذا أرسلت جوارحك فقل:\"بسم الله\"، وإن نسيت فلا حَرَج.\n\n١١٢١٩- حدثنا محمد قال، حدثنا أحمد قال، حدثنا أسباط، عن السدي قوله:\"واذكروا اسم الله عليه\"، قال: إذا أرسلته فسَمِّ عليه حين ترسله على الصيد.\n\n* *\n\nالقول في تأويل قوله: ﴿وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ (٤) ﴾\n\nقال أبو جعفر: يعني جل ثناؤه: واتقوا الله، أيها الناس، فيما أمركم به وفيما نهاكم عنه، فاحذروه في ذلك أن تقدموا على خلافه، وأن تأكلوا من صيد الجوارح غير المعلَّمة، أو مما لم تمسك عليكم من صيدها وأمسكته على أنفسها، أو تطعَمُوا ما لم يسمَّ الله عليه من الصيد والذبائح مما صادَه أهل الأوثان وعبدة الأصنام ومن لم يوحِّد الله من خلقه، أو ذبحوه، فإن الله قد حرَّم ذلك عليكم فاجتنبوه.\n\nثم خوَّفهم إن هم فعلوا ما نهاهم عنه من ذلك ومن غيره. فقال: اعلموا أن الله سريعٌ حسابه لمن حاسبه على نِعَمه عليه منكم [[في المطبوعة: \"على نعمته ... \"، وأثبت ما في المخطوطة.]] وشكرِ الشاكر منكم ربَّه على ما أنعم به عليه بطاعته إياه فيما أمر ونهى، لأنه حافظ لجميع ذلك فيكم، فيحيط به، لا يخفى عليه منه شيء، فيجازي المطيعَ منكم بطاعته، والعاصيَ بمعصيته، وقد بيَّن لكم جزاء الفريقين. [[انظر تفسير\"سريع الحساب\" فيما سلف ٧: ٥٠١، تعليق: ٣، والمراجع هناك.]]\n\n* *\n\nالقول في تأويل قوله: ﴿الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ﴾\n\nقال أبو جعفر: يعني جل ثناؤه بقوله:\"اليوم أحل لكم الطيبات\"، اليوم أحل لكم، أيها المؤمنون، الحلالُ من الذبائح والمطاعم دون الخبائث منها.\n\nوقوله:\"وطعام الذين أوتوا الكتاب حلٌّ لكم\"، وذبائحُ أهل الكتاب من اليهود والنصارى = وهم الذين أوتوا التوراة والإنجيل وأنزل عليهم، فدانُوا بهما أو بأحدهما =\"حل لكم\" [[انظر تفسير\"حل\" و\"حلال\" فيما سلف ٣: ٣٠٠، ٤٨٧.]] يقول: حلالٌ لكم، أكله دون ذبائح سائر أهل الشرك الذين لا كتاب لهم من مشركي العرب وعبدة الأوثان والأصنام. فإن من لم يكن منهم مِمَّن أقرَّ بتوحيد الله عزَّ ذكره ودان دين أهل الكتاب، فحرام عليكم ذبائحهم.\n\n* *\n\nثم اختلف فيمن عنى الله عز ذكره بقوله:\"وطعام الذين أوتوا الكتاب\"، من أهل الكتاب.\n\nفقال بعضهم: عنى الله بذلك ذبيحة كل كتابي ممن أنزل عليه التوراة والإنجيل، أو ممن دخل في مِلَّتهم فدان دينهم، وحرَّم ما حرَّموا، وحلَّل ما حللوا، منهم ومن غيرهم من سائر أجناس الأمم.\n\nذكر من قال ذلك:\n\n١١٢٢٠- حدثنا محمد بن عبد الملك بن أبي الشوارب قال، حدثنا عبد الواحد قال، حدثنا خصيف قال، حدثنا عكرمة قال، سئل ابن عباس عن ذبائح نصارى بني تغلب، فقرأ هذه الآية: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا الْيَهُودَ﴾ إلى قوله: ﴿وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ﴾ ، الآية [سورة المائدة: ٥١] . [[الأثر: ١١٢٢٠- هذا الأثر مؤخر بعد الذي يليه في المخطوطة، فلا أدري أهو مؤخر، أم سقط قبل الأثر رقم ١١٢٢١، أثر آخر، فاجتهد ناشر الكتاب أو ناسخ سابق، فقدم وأخر.]]\n\n١١٢٢١- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان: عن عاصم الأحول، عن عكرمة، عن ابن عباس، مثله.\n\n١١٢٢٢- حدثنا ابن بشار قال، حدثنا ابن عثمة قال، حدثنا سعيد بن بشر، عن قتادة، عن الحسن وعكرمة: أنهما كانا لا يريان بأسًا بذبائح نصارى بني تغلب، وبتزوُّج نسائهم، ويتلوان: ﴿وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ﴾ .\n\n١١٢٢٣- حدثنا ابن بشار قال، حدثنا ابن أبي عدي، عن سعيد، عن قتادة، عن الحسن وسعيد بن المسيب: أنهما كانا لا يريان بأسًا بذبيحة نصارى بني تغلب.\n\n١١٢٢٤- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن أبي حصين، عن الشعبي: أنه كان لا يرى بأسًا بذبائح نصارى بني تغلب، وقرأ: ﴿وَمَا كَانَ رَبُّكَ نَسِيًّا﴾ ، [سورة مريم: ٦٤] .\n\n١١٢٢٥- حدثني ابن بشار وابن المثنى قالا حدثنا أبو عاصم قال، أخبرنا ابن جريج قال، حدثني ابن شهاب عن ذبيحة نصارى العرب، قال. تؤكل من أجل أنهم في الدين أهلُ كتاب، ويذكرون اسمَ الله.\n\n١١٢٢٦- حدثنا ابن بشار وابن المثنى قالا حدثنا أبو عاصم قال، حدثنا ابن جريج قال، قال عطاء: إنما يقرُّون بدين ذلك الكتاب. [[في المطبوعة: \"إنما يقرأون ذلك الكتاب\"، وفي المخطوطة: \"إنما يقرون بين ذلك\" ورأيت أن صواب قراءتها كما أثبت، أي: أنهم يدينون بدين ذلك الكتاب.]]\n\n١١٢٢٧- حدثنا يعقوب بن إبراهيم قال، حدثنا ابن علية قال، حدثنا شعبة قال: سألت الحكم وحمادًا وقتادة عن ذبائح نصارى بني تغلب، فقالوا: لا بأس بها. قال: وقرأ الحكم: ﴿وَمِنْهُمْ أُمِّيُّونَ لا يَعْلَمُونَ الْكِتَابَ إِلا أَمَانِيَّ﴾ ، [سورة البقرة: ٧٨] .\n\n١١٢٢٨- حدثني المثنى قال، حدثنا الحجاج قال، حدثنا حماد، عن عطاء بن السائب، عن عكرمة، عن ابن عباس قال: كلوا من ذبائح بني تغلب، وتزوَّجوا من نسائهم، فإن الله قال في كتابه: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَتَّخِذُوا الْيَهُودَ وَالنَّصَارَى أَوْلِيَاءَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَمَنْ يَتَوَلَّهُمْ مِنْكُمْ فَإِنَّهُ مِنْهُمْ﴾ [سورة المائدة: ٥١] ، فلو لم يكونوا منهم إلا بالولاية، لكانوا منهم.\n\n١١٢٢٩- حدثني يعقوب بن إبراهيم، قال، حدثنا ابن علية، عن ابن أبي عروبة، عن قتادة: أن الحسن كان لا يرى بأسًا بذبائح نصارى بني تغلب، وكان يقول: انتحلوا دينًا، فذاك دينهم.\n\n* *\n\nوقال آخرون: إنما عنى بالذين أوتوا الكتاب في هذه الآية، الذين أنزل عليهم التوراة والإنجيل من بني إسرائيل وأبنائهم، فأما من كان دخيلا فيهم من سائر الأمم ممن دان بدينهم وهم من غير بني إسرائيل، فلم يعن بهذه الآية، وليس هو ممن يحل أكل ذبائحه، لأنه ليس ممن أوتي الكتاب من قَبْل المسلمين. وهذا قول كان محمد بن إدريس الشافعي يقوله = حدثنا بذلك عنه الربيع = ويتأول في ذلك قول من كره ذبائح نصارى العرب من الصحابة والتابعين. [[انظر الأم ٢: ١٩٦.]]\n\n* *\n\nذكر من حرَّم ذبائح نصارى العرب.\n\n١١٢٣٠- حدثنا يعقوب بن إبراهيم قال، حدثنا ابن علية، عن أيوب، عن محمد، عن عبيدة قال، قال علي رضوان الله عليه: لا تأكلوا ذبائح نصارى بني تغلب، فإنهم إنما يتمسكون من النصرانية بشرب الخمر. [[الأثر: ١١٢٣٠- رواه الشافعي في الأم ٢: ١٩٦، والبيهقي في السنن ٩: ٢٨٤، وأشار إليه الحافظ ابن حجر في (الفتح ٩: ٥٤٩) ، وقال: \"أخرجه الشافعي وعبد الرزاق بأسانيد صحيحة\".]]\n\n١١٢٣١- حدثنا يعقوب قال، حدثنا هشيم قال، أخبرنا هشام، عن ابن سيرين، عن عبيدة، عن علي قال: لا تأكلوا ذبائح نصارى بني تغلب، فإنهم لم يتمسكوا بشيء من النصرانية إلا بشرب الخمر.\n\n١١٢٣٢- حدثنا الحسن بن عرفة قال، حدثنا عبد الله بن بكر قال، حدثنا هشام، عن محمد بن سيرين، عن عبيدة قال: سألت عليًّا عن ذبائح نصارى العرب، فقال: لا تؤكل ذبائحهم، فإنهم لم يتعلَّقوا من دينهم إلا بشرب الخمر.\n\n١١٢٣٣- حدثني علي بن سعيد الكندي قال، حدثنا علي بن عابس، عن عطاء بن السائب، عن أبي البختري قال: نهانا عليٌّ عن ذبائح نصارى العرب. [[الأثر: ١١٢٣٣-\"علي بن سعيد بن مسروق الكندي\"، مضى برقم: ١١٨٤، ٢٧٨٤.\n\nو\"علي بن عابس الأسدي\"، ضعيف، يعتبر به. مترجم في التهذيب.\n\nو\"أبو البختري\"، هو: \"سعيد بن فيروز الطائي\" مضى برقم: ١٧٥، ١٤٩٧.]]\n\n١١٢٣٤- حدثنا ابن المثنى قال، حدثنا محمد بن جعفر قال، حدثنا شعبة، عن أبي حمزة القصاب قال: سمعت محمد بن علي يحدث، عن علي: أنه كان يكره ذبائح نصارى بني تغلب.\n\n١١٢٣٥- حدثنا ابن حميد قال، حدثنا جرير، عن ليث، عن سعيد بن جبير، عن ابن عباس قال، لا تأكلوا ذبائح نصارى العرب، وذبائح نصارى أرْمينية.\n\n* *\n\nقال أبو جعفر: وهذه الأخبار عن عليّ رضوان الله عليه، إنما تدل على أنه كان ينهى عن ذبائح نصارى بني تغلب، من أجل أنهم ليسوا على النصرانية، لتركهم تحليل ما تحلِّل النصارى، وتحريم ما تُحَرّم، غير الخمر. ومن كان منتحلا [[في المطبوعة والمخطوطة: \"من كان منتحلا ... \" بغير واو في أوله الكلام، وهو فساد، والصواب إثباتها.]] ملّة هو غير متمسك منها بشيء فهو إلى البراءة منها أقرب منه إلى اللحاق بها وبأهلها. [[في المخطوطة والمطبوعة: \"فهو إلى البراءة منها أقرب إلى اللحاق ... \"، بإسقاط\"منه\"، وهو اختلال شديد، والصواب إثباتها.]] فلذلك نهى عليٌّ عن أكل ذبائح نصارى بني تغلب، لا من أجل أنهم ليسوا من بني إسرائيل.\n\nفإذ كان ذلك كذلك، وكان إجماعًا من الحجة أن لا بأس بذبيحة كل نصرانيّ ويهوديّ دان دين النصرانيّ أو اليهودي [[في المطبوعة: \"وكان إجماعًا من الحجة إحلال ذبيحة كل نصراني ويهودي انتحل دين النصارى أو اليهودي، فأحل ... \"، لم يحسن قراءة المخطوطة، فوضع مكان ما حذف منها ما وضع. وكان في المخطوطة: \"وكان إجماعًا من الحجة ألا بأس فذبيحة كل نصراني ويهودي دان دين النصراني أو اليهودي\"، وظاهر أن صواب قراءة صدر هذه الجملة هو ما أثبته، وهو مطابق لما جاء في الآثار السالفة من ١١٢٢٢-١١٢٢٩.]] فأحل ما أحلُّوا، وحرَّم ما حرموا، من بني إسرائيل كان أو من غيرهم = [[السياق: وإذ كان ذلك كذلك، وكان إجماعًا من الحجة ... فبين خطأ ما قال الشافعي ...]] فبيِّنٌ خطأ ما قال الشافعي في ذلك، وتأويله الذي تأوّله في قوله:\"وطعام الذين أوتوا الكتاب حِلٌّ لكم\"، أنه ذبائح الذين أوتوا الكتابَ التوراةَ والإنجيلَ من بني إسرائيل = [[السياق: فبين خطأ ما قال الشافعي ... وصواب ما خالف تأويله ذلك.]] وصوابُ ما خالف تأويله ذلك، وقولِ من قال: إن كل يهودي ونصراني فحلال ذبيحتُه، من أيِّ أجناس بني آدم كان.\n\n* *\n\nوأمَّا\"الطعام\" الذي قال الله:\"وطعام الذين أوتوا الكتاب\"، فإنه الذبائح.\n\n* *\n\nوبمثل ما قلنا في ذلك قال أهل التأويل.\n\nذكر من قال ذلك:\n\n١١٢٣٦- حدثنا أبو كريب وابن وكيع قالا حدثنا ابن إدريس، عن ليث، عن مجاهد:\"وطعام الذين أوتوا الكتاب حلّ لكم\"، قال: الذبائح.\n\n١١٢٣٧- حدثنا ابن حميد قال: حدثنا حكام، عن عنبسة، عن محمد بن عبد الرحمن، عن القاسم بن أبي بزة، عن مجاهد في قوله:\"وطعام الذين أوتوا الكتاب حل لكم\"، قال: ذبائحهم.\n\n١١٢٣٨- حدثنا محمد بن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن ليث، عن مجاهد، مثله.\n\n١١٢٣٩- حدثنا المثنى قال، حدثنا أبو نعيم وقبيصة قالا حدثنا سفيان، عن ليث، عن مجاهد، مثله.\n\n١١٢٤٠- حدثنا ابن وكيع قال، حدثنا إسحاق بن سليمان الرازي، عن أبي سنان، عن ليث، عن مجاهد، مثله. [[الأثر: ١١٢٤٠-\"إسحق بن سليمان الرازي العبدي، سلف برقم: ٦٤٥٦.\n\nو\"أبو سنان\" هو: \"سعيد بن سنان الشيباني\"، مضى برقم: ١٧٥.]]\n\n١١٢٤١- حدثنا محمد بن عمرو قال، حدثنا أبو عاصم، عن عيسى، عن ابن أبي نجيح، عن مجاهد، مثله.\n\n١١٢٤٢- حدثني المثنى قال، حدثنا أبو حذيفة، قال: حدثنا شبل، عن ابن أبي نجيح، عن مجاهد:\"وطعام الذين أوتوا الكتاب حل لكم\"، قال: ذبيحة أهل الكتاب.\n\n١١٢٤٣- حدثنا يعقوب بن إبراهيم قال، حدثنا هشيم، عن مغيرة، عن إبراهيم في قوله:\"وطعام الذين أوتوا الكتاب حل لكم\"، قال: ذبائحهم.\n\n١١٢٤٤- حدثنا ابن بشار قال، حدثنا عبد الرحمن قال، حدثنا سفيان، عن المغيرة، عن إبراهيم، بمثله.\n\n١١٢٤٥- حدثنا ابن وكيع قال، حدثنا أبي، عن سفيان، عن مغيرة، عن إبراهيم، مثله.\n\n١١٢٤٦- حدثنا الحسن بن يحيى قال، أخبرنا عبد الرزاق قال، أخبرنا الثوري، عن مغيرة، عن إبراهيم، مثله.\n\n١١٢٤٧- حدثنا المثنى قال، حدثنا أبو نعيم وقبيصة قالا حدثنا سفيان، عن مغيرة، عن إبراهيم، مثله.\n\n١١٢٤٨- حدثنا المثنى قال، حدثنا عبد الله بن صالح قال، حدثني معاوية، عن علي بن أبي طلحة، عن ابن عباس:\"وطعام الذين أوتوا الكتاب حل لكم\"، قال: ذبائحهم.\n\n١١٢٤٩- حدثني المثنى قال، حدثنا المعلى بن أسد قال، حدثنا خالد، عن يونس، عن الحسن، مثله. [[الأثر: ١١٢٤٩-\"المعلى بن أسد العمي\" الحافظ الثقة، روى عنه البخاري، والباقون بالواسطة. مترجم في التهذيب، ومضى غير مترجم برقم: ٧٢٣٢.]]\n\n١١٢٥٠- حدثنا بشر قال، حدثنا يزيد قال، حدثنا سعيد، عن قتادة قوله:\"وطعام الذين أوتوا الكتاب حل لكم\"، أي: ذبائحهم.\n\n١١٢٥١- حدثنا محمد بن الحسين قال، حدثنا أحمد بن المفضل قال، حدثنا أسباط، عن السدي:\"وطعام الذين أوتوا الكتاب حل لكم\"، أما طعامهم، فهو الذبائح.\n\n١١٢٥٢- حدثت عن الحسين قال، سمعت أبا معاذ يقول، حدثنا عبيد قال، سمعت الضحاك يقول في قوله:\"وطعام الذين أوتوا الكتاب حل لكم\"، قال: أحل الله لنا طعامهم ونساءَهم.\n\n١١٢٥٣- حدثني محمد بن سعد قال، حدثني أبي قال، حدثني عمي قال، حدثني أبي، عن أبيه، عن ابن عباس: أما قوله:\"وطعام الذين أوتوا الكتاب حل لكم\"، فإنه أحلَّ لنا طعامهم ونساءهم.\n\n١١٢٥٤- حدثني يونس قال، أخبرنا ابن وهب قال، سألته = يعني ابن زيد = [[في المطبوعة: \"يعني ابن يزيد\"، وهو خطأ، محض، وهو إسناد دائر في التفسير.]] عما ذبح للكنائس وسُمِّي عليها، فقال: أحل الله لنا طعام أهل الكتاب، ولم يستثن منه شيئًا.\n\n١١٢٥٥- حدثني يونس قال، أخبرنا ابن وهب قال، حدثني معاوية، عن أبي الزاهرية حدير بن كريب، = عن أبي الأسود، عن عُمَير بن الأسود: أنه سأل أبا الدرداء عن كبش ذُبح لكنيسة يقال لها\"جرجس\"، أهدوه لها، أنأكل منه؟ فقال أبو الدرداء: اللهم عفوًا! إنما هم أهل كتاب، طعامهم حلٌّ لنا، وطعامنا حل لهم! وأمره بأكله. [[الأثر: ١١٢٥٥-\"معاوية\"، هو\"معاوية بن صالح بن حدير الحمصي الحضرمي\"، مضى برقم: ١٨٦، ١٨٧، ٢٠٧٢، ٨٤٧٢.\n\nو\"أبو الزاهرية\"، وهو\"حدير بن كريب الحضرمي = أو الحميري\". روى عن حذيفة، وأبي الدرداء، وعبد الله بن عمرو بن العاص، وغيرهم من الصحابة. روى عنه معاوية بن صالح، وغيره. قال ابن سعد: \"وكان ثقة إن شاء الله، كثير الحديث\". مترجم في التهذيب، والكبير ٢/١/٩١.\n\nوفي هذا الإسناد إشكال. فإن ظاهره أن أبا الزاهرية حدير بن كريب، روى الأثر عن\"أبي الأسود، عن عمير بن الأسود\"، وهذا محال. فإن أبا الزاهرية يروي مباشرة عن أبي الدرداء. فأكبر ظني أن في أصول التفسير سقطًا أو خرمًا في هذا الموضع، وأن الإسناد انتهى عند قوله\"حدير بن كريب\" وسقط أثر حدير بن كريب عن أبي الدرداء، وبدأ إسناد آخر -لا ندري ما هو- ينتهي إلى أبي الأسود عن عمير بن الأسود، أنه سأل أبا الدرداء ... إلخ. وسيظهر صواب ذلك فيما يأتي.\n\nو\"أبو الأسود\" في هذا الإسناد التالي، لم أعرف من يكون فيمن يكنى بأبي الأسود.\n\nوأما \"عمير بن الأسود العنسي\"، فزعم ابن حجر، أنه هو\"عمرو بن الأسود\" وبذلك ترجم له في التهذيب (٨: ٤) وأنهما رجل واحد، وقال: روى عن عمر، وابن مسعود، ومعاذ بن جبل، وعبادة بن الصامت، وغيرهم من الصحابة. وقال ابن أبي حاتم ٣/١/٣٧٥: \"عمير بن الأسود العنسي الشامي\"، سمع عبادة، وأبا الدرداء، وأم حرام. روى عنه خالد بن معدان، سمعت أبي يقول ذلك\". وترجم أيضًا\"عمرو بن الأسود القيسي\"، وقال: \"روى عن عمر بن الخطاب، وابن مسعود، وعبادة بن الصامت. روى عنه مجاهد، وخالد بن معدان ... \"، ففرق تفريقًا ظاهرًا بين\"عمرو بن الأسود القيسي\"، و\"عمير بن الأسود العنسي\".\n\nوكذلك فعل ابن سعد في الطبقات ٧/٢/١٥٣، ففرق بينهما قال: \"عمير بن الأسود: سأل أبا الدرداء عن طعام أهل الكتاب. وروى عن معاذ بن جبل، وكان قليل الحديث ثقة\".\n\nثم عقد ترجمة أخرى: \"وعمرو بن الأسود السكوني: روى عن عمر ومعاذ، وله أحاديث\".\n\nفلا أدري من أين جعلهما الحافظ ابن حجر، رجلا واحدًا!!\n\nوقد ثبت بما رواه ابن سعد، أن هذا الأثر، إنما هو من حديث عمير بن الأسود، أنه سأل: أبا الدرداء، وأنه حديث آخر، غير حديث حدير بن كريب أبي الزاهرية.\n\nهذا، ولم أجد هذا الأثر -أو هذين الأثرين- في مكان آخر، وقد أغفل ابن كثير روايته في تفسيره، وأغفله أيضًا السيوطي في الدر المنثور. وكتبه: محمود محمد شاكر.]] وأما قوله:\"وطعامكم حل لهم\"، فإنه يعني: ذبائحكم، أيها المؤمنون، حِلٌّ لأهل الكتاب."]]);
